insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ اصْطَفَى مِنْ وُلْدِ إِبْرَاهِيمَ إِسْمَعِيلَ، وَاصْطَفَى مِنْ وُلْدِ إِسْمَعِيلَ بَنِي كِنَانَةَ، وَاصْطَفَى مِنْ بَنِي كِنَانَةَ قُرَيْشًا، وَاصْطَفَى مِنْ قُرَيْشٍ بَنِي هَاشِمٍ، وَاصْطَفَانِي مِنْ بَنِي هَاشِمٍ". (ت)', 'വാസിലതുബ്നു അസ്ഖഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഇബ്റാഹീം സന്താനങ്ങളിൽ ഇസ്മാഈലിനെ തെരഞ്ഞെടുത്തു. ഇസ്മാഈൽ സന്താനങ്ങളിൽ ബനൂകിനാനയെ തെരഞ്ഞെടുത്തു. ബനൂകിനാനയിൽ നിന്ന് ഖുറൈശിനെ തെരഞ്ഞെടുത്തു. ഖുറൈശിൽ നിന്ന് ബനൂഹാശിമിനെ തെരഞ്ഞെടുത്തു. ബനൂഹാശിമിൽ നിന്ന് എന്നെ തെരഞ്ഞെടുത്തു." (തു)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലതുബ്നു അസ്ഖഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ قُرَيْشًا جَلَسُوا فَتَذَاكَرُوا أَحْسَابَهُمْ بَيْنَهُمْ، فَجَعَلُوا مَثَلَكَ مَثَلَ نَخْلَةٍ فِي كَبْوَةٍ مِنَ الْأَرْضِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ خَلَقَ الْخَلْقَ فَجَعَلَنِي مِنْ خَيْرِهِمْ، مِنْ خَيْرِ فِرَقِهِمْ وَخَيْرِ الْفَرِيقَيْنِ، ثُمَّ تَخَيَّرَ الْقَبَائِلَ فَجَعَلَنِي مِنْ خَيْرِ قَبِيلَةٍ، ثُمَّ تَخَيَّرَ الْبُيُوتَ فَجَعَلَنِي مِنْ خَيْرِ بُيُوتِهِمْ، فَأَنَا خَيْرُهُمْ نَفْسًا وَخَيْرُهُمْ بَيْتًا". حَسَنٌ. (ت)', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്ത്വലിബ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഖുറൈശികൾ ഇരുന്ന്, അവർക്കിടയിലെ തറവാട് മഹിമകൾ സംസാരിച്ചു. അങ്ങയുടെ ഉപമ ഭൂമിയിലെ മാലിന്യക്കുമ്പാരത്തിൻ മുകളിലുള്ള ഒരു ഈത്തപ്പന പോലെയാണെന്നാണ് അവർ പറഞ്ഞത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു സൃഷ്ടികളെ പടച്ചു. എന്നെ അവരിലെ ഉത്തമരിൽ ഉൾപ്പെടുത്തി. അവരിലെ വിഭാഗങ്ങളിൽ ഏറ്റവും ഉത്തമരിലും രണ്ട് വിഭാഗങ്ങളിൽ ഏറ്റവും ഉത്തമരിലും. പിന്നെ അല്ലാഹു ഗോത്രങ്ങളെ തെരഞ്ഞെടുത്തു. എന്നെ അവൻ ഉത്തമ ഗോത്രത്തിൽ ഉൾപ്പെടുത്തി. പിന്നെ അവൻ കുടുംബങ്ങളെ തെരഞ്ഞെടുത്തു. അവരുടെ ഉത്തമ കുടുംബത്തിൽ അവൻ എന്നെ ഉൾപ്പെടുത്തി. ശാരീരികമായി അവരിൽ ഉത്തമൻ ഞാനാണ്! കുടുംബപരമായും അവരിൽ ഉത്തമൻ ഞാനാണ്!" ഹദീസ് ഹസനാണ്. (തു)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്ത്വലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ الْعَبَّاسُ رَضِيَ اللَّهُ عَنْهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَأَنَّهُ سَمِعَ شَيْئًا، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَقَالَ: "مَنْ أَنَا". فَقَالُوا: أَنْتَ رَسُولُ اللَّهِ، عَلَيْكَ السَّلَامُ. قَالَ: "أَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ. إِنَّ اللَّهَ خَلَقَ الْخَلْقَ فَجَعَلَنِي فِي خَيْرِهِمْ فِرْقَةً، ثُمَّ جَعَلَهُمْ فِرْقَتَيْنِ فَجَعَلَنِي فِي خَيْرِهِمْ فِرْقَةً، ثُمَّ جَعَلَهُمْ قَبَائِلَ فَجَعَلَنِي فِي خَيْرِهِمْ قَبِيلَةً، ثُمَّ جَعَلَهُمْ بُيُوتًا فَجَعَلَنِي فِي خَيْرِهِمْ بَيْتًا وَخَيْرِهِمْ نَفْسًا". (ت)', 'മുത്ത്വലിബുബ്നു അബീവദാഅ(റ): അബ്ബാസ്(റ) നബി(സ)യുടെ അടുത്തുവന്നു, അവിടുന്ന് എന്തോ കേട്ടതുപോലെയുണ്ട്. അങ്ങനെ നബി(സ) മിമ്പറിൽ എണീറ്റുനിന്നുകൊണ്ട് ചോദിച്ചു: "ഞാനാരാണ്?" അപ്പോൾ അവർ പറഞ്ഞു: അങ്ങ് അല്ലാഹുവിന്റെ റസൂലാണ്. അങ്ങയുടെ മേൽ അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാകട്ടെ. നബി(സ) പറഞ്ഞു: "ഞാൻ അബ്ദുൽ മുത്ത്വലിബിന്റെ മകൻ അബ്ദുല്ലായുടെ മകൻ മുഹമ്മദാണ്. അല്ലാഹു സൃഷ്ടികളെ പടച്ചു. എന്നെ അവൻ അതിലെ ഉത്തമ വിഭാഗത്തിൽ ഉൾപ്പെടുത്തി. പിന്നെ അല്ലാഹു അവരെ രണ്ട് വിഭാഗമാക്കി. അല്ലാഹു എന്നെ അവരിലെ ഉത്തമ വിഭാഗത്തിൽ ഉൾപ്പെടുത്തി. പിന്നെ അല്ലാഹു അവരെ ഗോത്രങ്ങളാക്കി. എന്നെ അവരിലെ ഉത്തമ ഗോത്രത്തിലുൾപ്പെടുത്തി. പിന്നെ അല്ലാഹു അവരെ കുടുംബങ്ങളാക്കി. എന്നിട്ട് അല്ലാഹു എന്നെ കുടുംബത്താലും ശരീരത്താലും അവരിലെ ഉത്തമരിൽ ഉൾപ്പെടുത്തി." (തു)', 'الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ', 'മുത്ത്വലിബുബ്നു അബീവദാഅ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 289, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، مَتَى وَجَبَتْ لَكَ النُّبُوَّةُ؟ قَالَ: "وَآدَمُ بَيْنَ الرُّوحِ وَالْجَسَدِ". (ت)', 'അബൂഹുറൈറ(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങേക്ക് എപ്പോഴാണ് പ്രവാചകത്വം ലഭിച്ചത്? നബി(സ) പറഞ്ഞു: "ആദം റൂഹിന്റെയും ശരീരത്തിന്റെയും ഇടയിലുള്ളപ്പോൾ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا سَيِّدُ وَلَدِ آدَمَ يَوْمَ الْقِيَامَةِ، وَأَوَّلُ مَنْ يَنْشَقُّ عَنْهُ الْقَبْرُ، وَأَوَّلُ شَافِعٍ وَأَوَّلُ مُشَفَّعٍ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ അന്ത്യദിനത്തിൽ ആദം സന്തതികളുടെ നേതാവാണ്, ആദ്യമായി ഖബ്ർ പിളർന്ന് പുറത്ത് വരുന്നവനും ആദ്യത്തെ ശുപാർശകനും ആദ്യമായി ശുപാർശ നൽകപ്പെടുന്നവനും ഞാനാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَلُوا اللَّهَ لِيَ الْوَسِيلَةَ". قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا الْوَسِيلَةُ؟ قَالَ: "أَعْلَى دَرَجَةٍ فِي الْجَنَّةِ، لَا يَنَالُهَا إِلَّا رَجُلٌ وَاحِدٌ، أَرْجُو أَنْ أَكُونَ أَنَا هُوَ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ എനിക്ക് വേണ്ടി അല്ലാഹുവിനോട് വസീലയെ ചോദിക്കുക." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണ് വസീല? നബി(സ) പറഞ്ഞു: "സ്വർഗത്തിലെ ഉന്നതമായ സ്ഥാനം, അത് ഒരാൾക്ക് മാത്രമേ ലഭിക്കുകയുള്ളൂ. അത് ഞാനായിരിക്കുമെന്നാണ് ഞാൻ പ്രതീക്ഷിക്കുന്നത്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلِي فِي النَّبِيِّينَ كَمَثَلِ رَجُلٍ بَنَى دَارًا، فَأَحْسَنَهَا وَأَكْمَلَهَا وَأَجْمَلَهَا، وَتَرَكَ مِنْهَا مَوْضِعَ لَبِنَةٍ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِالْبِنَاءِ وَيَعْجَبُونَ مِنْهُ، وَيَقُولُونَ: لَوْ تَمَّ مَوْضِعُ تِلْكَ اللَّبِنَةِ. وَأَنَا فِي النَّبِيِّينَ مَوْضِعُ تِلْكَ اللَّبِنَةِ". وَفِي رِوَايَةٍ قَالَ: "إِذَا كَانَ يَوْمُ الْقِيَامَةِ كُنْتُ إِمَامَ النَّبِيِّينَ وَخَطِيبَهُمْ، وَصَاحِبَ شَفَاعَتِهِمْ، غَيْرَ فَخْرٍ". (ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകരിലെ എന്റെ ഉപമ, ഒരു വീട് നല്ല നിലയിൽ, നല്ല ഭംഗിയിൽ പൂർണതയോടെ ഉണ്ടാക്കിയ ഒരാളെപ്പോലെയാണ്. അദ്ദേഹമതിൽ ഒരു ഇഷ്ടികയുടെ സ്ഥലം ബാക്കിവെച്ചു. ജനങ്ങൾ ആ കെട്ടിടത്തിന്റെ അടുത്തുകൂടെ നടക്കുമ്പോൾ അത് അവരെ അത്ഭുതപ്പെടുത്തുന്നു. അവർ പറയുന്നു: ഈ ഇഷ്ടികയുടെ സ്ഥലം പൂർത്തിയാക്കിയിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു. എന്നാൽ പ്രവാചകരിൽ ഞാൻ ഈ ഇഷ്ടികയുടെ സ്ഥാനത്താണ്." മറ്റൊരു നിവേദനം: "അന്ത്യദിനമായാൽ ഞാൻ പ്രവാചകന്മാരുടെ നേതാവും അവരുടെ പ്രാസംഗികനും അവരുടെ ശഫാഅത്തിന്റെ വക്താവുമാകും. ഇത് അഹങ്കാരമല്ല." (തു)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 290, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=7), 1, 'وَفِي رِوَايَةٍ قَالَ: "إِذَا كَانَ يَوْمُ الْقِيَامَةِ كُنْتُ إِمَامَ النَّبِيِّينَ وَخَطِيبَهُمْ، وَصَاحِبَ شَفَاعَتِهِمْ، غَيْرَ فَخْرٍ". (ت)', 'മറ്റൊരു നിവേദനം: "അന്ത്യദിനമായാൽ ഞാൻ പ്രവാചകന്മാരുടെ നേതാവും അവരുടെ പ്രാസംഗികനും അവരുടെ ശഫാഅത്തിന്റെ വക്താവുമാകും. ഇത് അഹങ്കാരമല്ല." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا سَيِّدُ وَلَدِ آدَمَ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَبِيَدِي لِوَاءُ الْحَمْدِ وَلَا فَخْرَ، وَمَا مِنْ نَبِيٍّ يَوْمَئِذٍ – آدَمُ فَمَنْ سِوَاهُ – إِلَّا تَحْتَ لِوَائِي، وَأَنَا أَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ وَلَا فَخْرَ". حَسَنٌ. (ت,جه)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യദിനത്തിൽ ആദം സന്തതികളുടെ നേതാവാണ് ഞാൻ. ഇത് അഹങ്കാരമല്ല. ലിവാഉൽ ഹംദ് എന്റെ കയ്യിലാണ്. ഇത് അഹങ്കാരമല്ല. എന്റെ പതാകക്ക് കീഴിൽ വരാത്തവരായി ആദം(അ)മോ മറ്റു പ്രവാചകന്മാരോ ഉണ്ടാവില്ല. ആദ്യമായി ഭൂമി പിളർന്ന് പുറത്ത് വരുന്നതും ഞാനാണ്. ഇത് അഹന്തയല്ല." (തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا. ثُمَّ سَلُوا لِيَ الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ، لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، وَمَنْ سَأَلَ لِيَ الْوَسِيلَةَ حَلَّتْ عَلَيْهِ الشَّفَاعَةُ". (م,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അദ്ദേഹം നബി(സ) പറയുന്നത് കേട്ടു: "നിങ്ങൾ ബാങ്ക് വിളിക്കുന്നവനെ കേട്ടാൽ അവൻ പറയുന്നത് പോലെ പറയുക. പിന്നെ നിങ്ങൾ എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലുക. എന്റെ മേൽ ആരെങ്കിലും ഒരു സ്വലാത്ത് ചൊല്ലിയാൽ അതു കാരണമായി അവന്റെ മേൽ അല്ലാഹു പത്ത് സ്വലാത്ത് ചൊല്ലും. പിന്നെ നിങ്ങൾ എനിക്ക് വേണ്ടി വസീലയെ ചോദിക്കുക. അത് സ്വർഗത്തിലെ ഒരു സ്ഥാനമാണ്. അല്ലാഹുവിന്റെ അടിമകളിൽ ഒരാൾക്ക് മാത്രമേ അത് ലഭിക്കൂ. അത് ഞാനാകാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. എനിക്ക് വേണ്ടി ആരെങ്കിലും വസീലയെ ചോദിച്ചാൽ അവന് എന്റെ ശഫാഅത്ത് അനുവദനീയമായിരിക്കുന്നു." (മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَلَسَ نَاسٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْتَظِرُونَهُ، قَالَ: فَخَرَجَ حَتَّى إِذَا دَنَا مِنْهُمْ سَمِعَهُمْ يَتَذَاكَرُونَ، فَسَمِعَ حَدِيثَهُمْ، فَقَالَ بَعْضُهُمْ: عَجَبًا، إِنَّ اللَّهَ عَزَّ وَجَلَّ اتَّخَذَ مِنْ خَلْقِهِ خَلِيلًا: اتَّخَذَ إِبْرَاهِيمَ خَلِيلًا. وَقَالَ آخَرُ: مَاذَا بِأَعْجَبَ مِنْ كَلَامِ مُوسَى، كَلَّمَهُ تَكْلِيمًا. وَقَالَ آخَرُ: فَعِيسَى كَلِمَةُ اللَّهِ وَرُوحُهُ. وَقَالَ آخَرُ: آدَمُ اصْطَفَاهُ اللَّهُ. فَخَرَجَ عَلَيْهِمْ فَسَلَّمَ وَقَالَ: "قَدْ سَمِعْتُ كَلَامَكُمْ وَعَجَبَكُمْ، إِنَّ إِبْرَاهِيمَ خَلِيلُ اللَّهِ وَهُوَ كَذَلِكَ، وَمُوسَى نَجِيُّ اللَّهِ وَهُوَ كَذَلِكَ، وَعِيسَى رُوحُ اللَّهِ وَكَلِمَتُهُ وَهُوَ كَذَلِكَ، وَآدَمُ اصْطَفَاهُ اللَّهُ وَهُوَ كَذَلِكَ. أَلَا وَأَنَا حَبِيبُ اللَّهِ وَلَا فَخْرَ، وَأَنَا حَامِلُ لِوَاءِ الْحَمْدِ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَأَنَا أَوَّلُ شَافِعٍ وَأَوَّلُ مُشَفَّعٍ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَأَنَا أَوَّلُ مَنْ يُحَرِّكُ حَلَقَ الْجَنَّةِ، فَيَفْتَحُ اللَّهُ لِي فَيُدْخِلُنِيهَا وَمَعِي فُقَرَاءُ الْمُؤْمِنِينَ وَلَا فَخْرَ، وَأَنَا أَكْرَمُ الْأَوَّلِينَ وَالْآخِرِينَ وَلَا فَخْرَ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ ചില അനുചരർ തിരുമേനി(സ)യെ പ്രതീക്ഷിച്ചിരിക്കുന്നുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ നബി(സ) പുറപ്പെട്ടു. അവരുടെ അടുത്തെത്തിയപ്പോൾ അവർ പരസ്പരം സംസാരിക്കുന്നത് അവിടുന്ന് കേൾക്കുകയും ശ്രദ്ധിക്കുകയും ചെയ്തു. ഒരാൾ പറഞ്ഞു: അത്ഭുതം! അല്ലാഹു തന്റെ സൃഷ്ടികളിൽ നിന്ന് ഒരു സുഹൃത്തിനെ ഉണ്ടാക്കിയിരിക്കുന്നു. അല്ലാഹു ഇബ്റാഹീം(അ)നെ സുഹൃത്താക്കിയിരിക്കുന്നു. വേറൊരാൾ പറഞ്ഞു: മൂസാ(അ)മിന്റെ സംസാരം എന്ത് അത്ഭുതമാണ്! അവിടുന്ന് അല്ലാഹുവിനോട് സംസാരിച്ചിരിക്കുന്നു! മറ്റൊരാൾ പറഞ്ഞു: ഈസാ(അ) അല്ലാഹുവിന്റെ വചനവും ആത്മാവുമാണ്. പിന്നീടൊരാൾ പറഞ്ഞു: ആദം(അ)മിനെ അല്ലാഹു തെരഞ്ഞെടുത്തിരിക്കുന്നു. അപ്പോൾ നബി(സ) അവരിലേക്ക് വന്ന് അവരോട് സലാം ചൊല്ലി. ശേഷം പറഞ്ഞു: "നിങ്ങളുടെ സംസാരവും അത്ഭുതവും ഞാൻ കണ്ടു. നിശ്ചയം ഇബ്റാഹീം(അ) അല്ലാഹുവിന്റെ ഖലീലാണ്. അത് അങ്ങനെത്തന്നെയാണ്. മൂസാ(അ) അല്ലാഹുവിന്റെ നജിയ്യാണ് (രക്ഷപ്പെട്ടവൻ). അതും അങ്ങനെത്തന്നെ. ഈസാ(അ) അല്ലാഹുവിന്റെ റൂഹും (ആത്മാവ്) കലിമയും (വചനം) ആകുന്നു. അതും അങ്ങനെത്തന്നെ. ആദം(അ)മിനെ അല്ലാഹു തെരഞ്ഞെടുത്തിരിക്കുന്നു. അതും അപ്രകാരം തന്നെ. അറിയുക! ഞാൻ അല്ലാഹുവിന്റെ ഹബീബാണ് (സ്നേഹിതൻ), മേന്മ പറയുകയല്ല. ഞാൻ അന്ത്യദിനത്തിൽ ലിവാഉൽ ഹംദിന്റെ വാഹകനാണ്, മേന്മ പറയുകയല്ല. അന്ത്യദിനത്തിൽ ആദ്യമായി ശുപാർശ ചെയ്യുന്നവനും ശുപാർശക്ക് അധികാരം നൽകപ്പെടുന്നവനും ഞാനാണ്, മേന്മ പറയുകയല്ല. ആദ്യമായി സ്വർഗത്തിന്റെ വട്ടക്കണ്ണി ഇളക്കുന്നവനും ഞാനാണ്. അപ്പോൾ അത് അല്ലാഹു എനിക്ക് തുറന്നുതരും. എന്നെയും എന്റെ കൂടെ പാവപ്പെട്ട മുഅ്മിനുകളെയും അവൻ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കും, മേന്മ പറയുകയല്ല. ആദ്യത്തെവരിലും അവസാനത്തെവരിലും ഏറ്റവും മാന്യൻ ഞാനാണ്, മേന്മ പറയുകയല്ല." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 291, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَكْتُوبٌ فِي التَّوْرَاةِ صِفَةُ مُحَمَّدٍ وَصِفَةُ عِيسَى ابْنِ مَرْيَمَ، يُدْفَنُ مَعَهُ. فَقَالَ أَبُو مَوْدُودٍ: وَقَدْ بَقِيَ فِي الْبَيْتِ مَوْضِعُ قَبْرٍ. حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): തൗറാത്തിൽ മുഹമ്മദ്(സ)യുടെയും ഈസബ്നു മർയം(അ)മിന്റെയും വിശേഷണം എഴുതപ്പെട്ടിട്ടുണ്ട്. ഈസബ്നു മർയം(അ) തിരുമേനി(സ)യോടൊപ്പം മറവ് ചെയ്യപ്പെടുന്നതാണ്. അബൂമൗദൂദ്(റ) പറയുന്നു: ബൈത്തിൽ (നബി(സ)യുടെ വീട്ടിൽ) ഒരു ഖബറിനുള്ള സ്ഥലം ശേഷിക്കുന്നുണ്ട്. ഹദീസ് ഹസനാണ്. (തു)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ الْيَوْمُ الَّذِي دَخَلَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ أَضَاءَ مِنْهَا كُلُّ شَيْءٍ، فَلَمَّا كَانَ الْيَوْمُ الَّذِي مَاتَ فِيهِ أَظْلَمَ مِنْهَا كُلُّ شَيْءٍ، وَمَا نَفَضْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْأَيْدِي – وَإِنَّا لَفِي دَفْنِهِ – حَتَّى أَنْكَرْنَا قُلُوبَنَا. (ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) മദീനയിൽ പ്രവേശിച്ച ദിവസമായപ്പോൾ, മദീനയിലെ എല്ലാ വസ്തുക്കളും പ്രകാശിച്ചു. നബി(സ) വഫാത്തായപ്പോൾ മദീനയിലെ എല്ലാം ഇരുട്ടിലായി. ഞങ്ങൾ റസൂൽ(സ)യുടെ മീതെ കൈകൊണ്ട് മണ്ണ് വാരിയിട്ട് കഴിഞ്ഞപ്പോഴേക്കും (നബിയെ മറവ് ചെയ്യുമ്പോൾ) ഞങ്ങൾ ഞങ്ങളെത്തന്നെ വെറുക്കുന്നതായി തോന്നി: (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ شَمِطَ مُقَدَّمُ رَأْسِهِ وَلِحْيَتِهِ، وَكَانَ إِذَا ادَّهَنَ لَمْ يَتَبَيَّنْ، وَإِذَا شَعِثَ رَأْسُهُ تَبَيَّنَ، وَكَانَ كَثِيرَ شَعْرِ اللِّحْيَةِ. فَقَالَ رَجُلٌ: وَجْهُهُ مِثْلُ السَّيْفِ. قَالَ: لَا؛ بَلْ كَانَ مِثْلَ الشَّمْسِ وَالْقَمَرِ، وَكَانَ مُسْتَدِيرًا، وَرَأَيْتُ الْخَاتَمَ عِنْدَ كَتِفِهِ مِثْلَ بَيْضَةِ الْحَمَامَةِ، يُشْبِهُ جَسَدَهُ. (م)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ)യുടെ താടിയുടെയും തലമുടിയുടെയും മുൻഭാഗം അൽപം നരച്ചിരുന്നു. അവിടുന്ന് എണ്ണ പുരട്ടിയാൽ അത് വ്യക്തമായി കാണില്ല. അവിടുത്തെ മുടി ജട കുത്തിയാൽ അത് വ്യക്തമാകും. തിരുമേനി(സ) കൂടുതൽ താടിരോമങ്ങളുള്ളവരായിരുന്നു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: അവിടുത്തെ മുഖം വാൾ പോലെയാണ്. ജാബിർ(റ) പറഞ്ഞു: അല്ല. അത് ചന്ദ്രന്റെയോ സൂര്യന്റെയോ പോലെയാണ്. അവിടുത്തെ വദനം വൃത്താകൃതിയിലായിരുന്നു. അവിടുത്തെ തോൾ ഭാഗത്ത് പ്രാവിന്റെ മുട്ട പോലെയുള്ള, അതിന്റെ ശരീരത്തോട് സാമ്യതയുള്ള പ്രവാചകത്വത്തിന്റെ അടയാളം ഞാൻ കണ്ടു. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 292, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَهَبَتْ بِي خَالَتِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي وَجِعٌ. فَمَسَحَ رَأْسِي وَدَعَا لِي بِالْبَرَكَةِ، ثُمَّ تَوَضَّأَ فَشَرِبْتُ مِنْ وَضُوئِهِ، ثُمَّ قُمْتُ خَلْفَ ظَهْرِهِ، فَنَظَرْتُ إِلَى خَاتَمِهِ بَيْنَ كَتِفَيْهِ مِثْلَ زِرِّ الْحَجَلَةِ. (م)', 'സാഇബുബ്നു യസീദ്(റ): എന്റെ മാതൃസഹോദരി എന്നെയും കൊണ്ട് റസൂൽ(സ)യുടെ അടുത്തുചെന്നു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ സഹോദര പുത്രൻ രോഗിയാണ്. അപ്പോൾ അവിടുന്ന് എന്റെ തല തടവിയിട്ട് എനിക്ക് അനുഗ്രഹത്തിന് വേണ്ടി പ്രാർത്ഥിച്ചു. പിന്നെ റസൂൽ(സ) വുളു ചെയ്തു. ഞാൻ അവിടുത്തെ വുളുവിന്റെ വെള്ളത്തിൽ നിന്നൽപം കുടിച്ചു. പിന്നെ ഞാൻ നബി(സ)യുടെ പിറകിൽ നിന്നു. അപ്പോൾ ഞാൻ അവിടുത്തെ തോളുകൾക്കിടയിലുള്ള പ്രാവിന്റെ മുട്ടയെപ്പോലുള്ള പ്രവാചകത്വത്തിന്റെ അടയാളത്തിലേക്ക് നോക്കി. (മു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَكَلْتُ مَعَهُ خُبْزًا وَلَحْمًا. أَوْ قَالَ: ثَرِيدًا. قَالَ: فَقُلْتُ لَهُ: أَسْتَغْفَرَ لَكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ وَلَكَ، ثُمَّ تَلَا هَذِهِ الْآيَةَ {وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ} [مُحَمَّد: ١٩]. قَالَ: ثُمَّ دُرْتُ خَلْفَهُ فَنَظَرْتُ إِلَى خَاتَمِ النُّبُوَّةِ بَيْنَ كَتِفَيْهِ، عِنْدَ نَاغِضِ كَتِفِهِ الْيُسْرَى، جُمْعًا، عَلَيْهِ خِيلَانٌ كَأَمْثَالِ الثَّآلِيلِ. (م)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): നബി(സ)യെ ഞാൻ കണ്ടു. ഞാനവിടുത്തോടൊപ്പം റൊട്ടിയും ഇറച്ചിയും കഴിച്ചു. - അല്ലെങ്കിൽ നിവേദകൻ പറഞ്ഞത്: സരീദ്¹ കഴിച്ചുവെന്നാണ്. - ഞാൻ നിവേദകനോട് ചോദിച്ചു: നബി(സ) അങ്ങേക്ക് വേണ്ടി പൊറുക്കലിനെ തേടിയോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അതെ. നിനക്ക് വേണ്ടിയും. പിന്നെ അദ്ദേഹം ഈ സൂക്തം ഓതിക്കേൾപ്പിച്ചു: ''അങ്ങയുടെ ദോഷത്തിനും സത്യവിശ്വാസികൾക്കും വിശ്വാസിനികൾക്കും വേണ്ടി അവിടുന്ന് പൊറുക്കലിനെ തേടുക.'' (മുഹമ്മദ്: 19) നിവേദകൻ പറയുന്നു: പിന്നെ ഞാൻ അവിടുത്തെ പിറകിൽ ചുറ്റിത്തിരിഞ്ഞു. നബി(സ)യുടെ രണ്ട് തോളുകൾക്കിടയിലുള്ള മുഷ്ടിയുടെ രൂപത്തിൽ ഇടത്തേ തോളിന്റെ മേൽഭാഗത്ത്, രണ്ട് തോളുകൾക്കിടയിൽ ഞാൻ നുബുവ്വത്തിന്റെ അടയാളം കണ്ടു. അതിന്മേൽ മറുകുകൾ പോലെയുള്ള ഭാഗങ്ങളുണ്ട്. (മു)', 'عَبْدِ اللَّهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', '¹. റൊട്ടിയും മാംസവും ചേർത്തുണ്ടാക്കുന്ന പലഹാരമാണ് സരീദ്', null, array['م']::text[], array['മു']::text[], 'مُحَمَّد: ١٩', null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ خَاتَمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – يَعْنِي الَّذِي بَيْنَ كَتِفَيْهِ – غُدَّةً حَمْرَاءَ، مِثْلَ بَيْضَةِ الْحَمَامَةِ. (م,ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ)യുടെ പ്രവാചകത്വത്തിന്റെ അടയാളം അവിടുത്തെ രണ്ട് തോളുകൾക്കിടയിലുള്ള പ്രാവിന്റെ മുട്ട പോലെയുള്ള ചുവന്ന മൃദുലമായ മാംസമായിരുന്നു. (മു,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ قَيْسِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وُلِدْتُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفِيلِ، وَسَأَلَ عُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قُبَاثَ بْنَ أَشْيَمَ رَضِيَ اللَّهُ عَنْهُ: أَأَنْتَ أَكْبَرُ أَمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْبَرُ مِنِّي، وَأَنَا أَقْدَمُ مِنْهُ فِي الْمِيلَادِ، وُلِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفِيلِ، وَرُفِعَتْ بِي أُمِّي عَلَى الْمَوْضِعِ، قَالَ: وَرَأَيْتُ خَرْءَ الْفِيلِ أَخْضَرَ مُحِيلًا. حَسَنٌ. (ت)', 'ഖൈസുബ്നു മഖ്റമ(റ): ഞാനും റസൂൽ(സ)യും ആനക്കലഹ സംഭവത്തിന്റെ വർഷത്തിലാണ് ജനിച്ചത്. ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) ഖുബാസുബ്നു അശ്യം(റ)വിനോട് ചോദിച്ചു: നിങ്ങളാണോ അതോ റസൂൽ(സ)യാണോ മുതിർന്നവർ? ഖുബാസ്(റ) പറഞ്ഞു: റസൂൽ(സ) എന്നെക്കാൾ വലിയവരാണ്. ജനനത്തിൽ അവിടത്തേക്കാൾ മുമ്പ് വന്നത് ഞാനാണ്. റസൂൽ(സ) ആനക്കലഹ വർഷത്തിലാണ് ജനിച്ചത്. എന്റെ മാതാവ് എന്നെ നിലത്തുനിന്ന് ഉയർത്തിപ്പിടിച്ചു. അദ്ദേഹം പറയുന്നു: ഞാൻ പച്ച നിറത്തിലുള്ള നിറപ്പകർച്ചവന്ന ആനപ്പിണ്ടി കണ്ടു. (തു)', 'قَيْسِ بْنِ مَخْرَمَةَ', 'ഖൈസുബ്നു മഖ്റമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 293, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'مُحَمَّدُ بْنُ عَبْدِاللهِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمٍ، بْنِ عَبْدِ مَنَافٍ، بْنِ قُصَيٍّ، بْنِ كِلَابٍ، بْنِ مُرَّةَ، بْنِ كَعْبٍ، بْنِ لُؤَيٍّ، بْنِ غَالِبٍ، بْنِ فِهْرٍ، بْنِ مَالِكٍ، بْنِ النَّضْرِ، بْنِ كِنَانَةَ، بْنِ خُزَيْمَةَ، بْنِ مُدْرِكَةَ، بْنِ إِلْيَاسَ، بْنِ مُضَرَ، بْنِ نِزَارٍ، بْنِ مَعَدٍّ، بْنِ عَدْنَانَ. (خ)', 'അദ്നാൻ മകൻ മഅദ്ദ് മകൻ നിസാർ മകൻ മുളർ മകൻ ഇല്യാസ് മകൻ മുദ്രിക മകൻ ഖുസൈമ മകൻ കിനാന മകൻ നള്റ് മകൻ മാലിക് മകൻ ഫിഹ്റ് മകൻ ഗാലിബ് മകൻ ലുഅയ്യ് മകൻ കഅ്ബ് മകൻ മുർറ മകൻ കിലാബ് മകൻ ഖുസ്വയ്യ് മകൻ അബ്ദുമനാഫ് മകൻ ഹാശിം മകൻ അബ്ദുൽമുത്വലിബ് മകൻ അബ്ദുല്ല മകൻ മുഹമ്മദ്(സ). (ഇതാണ് നബി(സ)യുടെ പിതൃപരമ്പര). (ബു)', null, null, null, null, array['خ']::text[], array['ബു']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ أَبُو طَالِبٍ إِلَى الشَّامِ، وَخَرَجَ مَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَشْيَاخٍ مِنْ قُرَيْشٍ، فَلَمَّا أَشْرَفُوا عَلَى الرَّاهِبِ هَبَطُوا، فَحَلُّوا رِحَالَهُمْ، فَخَرَجَ إِلَيْهِمُ الرَّاهِبُ، وَكَانُوا قَبْلَ ذَلِكَ يَمُرُّونَ بِهِ فَلَا يَخْرُجُ إِلَيْهِمْ وَلَا يَلْتَفِتُ، قَالَ: فَهُمْ يَحُلُّونَ رِحَالَهُمْ فَجَعَلَ يَتَخَلَّلُهُمُ الرَّاهِبُ، حَتَّى جَاءَ فَأَخَذَ بِيَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: هَذَا سَيِّدُ الْعَالَمِينَ، هَذَا رَسُولُ رَبِّ الْعَالَمِينَ، يَبْعَثُهُ اللَّهُ رَحْمَةً لِلْعَالَمِينَ. فَقَالَ لَهُ أَشْيَاخٌ مِنْ قُرَيْشٍ: مَا عِلْمُكَ؟ فَقَالَ: إِنَّكُمْ حِينَ أَشْرَفْتُمْ مِنَ الْعَقَبَةِ لَمْ يَبْقَ شَجَرٌ وَلَا حَجَرٌ إِلَّا خَرَّ سَاجِدًا، وَلَا يَسْجُدَانِ إِلَّا لِنَبِيٍّ، وَإِنِّي أَعْرِفُهُ بِخَاتَمِ النُّبُوَّةِ أَسْفَلَ مِنْ غُضْرُوفِ كَتِفِهِ مِثْلَ التُّفَّاحَةِ. ثُمَّ رَجَعَ فَصَنَعَ لَهُمْ طَعَامًا، فَلَمَّا أَتَاهُمْ بِهِ وَكَانَ هُوَ فِي رِعْيَةِ الْإِبِلِ، قَالَ: أَرْسِلُوا إِلَيْهِ. فَأَقْبَلَ وَعَلَيْهِ غَمَامَةٌ تُظِلُّهُ، فَلَمَّا دَنَا مِنَ الْقَوْمِ وَجَدَهُمْ قَدْ سَبَقُوهُ إِلَى فَيْءِ الشَّجَرَةِ، فَلَمَّا جَلَسَ مَالَ فَيْءُ الشَّجَرَةِ عَلَيْهِ، فَقَالَ: انْظُرُوا إِلَى فَيْءِ الشَّجَرَةِ مَالَ عَلَيْهِ. قَالَ: فَبَيْنَمَا هُوَ قَائِمٌ عَلَيْهِمْ، وَهُوَ يُنَاشِدُهُمْ أَنْ لَا يَذْهَبُوا بِهِ إِلَى الرُّومِ، فَإِنَّ الرُّومَ إِذَا رَأَوْهُ عَرَفُوهُ بِالصِّفَةِ فَيَقْتُلُونَهُ، فَالْتَفَتَ فَإِذَا بِسَبْعَةٍ قَدْ أَقْبَلُوا مِنَ الرُّومِ، فَاسْتَقْبَلَهُمْ فَقَالَ: مَا جَاءَ بِكُمْ؟ قَالُوا: جِئْنَا إِنَّ هَذَا النَّبِيَّ خَارِجٌ فِي هَذَا الشَّهْرِ، فَلَمْ يَبْقَ طَرِيقٌ إِلَّا بُعِثَ إِلَيْهِ بِأُنَاسٍ، وَإِنَّا قَدْ أُخْبِرْنَا خَبَرَهُ بُعِثْنَا إِلَى طَرِيقِكَ هَذَا. فَقَالَ: هَلْ خَلْفَكُمْ أَحَدٌ هُوَ خَيْرٌ مِنْكُمْ. قَالُوا: إِنَّمَا أُخْبِرْنَا خَبَرَهُ بِطَرِيقِكَ هَذَا. قَالَ: أَفَرَأَيْتُمْ أَمْرًا أَرَادَ اللَّهُ أَنْ يَقْضِيَهُ، هَلْ يَسْتَطِيعُ أَحَدٌ مِنَ النَّاسِ رَدَّهُ؟ قَالُوا: لَا. قَالَ: فَبَايَعُوهُ وَأَقَامُوا مَعَهُ. قَالَ: أَنْشُدُكُمْ بِاللَّهِ أَيُّكُمْ وَلِيُّهُ؟ قَالُوا: أَبُو طَالِبٍ. فَلَمْ يَزَلْ يُنَاشِدُهُ حَتَّى رَدَّهُ أَبُو طَالِبٍ، وَبَعَثَ مَعَهُ أَبُو بَكْرٍ بِلَالًا، وَزَوَّدَهُ الرَّاهِبُ مِنَ الْكَعْكِ وَالزَّيْتِ. (ت)', 'അബൂമൂസൽ അശ്അരി(റ): അബൂഥാലിബ് ശാമിലേക്ക് പുറപ്പെട്ടു. അദ്ദേഹത്തോടൊപ്പം ഖുറൈശീ പ്രമാണികളുടെ കൂട്ടത്തിൽ നബി(സ)യും പുറപ്പെട്ടു. പോകുംവഴിയുള്ള പുരോഹിതന്റെ അടുത്തെത്തിയപ്പോൾ അവർ അവിടെ ഇറങ്ങി. അവർ തങ്ങളുടെ ഒട്ടകക്കട്ടിലുകൾ അഴിച്ചു. പുരോഹിതൻ അവരുടെ അടുത്ത് വന്നു. അതിനുമുമ്പും അവർ പുരോഹിതന്റെ അടുത്തുകൂടെ നടന്നുപോകാറുണ്ടായിരുന്നു. പക്ഷേ, അദ്ദേഹം അവരിലേക്ക് വരികയോ തിരിഞ്ഞുനോക്കുകയോ ചെയ്തിരുന്നില്ല. നിവേദകൻ പറയുന്നു: അവർ തങ്ങളുടെ ഒട്ടകക്കട്ടിലുകളഴിക്കുമ്പോൾ പുരോഹിതൻ അവർക്കിടയിലൂടെ നടക്കാൻ തുടങ്ങി. എന്നിട്ട് നേരെവന്ന് നബി(സ)യുടെ കൈ പിടിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഇവർ സർവ്വലോകരുടെയും നേതാവാണ്. ഇവർ ലോകരക്ഷിതാവിന്റെ ദൂതനാണ്. ഇവരെ അല്ലാഹു ലോകത്തിനനുഗ്രഹമായി നിയോഗിക്കും. അന്നേരം ഖുറൈശി പ്രമാണികൾ അദ്ദേഹത്തോട് ചോദിച്ചു: താങ്കൾക്കെങ്ങനെ മനസ്സിലായി? അപ്പോൾ പുരോഹിതൻ പറഞ്ഞു: നിങ്ങൾ അഖബയിൽ നിന്ന് വന്ന സമയത്ത് അവിടത്തേക്ക് സാഷ്ടാംഗം നമിക്കാത്ത ഒരു കല്ലോ മരമോ ഇല്ല. ഇവ ഒരു പ്രവാചകനു മാത്രമേ സാഷ്ടാംഗം നമിക്കുകയുള്ളൂ. അവിടുത്തെ ചുമലിന്റെ തരുണാസ്ഥിയുടെ അടിഭാഗത്തുള്ള, ആപ്പിൾ പോലുള്ള, പ്രവാചകത്വത്തിന്റെ മുദ്രയാൽ തീർച്ചയായും എനിക്കദ്ദേഹത്തെ തിരിച്ചറിയാം. പിന്നെ പുരോഹിതൻ മടങ്ങിച്ചെന്ന് അവർക്കുവേണ്ടി ഭക്ഷണമുണ്ടാക്കി. അദ്ദേഹം അവരുടെ അടുത്ത് ഭക്ഷണവുമായി വന്നപ്പോൾ നബി(സ) തന്റെ ഒട്ടകത്തെ മേയ്ക്കുകയായിരുന്നു. അപ്പോൾ പുരോഹിതൻ നബി(സ)യെ ആളെ അയച്ചു വിളിക്കാൻ പറഞ്ഞു. നബി(സ) മുന്നിട്ടു. അവിടുത്തേക്ക് മേഘം തണൽ നൽകുന്നുണ്ടായിരുന്നു. നബി(സ) അവരോടടുത്തെത്തിയപ്പോൾ മരത്തണലിലേക്ക് അവരെല്ലാം മുമ്പേ എത്തിയതായി കണ്ടു. നബി(സ) ഇരുന്നപ്പോൾ മരത്തണൽ അവിടത്തേക്ക് ചാഞ്ഞു. അപ്പോൾ പുരോഹിതൻ പറഞ്ഞു: മരത്തണൽ അവിടുത്തേക്ക് ചാഞ്ഞിരിക്കുന്നത് നിങ്ങൾ നോക്കുക. നിവേദകൻ പറയുന്നു: റോമക്കാർ തിരുമേനിയെ കണ്ടാൽ വിശേഷണം കൊണ്ട് തിരിച്ചറിയുകയും തിരുമേനിയെ വധിക്കുകയും ചെയ്യും, അതിനാൽ നബി(സ)യെ അവർ റോമിലേക്ക് കൊണ്ടുപോകരുതെന്ന് ആവശ്യപ്പെട്ട് പുരോഹിതൻ അവർക്കിടയിൽ നിൽക്കെ, ഒന്ന് തിരിഞ്ഞുനോക്കുമ്പോൾ ഏഴാളുകൾ റോമിൽനിന്ന് കടന്നുവരുന്നു. പുരോഹിതൻ അവരെ സ്വീകരിച്ചുകൊണ്ട് ചോദിച്ചു: നിങ്ങൾ എന്തിനാണ് വന്നത്? അവർ പറഞ്ഞു: ഈ പ്രവാചകൻ ഈ മാസത്തിൽ വരും. അതുകൊണ്ട് എല്ലാ വഴികളിലേക്കും ആളെ അയച്ചിട്ടുണ്ട്. അങ്ങനെയാണ് ഞങ്ങൾ വന്നത്. ഞങ്ങൾക്കും ആ പ്രവാചകന്റെ വിവരം ലഭിക്കുകയും താങ്കളുടെ ഈ വഴിയിലേക്ക് ഞങ്ങൾ നിയോഗിക്കപ്പെടുകയും ചെയ്തു. പുരോഹിതൻ ചോദിച്ചു: നിങ്ങളുടെ പിന്നിൽ നിങ്ങളേക്കാൾ ഉത്തമരായ ആരെങ്കിലുമുണ്ടോ? അവർ പറഞ്ഞു: നിങ്ങളുടെ ഈ വഴിയിലാണ് ആ പ്രവാചകനുണ്ടാവുകയെന്നാണ് ഞങ്ങൾക്ക് വിവരം ലഭിച്ചിട്ടുള്ളത്. പുരോഹിതൻ ചോദിച്ചു: അല്ലാഹു നടപ്പാക്കാൻ ഉദ്ദേശിച്ച ഒരു കാര്യം ജനങ്ങളിൽ ആർക്കെങ്കിലും തട്ടിമാറ്റാൻ കഴിയുമെന്ന് നിങ്ങൾക്ക് അഭിപ്രായമുണ്ടോ? അവർ പറഞ്ഞു: ഇല്ല. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ പുരോഹിതനോട് ഉടമ്പടി ചെയ്യുകയും അദ്ദേഹത്തിന്റെ കൂടെ കഴിയുകയും ചെയ്തു. പുരോഹിതൻ പറഞ്ഞു: ഞാൻ നിങ്ങളോട് അല്ലാഹുവിൽ സത്യംചെയ്ത് ചോദിക്കുന്നു: നിങ്ങളിൽ തിരുമേനിയുടെ രക്ഷിതാവ് ആരാണ്? അവർ പറഞ്ഞു: അബൂത്വാലിബ്. അപ്പോൾ പുരോഹിതൻ അബൂത്വാലിബിനോട് (നബി(സ)യെ മടക്കിയയക്കാൻ) ആവശ്യപ്പെട്ടുകൊണ്ടേയിരിക്കുകയും അങ്ങനെ അബൂത്വാലിബ് നബി(സ)യെ മടക്കിയയക്കുകയും ചെയ്തു. അബൂബക്കർ(റ) നബി(സ)യുടെ കൂടെ ബിലാൽ(റ)വിനെയും അയച്ചു. പുരോഹിതൻ നബി(സ)ക്ക് റൊട്ടിയും എണ്ണയും പാഥേയമായി ഒരുക്കിക്കൊടുത്തു. (തു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 294, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُنْزِلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ أَرْبَعِينَ، فَأَقَامَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ، وَبِالْمَدِينَةِ عَشْرًا، وَتُوُفِّيَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ. (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് നാൽപത് വയസ്സുള്ളപ്പോഴാണ് അവിടത്തേക്ക് ഖുർആൻ അവതരിച്ചത്. അങ്ങനെ അവിടുന്ന് മക്കയിൽ പതിമൂന്ന് വർഷവും മദീനയിൽ പത്ത് വർഷവും താമസിച്ചു. അറുപത്തിമൂന്ന് വയസ്സുള്ളപ്പോഴാണ് അവിടുന്ന് വഫാതായത്. (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالطَّوِيلِ الْبَائِنِ، وَلَا بِالْقَصِيرِ الْمُتَرَدِّدِ، وَلَا بِالْأَبْيَضِ الْأَمْهَقِ وَلَا بِالْآدَمِ، وَلَيْسَ بِالْجَعْدِ الْقَطَطِ وَلَا بِالسَّبْطِ، بَعَثَهُ اللَّهُ عَلَى رَأْسِ أَرْبَعِينَ سَنَةً، فَأَقَامَ بِمَكَّةَ عَشْرَ سِنِينَ، وَبِالْمَدِينَةِ عَشْرَ سِنِينَ، وَتَوَفَّاهُ اللَّهُ عَلَى رَأْسِ سِتِّينَ سَنَةً، وَلَيْسَ فِي رَأْسِهِ وَلِحْيَتِهِ عِشْرُونَ شَعْرَةً بَيْضَاءَ. (ق,ت)', 'അനസുബ്നുമാലിക്(റ): റസൂൽ(സ) കൂടുതൽ നീളമുള്ളവരോ വളരെ കുറിയവരോ ആയിരുന്നില്ല. അവിടുന്ന് അമിതമായി വെളുപ്പ് നിറമുള്ളവരോ തവിട്ട് നിറമുള്ളവരോ ആയിരുന്നില്ല. അവിടുന്ന് മുടി ജടപിടിച്ചവരോ, തീരെ മുടിയിൽ ചുരുളില്ലാത്തവരോ ആയിരുന്നില്ല. നാൽപതാം വയസ്സിന്റെ ആദ്യത്തിൽ തിരുമേനി(സ)യെ അല്ലാഹു പ്രവാചകനായി നിയോഗിച്ചു. അവിടുന്ന് മക്കയിൽ പത്ത് വർഷവും മദീനയിൽ പത്ത് വർഷവും താമസിച്ചു. അറുപതാം വയസ്സിന്റെ തുടക്കത്തിൽ അവിടുന്ന് വഫാതായി. ആ സമയത്ത് അവിടുത്തെ തലയിലും താടിയിലുമായി നെരച്ച ഇരുപത് മുടിപോലും ഉണ്ടായിരുന്നില്ല. (ബു,മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُنْزِلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ أَرْبَعِينَ سَنَةً، فَمَكَثَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ سَنَةً ثُمَّ أُمِرَ بِالْهِجْرَةِ، فَهَاجَرَ إِلَى الْمَدِينَةِ فَمَكَثَ بِهَا عَشْرَ سِنِينَ، ثُمَّ تُوُفِّيَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നാൽപത് വയസ്സുള്ളപ്പോഴാണ് നബി(സ)ക്ക് ഖുർആൻ ഇറക്കപ്പെട്ടത്. അവിടുന്ന് പതിമൂന്ന് വർഷം മക്കയിൽ ജീവിച്ചു. ശേഷം ഹിജ്റ പോകാൻ കൽപിക്കപ്പെട്ടു. അപ്പോൾ മദീനയിലേക്ക് ഹിജ്റ പോയി. അവിടെ പത്ത് വർഷം ജീവിച്ചു. ശേഷം അവിടുന്ന് വഫാതായി. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ [سَنَةً] يُوحَى إِلَيْهِ، وَبِالْمَدِينَةِ عَشْرًا، وَمَاتَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ [سَنَةً]. (ق,ت)', 'ഇബ്നു അബ്ബാസ്(റ): വഹ്യ് അവതരിക്കുന്ന അവസ്ഥയിൽ (നുബുവ്വതിന് ശേഷം) റസൂൽ(സ) മക്കയിൽ പതിമൂന്ന് വർഷവും മദീനയിൽ പത്ത് വർഷവും താമസിച്ചു. അറുപത്തിമൂന്ന് വയസ്സുള്ളപ്പോഴാണ് അവിടുന്ന് വഫാതായത്. (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], 'سَنَةً', null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ خَمْسَ عَشْرَةَ سَنَةً، يَسْمَعُ الصَّوْتَ وَيَرَى الضَّوْءَ سَبْعَ سِنِينَ، وَلَا يَرَى شَيْئًا، وَثَمَانَ سِنِينَ يُوحَى إِلَيْهِ، وَأَقَامَ بِالْمَدِينَةِ عَشْرًا. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മക്കയിൽ പതിനഞ്ച് വർഷം താമസിച്ചു. ഏഴു വർഷം തിരുമേനി(സ) ശബ്ദം കേൾക്കുകയും പ്രകാശം കാണുകയും ചെയ്തുകൊണ്ടിരുന്നു. എന്നാൽ മറ്റൊന്നും കാണുമായിരുന്നില്ല. എട്ട് വർഷം വഹ്യ് അവതരിക്കുന്ന അവസ്ഥയിലും തിരുമേനി(സ) താമസിച്ചു. മദീനയിൽ റസൂൽ(സ) പത്ത് വർഷം താമസിച്ചു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ الْحَارِثَ بْنَ هِشَامٍ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ يَأْتِيكَ الْوَحْيُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْيَانًا يَأْتِينِي فِي مِثْلِ صَلْصَلَةِ الْجَرَسِ، وَهُوَ أَشَدُّهُ عَلَيَّ، وَأَحْيَانًا يَتَمَثَّلُ لِيَ الْمَلَكُ رَجُلًا فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ". قَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْزِلُ عَلَيْهِ الْوَحْيُ فِي الْيَوْمِ ذِي الْبَرْدِ الشَّدِيدِ، فَيَفْصِمُ عَنْهُ وَإِنَّ جَبِينَهُ لَيَتَفَصَّدُ عَرَقًا. (ق,ت,ن)', 'ആഇശ(റ): ഹാരിസുബ്നു ഹിശാം(റ) നബി(സ)യോട് ചോദിച്ചു: അങ്ങേക്ക് എങ്ങനെയാണ് വഹ്യ് അവതരിക്കുന്നത്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പലപ്പോഴും മണിമുഴക്കം പോലെ (ഒന്നിൽ) അത് എനിക്ക് അവതരിക്കുന്നു. അതാണ് എനിക്ക് കൂടുതൽ പ്രയാസകരമായി അനുഭവപ്പെടാറ്. മറ്റു ചിലപ്പോൾ മലക്ക് ഒരു മനുഷ്യന്റെ രൂപം സ്വീകരിച്ച് എന്റെ അടുത്ത് വരികയും എന്നോട് സംസാരിക്കുകയും ചെയ്യും. ആ മലക്ക് പറയുന്ന കാര്യം ഞാൻ മനസ്സിലാക്കി വെക്കും." ആഇശ(റ) പറയുന്നു: കൊടും തണുപ്പുള്ള ദിവസങ്ങളിൽ റസൂൽ(സ)ക്ക് വഹ്യ് അവതരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അങ്ങനെ ആ വഹ്യ് നീങ്ങുമ്പോഴേക്ക് അവിടുത്തെ നെറ്റിത്തടത്തിൽനിന്ന് വിയർപ്പ് ഒലിച്ചിട്ടുണ്ടാവും. (ബു,മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 296, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا قَالَتْ: أَوَّلُ مَا ابْتُدِيَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ النُّبُوَّةِ – حِينَ أَرَادَ اللَّهُ كَرَامَتَهُ وَرَحْمَةَ الْعِبَادِ بِهِ – أَنْ لَا يَرَى شَيْئًا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، فَمَكَثَ عَلَى ذَلِكَ مَا شَاءَ اللَّهُ أَنْ يَمْكُثَ، وَحُبِّبَ إِلَيْهِ الْخَلْوَةُ، فَلَمْ يَكُنْ شَيْءٌ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَخْلُوَ. (ق,ت)', 'ആഇശ(റ): റസൂൽ(സ)യെ ആദരിക്കുവാനും തിരുമേനി(സ) കാരണമായി അടിമകൾക്ക് അനുഗ്രഹം ചെയ്യുവാനും അല്ലാഹു ഉദ്ദേശിച്ചപ്പോൾ പ്രവാചകത്വത്തിൽ നിന്ന് നബി(സ)ക്ക് ആദ്യമായി വെളിവായ കാര്യം ഇതായിരുന്നു: തിരുമേനി(സ) സ്വപ്നത്തിൽ ദർശിക്കുന്ന ഏതു കാര്യവും പകൽവെളിച്ചം പോലെ പുലർന്നുകൊണ്ടിരുന്നു. ഈ അവസ്ഥയിൽ തിരുമേനി(സ) അല്ലാഹു ഉദ്ദേശിച്ച അത്രയും കാലം കഴിച്ചുകൂട്ടി. അവിടത്തേക്ക് ഏകാന്തത ഇഷ്ടമായി മാറി. ഏകാന്തനായി ഇരിക്കുന്നതിനേക്കാൾ അവിടത്തേക്ക് ഇഷ്ടപ്പെട്ട ഒരു കാര്യവും ഉണ്ടായിരുന്നില്ല. (ബു,മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ مِنْ قَبْلِي، كَمَثَلِ رَجُلٍ بَنَى بُنْيَانًا فَأَحْسَنَهُ وَأَجْمَلَهُ، إِلَّا مَوْضِعَ لَبِنَةٍ مِنْ زَاوِيَةٍ مِنْ زَوَايَاهُ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ وَيَقُولُونَ: هَلَّا وُضِعَتْ هَذِهِ اللَّبِنَةُ؟ قَالَ: فَأَنَا اللَّبِنَةُ، وَأَنَا خَاتِمُ النَّبِيِّينَ". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെയും എനിക്ക് മുമ്പുള്ള പ്രവാചകരുടെയും ഉപമ, നല്ല നിലയിൽ, നല്ല ഭംഗിയിൽ ഒരു വീടുണ്ടാക്കിയ ഒരാളുടെ ഉപമയാണ്. അതിന്റെ മൂലകളിൽ ഒന്നിൽ ഒരു ഇഷ്ടികയുടെ സ്ഥലം അവശേഷിച്ചു. ജനങ്ങൾ, അതിനെ ചുറ്റാൻ തുടങ്ങി. അവരത് കണ്ട് അത്ഭുതം കൂറി പറയുന്നു: ഈ ഇഷ്ടികകൂടി വെക്കാത്തത് എന്തുകൊണ്ടാണ്?" നബി(സ) പറയുന്നു: "ഞാനാണ് ആ ഇഷ്ടിക. ഞാൻ അന്ത്യപ്രവാചകനാണ്." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مَثَلَ مَا بَعَثَنِي اللَّهُ بِهِ [عَزَّ وَجَلَّ] مِنَ الْهُدَى وَالْعِلْمِ، كَمَثَلِ غَيْثٍ أَصَابَ أَرْضًا، فَكَانَتْ مِنْهَا طَائِفَةٌ طَيِّبَةٌ قَبِلَتِ الْمَاءَ، فَأَنْبَتَتِ الْكَلَأَ وَالْعُشْبَ الْكَثِيرَ. وَكَانَ مِنْهَا أَجَادِبُ أَمْسَكَتِ الْمَاءَ، فَنَفَعَ اللَّهُ بِهَا النَّاسَ فَشَرِبُوا مِنْهَا وَسَقَوْا وَزَرَعُوا. وَأَصَابَ طَائِفَةً مِنْهَا أُخْرَى، إِنَّمَا هِيَ قِيعَانٌ لَا تُمْسِكُ مَاءً وَلَا تُنْبِتُ كَلَأً. فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ وَنَفَعَهُ بِمَا بَعَثَنِي اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ، وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا، وَلَمْ يَقْبَلْ هُدَى اللَّهِ الَّذِي أُرْسِلْتُ بِهِ". (م)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു എന്നെ ജ്ഞാനവും സന്മാർഗവുമായി അയച്ചതിന്റെ ഉപമ ഒരു ഭൂമിയിൽ വർഷിച്ച മഴയുടെ ഉപമയാണ്. ആ ഭൂമിയിൽ വെള്ളം സ്വീകരിക്കുന്ന നല്ല സ്ഥലമുണ്ട്. ആ സ്ഥലം ഒരുപാട് പുല്ലും ചെടിയും മുളപ്പിച്ചു. ആ ഭൂമിയിൽ വെള്ളം പിടിച്ചുവെക്കുന്ന ഉറച്ച സ്ഥലങ്ങളുണ്ട്. അതുകൊണ്ട് ജനങ്ങൾക്ക് അല്ലാഹു ഉപകാരം നൽകി. അവരതിൽ നിന്ന് കുടിക്കുകയും നനക്കുകയും മേയ്ക്കുകയും ചെയ്തു. ഭൂമിയുടെ വേറൊരു ഭാഗത്തും മഴ വർഷിച്ചു. അത് വെള്ളം പിടിച്ച് നിർത്തുകയോ പുല്ല് മുളപ്പിക്കുകയോ ചെയ്യാത്ത സമതലമാണ്. ഇതാണ് അല്ലാഹുവിന്റെ ദീനിൽ (മതത്തിൽ) ജ്ഞാനം നേടുകയും അല്ലാഹു എന്നെ നിയോഗിച്ചത് കൊണ്ട് അല്ലാഹു ഉപകാരം നൽകുകയും അങ്ങനെ പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്തവന്റെയും ഇത് അവഗണിക്കുകയും എന്നെ അല്ലാഹു നിയോഗിച്ച സന്മാർഗം തിരസ്കരിക്കുകയും ചെയ്തവന്റെ ഉപമ." (മു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['م']::text[], array['മു']::text[], 'عَزَّ وَجَلَّ', null, 297, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مَثَلِي وَمَثَلَ مَا بَعَثَنِي اللَّهُ بِهِ كَمَثَلِ رَجُلٍ أَتَى قَوْمَهُ، فَقَالَ: يَا قَوْمِ إِنِّي رَأَيْتُ الْجَيْشَ بِعَيْنَيَّ، وَإِنِّي أَنَا النَّذِيرُ الْعُرْيَانُ، فَالنَّجَاءَ. فَأَطَاعَهُ طَائِفَةٌ مِنْ قَوْمِهِ فَأَدْلَجُوا فَانْطَلَقُوا عَلَى مُهْلَتِهِمْ، وَكَذَّبَتْ طَائِفَةٌ مِنْهُمْ فَأَصْبَحُوا مَكَانَهُمْ فَصَبَّحَهُمُ الْجَيْشُ، فَأَهْلَكَهُمْ وَاجْتَاحَهُمْ، فَذَلِكَ مَثَلُ مَنْ أَطَاعَنِي وَاتَّبَعَ مَا جِئْتُ بِهِ، وَمَثَلُ مَنْ عَصَانِي وَكَذَّبَ مَا جِئْتُ بِهِ مِنَ الْحَقِّ". (م)', 'അബൂമൂസാ(റ): നബി(സ) പറഞ്ഞു: "എന്റെയും അല്ലാഹു എന്നെ നിയോഗിച്ചതിന്റെയും ഉപമ തന്റെ സമൂഹത്തിന്റെ അടുത്തുചെന്ന ഒരാളുടെ ഉപമയാണ്. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: എന്റെ സമൂഹമേ, ഞാൻ ശത്രുസൈന്യത്തെ എന്റെ കണ്ണ് കൊണ്ട് കണ്ടിരിക്കുന്നു. ഞാൻ നിങ്ങൾക്ക് വ്യക്തമായ മുന്നറിയിപ്പുകാരനാണ്. അതുകൊണ്ട് നിങ്ങൾ രക്ഷപ്പെടുക. തന്റെ സമൂഹത്തിലെ ഒരു വിഭാഗം അയാളെ അനുസരിച്ചു. തങ്ങളുടെ സൗകര്യാർത്ഥം അവർ ഓടിരക്ഷപ്പെട്ടു. തന്റെ സമൂഹത്തിലെ ഒരു വിഭാഗം നിഷേധിക്കുകയും അതേ സ്ഥലങ്ങളിൽ തന്നെ നിൽക്കുകയും ചെയ്തു. അവരെ സൈന്യം പിടികൂടി നശിപ്പിക്കുകയും ഇല്ലായ്മ ചെയ്യുകയും ചെയ്തു. ഇത് എന്നെ അനുസരിക്കുകയും ഞാൻ കൊണ്ടുവന്നത് പിൻപറ്റുകയും ചെയ്തവന്റെ ഉപമയും എന്നെ ധിക്കരിക്കുകയും ഞാൻ കൊണ്ടുവന്ന സത്യം നിഷേധിക്കുകയും ചെയ്തവന്റെ ഉപമയുമാണ്." (മു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ، فَكَانَ يَجْمَعُ الصَّلَاةَ، فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، حَتَّى إِذَا كَانَ يَوْمًا أَخَّرَ الصَّلَاةَ، ثُمَّ خَرَجَ فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ دَخَلَ، ثُمَّ خَرَجَ بَعْدَ ذَلِكَ فَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، ثُمَّ قَالَ: "إِنَّكُمْ سَتَأْتُونَ غَدًا إِنْ شَاءَ اللَّهُ [تَعَالَى] عَيْنَ تَبُوكَ، وَإِنَّكُمْ لَنْ تَأْتُوهَا حَتَّى يُضْحِيَ النَّهَارُ، فَمَنْ جَاءَهَا مِنْكُمْ فَلَا يَمَسَّ مِنْ مَائِهَا شَيْئًا حَتَّى آتِيَ". فَجِئْنَاهَا وَقَدْ سَبَقَنَا إِلَيْهَا رَجُلَانِ، وَالْعَيْنُ مِثْلُ الشِّرَاكِ، تَبِضُّ بِشَيْءٍ مِنْ مَاءٍ، قَالَ: فَسَأَلَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مَسَسْتُمَا مِنْ مَائِهَا شَيْئًا". قَالَا: نَعَمْ، فَسَبَّهُمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ لَهُمَا مَا شَاءَ اللَّهُ أَنْ يَقُولَ، قَالَ: ثُمَّ غَرَفُوا بِأَيْدِيهِمْ مِنَ الْعَيْنِ قَلِيلًا قَلِيلًا، حَتَّى اجْتَمَعَ [فِي] شَيْءٍ، [قَالَ]: وَغَسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ يَدَيْهِ وَوَجْهَهُ ثُمَّ أَعَادَهُ فِيهَا، فَجَرَتِ الْعَيْنُ بِمَاءٍ مُنْهَمِرٍ – أَوْ قَالَ: غَزِيرٍ، شَكَّ أَبُو عَلِيٍّ أَيُّهُمَا قَالَ – حَتَّى اسْتَقَى النَّاسُ، ثُمَّ قَالَ: "يُوشِكُ يَا مُعَاذُ – إِنْ طَالَتْ بِكَ حَيَاةٌ – أَنْ تَرَى مَا هَاهُنَا قَدْ مُلِئَ جِنَانًا". (م)', 'മുആദുബ്നു ജബൽ(റ): തബൂക് യുദ്ധ വർഷം ഞങ്ങൾ നബി(സ)യുടെ കൂടെ പുറപ്പെട്ടു. തിരുമേനി(സ) നിസ്കാരം ജംഅ് ചെയ്തിരുന്നു. നബി(സ) ളുഹ്റും അസ്വറും ഒരുമിച്ച് നിസ്കരിച്ചു. മഗ്രിബും ഇശാഉം ഒരുമിച്ച് നിസ്കരിച്ചു. അങ്ങനെ ഒരു ദിവസമായാൽ അവിടുന്ന് നിസ്കാരം പിന്തിച്ചിരുന്നു. പിന്നെ അവിടുന്ന് പുറപ്പെടുകയും ളുഹ്റും അസ്വറും ഒരുമിച്ച് നിസ്കരിക്കുകയും ചെയ്തു. പിന്നെ നബി(സ) പ്രവേശിച്ചു. പിന്നെ അതിനുശേഷം പുറപ്പെടുകയും മഗ്രിബും ഇശായും ഒരുമിച്ച് നിസ്കരിക്കുകയും ചെയ്തു. പിന്നെ അവിടുന്ന് പറഞ്ഞു: "ഇൻശാഅല്ലാഹ്, നാളെ നിങ്ങൾ തബൂക്കിലെ തടാകത്തിലെത്തും. പ്രഭാതം ഉദിച്ചുയർന്ന ശേഷമേ നിങ്ങളവിടെ എത്തുകയുള്ളൂ. അരുവിയുടെ അടുത്ത് നിങ്ങളാരെങ്കിലും എത്തിയാൽ ഞാൻ വരുന്നതുവരെ അതിലെ വെള്ളം ഒരിക്കലും തൊടരുത്." ഞങ്ങളവിടെ ചെന്നു. ഞങ്ങൾക്കു മുമ്പ് അതിന്റെയടുത്ത് രണ്ടാളുകൾ എത്തിയിട്ടുണ്ട്. അരുവി ചെരുപ്പിന്റെ വാറുപോലെയായിരുന്നു. അതിൽ അൽപം വെള്ളം ഒഴുകുന്നുണ്ട്. അപ്പോൾ അവർ രണ്ടുപേരോടും റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ അരുവിയിലെ വെള്ളം അൽപമെങ്കിലും തൊട്ടുവോ?" അവർ പറഞ്ഞു: അതെ. അപ്പോൾ റസൂൽ(സ) അവരെ ആക്ഷേപിക്കുകയും അവരോട് പറയേണ്ടത് പറയുകയും ചെയ്തു. മുആദുബ്നു ജബൽ(റ) പറയുന്നു: പിന്നെ അവർ അരുവിയിൽനിന്ന് അൽപാൽപം വെള്ളം കോരിയെടുത്തു. അങ്ങനെ അതെല്ലാം ഒരു വസ്തുവിൽ കൂടിച്ചേർന്നു. തടാകത്തിൽ റസൂൽ(സ) അവിടുത്തെ ഇരു കരങ്ങളും മുഖവും കഴുകി. വെള്ളം അരുവിയിലേക്ക് തന്നെ ഒഴിച്ചു. അപ്പോൾ അരുവി അതിശക്തമായ വെള്ളത്തോടെ ഒലിച്ചു. അങ്ങനെ ജനങ്ങൾ കുടിച്ചു. പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "ഓ മുആദേ, നിനക്ക് ആയുസ്സുണ്ടെങ്കിൽ ഇവിടെ തോട്ടങ്ങൾ തിങ്ങിക്കൂടുന്നത് നിനക്ക് കാണാം." (മു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 298, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عُرْوَةَ الْبَارِقِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُ دِينَارًا يَشْتَرِي لَهُ بِهِ شَاةً، فَاشْتَرَى لَهُ بِهِ شَاتَيْنِ، فَبَاعَ إِحْدَاهُمَا بِدِينَارٍ، وَجَاءَهُ بِدِينَارٍ وَشَاةٍ. فَدَعَا لَهُ بِالْبَرَكَةِ فِي بَيْعِهِ، فَكَانَ لَوِ اشْتَرَى التُّرَابَ لَرَبِحَ فِيهِ. (خ)', 'ഉർവതുൽ ബാരിഖി(റ): നബി(സ) അദ്ദേഹത്തിന് ഒരു ആടിനെ വാങ്ങാൻവേണ്ടി ഒരു ദീനാർ നൽകി. അദ്ദേഹം അതുകൊണ്ട് രണ്ടാടിനെ വാങ്ങി. അവയിൽ ഒന്നിനെ ഒരു ദീനാറിന് വിറ്റു. അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ഒരു ദീനാറും ഒരു ആടുമായി വന്നു. അദ്ദേഹത്തിന് വിൽപനയിൽ അനുഗ്രഹമുണ്ടാകാൻ നബി(സ) പ്രാർത്ഥിച്ചു. ശേഷം അദ്ദേഹം മണ്ണ് വാങ്ങിയാലും അതിൽ ലാഭമുണ്ടാകുമായിരുന്നു. (ബു)', 'عُرْوَةَ الْبَارِقِيِّ', 'ഉർവതുൽ ബാരിഖി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَانَتْ صَلَاةُ الْعَصْرِ، وَالْتَمَسَ النَّاسُ الْوَضُوءَ فَلَمْ يَجِدُوا، فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ، فَوَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ فِي ذَلِكَ الْإِنَاءِ، وَأَمَرَ النَّاسَ أَنْ يَتَوَضَّئُوا مِنْهُ، قَالَ: فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ، فَتَوَضَّأَ النَّاسُ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ. (ق,ت,ن)', 'അനസുബ്നു മാലിക്(റ): അസ്വർ നമസ്കാര സമയമടുക്കവെ ഞാൻ റസൂൽ(സ)യെ കണ്ടു. ജനങ്ങൾ വുളൂ ചെയ്യാനുള്ള വെള്ളമന്വേഷിച്ചെങ്കിലും അവർക്കത് കിട്ടിയില്ല. അങ്ങനെ റസൂൽ(സ)യുടെ അടുക്കൽ (കുറച്ച്) വെള്ളം കൊണ്ടുവന്നു. റസൂൽ(സ) അവിടുത്തെ കരം ആ പാത്രത്തിൽ വെച്ചു. തിരുമേനി(സ) ജനങ്ങളോട് അതിൽനിന്ന് വുളു ചെയ്യാൻ കൽപിച്ചു. നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യുടെ വിരലുകൾക്കിടയിലൂടെ വെള്ളം ഉറവപൊട്ടി വരുന്നത് ഞാൻ കണ്ടു. അങ്ങനെ ജനങ്ങളിലെ അവസാനത്തെയാൾ പോലും വുളു ചെയ്തു. (ബു,മു,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّكُمْ تَعُدُّونَ الْآيَاتِ عَذَابًا، وَإِنَّا كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَرَكَةً، لَقَدْ كُنَّا نَأْكُلُ الطَّعَامَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَسْمَعُ تَسْبِيحَ الطَّعَامِ. قَالَ: وَأُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ، فَوَضَعَ يَدَهُ فِيهِ، فَجَعَلَ الْمَاءُ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "حَيَّ عَلَى الْوَضُوءِ الْمُبَارَكِ وَالْبَرَكَةُ مِنَ السَّمَاءِ". حَتَّى تَوَضَّأْنَا كُلُّنَا. (خ,ت)', 'അബ്ദുല്ലാഹ്(റ): നിങ്ങൾ ദൃഷ്ടാന്തങ്ങൾ ശിക്ഷയായി കാണുന്നു. റസൂൽ(സ)യുടെ കാലത്ത് അവ ഞങ്ങൾ പുണ്യമായി കണ്ടിരുന്നു. തീർച്ചയായും ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ഭക്ഷണം കഴിക്കുമ്പോൾ ഭക്ഷണത്തിന്റെ തസ്ബീഹ് കേട്ടിരുന്നു. നിവേദകൻ പറയുന്നു: നബി(സ)യുടെ അടുത്ത് ഒരു പാത്രം കൊണ്ടുവരപ്പെട്ടു. നബി(സ)യുടെ കൈ അതിൽ വെച്ചു. വെള്ളം വിരലുകൾക്കിടയിൽനിന്ന് ഉറവപൊട്ടിയൊഴുകാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അനുഗ്രഹീതമായ വുളൂവിന്റെ ജലത്തിലേക്കും ആകാശത്തിൽ നിന്നുള്ള അനുഗ്രഹത്തിലേക്കും നിങ്ങൾ കടന്നുവരിക." അങ്ങനെ ഞങ്ങളെല്ലാവരും വുളു ചെയ്തു. (ബു,തു)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ലാഹ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 299, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ بِالزَّوْرَاءِ – قَالَ: وَالزَّوْرَاءُ بِالْمَدِينَةِ عِنْدَ السُّوقِ وَالْمَسْجِدِ فِيمَا ثَمَّهْ – دَعَا بِقَدَحٍ فِيهِ مَاءٌ، فَوَضَعَ كَفَّهُ فِيهِ، فَجَعَلَ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ، فَتَوَضَّأَ جَمِيعُ أَصْحَابِهِ. قَالَ: قُلْتُ: كَمْ كَانُوا يَا أَبَا حَمْزَةَ؟ قَالَ: كَانُوا زُهَاءَ الثَّلَاثِ مِائَةٍ. (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യും അവിടുത്തെ അനുചരരും സൗറാഇലായിരുന്നു. നിവേദകൻ പറയുന്നു: സൗറാഅ് മദീനയിലെ അങ്ങാടിക്കും അവിടുത്തെ പള്ളിക്കും അടുത്താണ് സ്ഥിതി ചെയ്യുന്നത്. റസൂൽ(സ) വെള്ളമുള്ള ഒരു പാത്രം കൊണ്ടുവരാൻ കൽപിച്ചു. നബി(സ)യുടെ കരം അതിൽ വെച്ചു. അപ്പോൾ അവിടുത്തെ വിരലുകളിൽ നിന്ന് ഉറവ പൊട്ടിയൊഴുകാൻ തുടങ്ങി. അങ്ങനെ മുഴുവൻ അനുചരരും വുളൂ ചെയ്തു. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: അബൂഹംസാ, അവർ എത്ര പേരുണ്ടായിരുന്നു? അദ്ദേഹം പറഞ്ഞു: അവർ ഏകദേശം മുന്നൂറ് പേരുണ്ടായിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نَعُدُّ الْآيَاتِ بَرَكَةً، وَأَنْتُمْ تَعُدُّونَهَا تَخْوِيفًا، كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَقَلَّ الْمَاءُ، فَقَالَ: اطْلُبُوا فَضْلَةً مِنْ مَاءٍ، فَجَاءُوا بِإِنَاءٍ فِيهِ مَاءٌ قَلِيلٌ، فَأَدْخَلَ يَدَهُ فِي الْإِنَاءِ ثُمَّ قَالَ: حَيَّ عَلَى الطَّهُورِ الْمُبَارَكِ، وَالْبَرَكَةُ مِنَ اللَّهِ، فَلَقَدْ رَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَقَدْ كُنَّا نَسْمَعُ تَسْبِيحَ الطَّعَامِ وَهُوَ يُؤْكَلُ. (خ)', 'അബ്ദുല്ലാഹ്(റ): ഞങ്ങൾ ദൃഷ്ടാന്തങ്ങൾ അനുഗ്രഹമായി ഗണിച്ചിരുന്നു. നിങ്ങളതിനെ ഭീതിപ്പെടുത്തലായി കാണുന്നു. ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഒരു യാത്രയിലായിരുന്നു. വെള്ളം കുറവുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ശേഷിച്ച വെള്ളം അന്വേഷിക്കുക." അൽപം വെള്ളമുള്ള പാത്രവുമായി അവർ വന്നു. നബി(സ) ആ പാത്രത്തിൽ കൈ പ്രവേശിപ്പിച്ചു. പിന്നെ അവിടുന്ന് പറഞ്ഞു: "പവിത്രമായ ശുദ്ധജലത്തിലേക്കും അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിലേക്കും നിങ്ങൾ കടന്നുവരിക." റസൂൽ(സ)യുടെ വിരലുകൾക്കിടയിലൂടെ വെള്ളം ഉറവ പൊട്ടുന്നത് ഞാൻ കാണുക തന്നെ ചെയ്തു. ഭക്ഷണം കഴിക്കുമ്പോൾ അതിന്റെ തസ്ബീഹ് നിശ്ചയം ഞങ്ങൾ കേൾക്കാറുണ്ടായിരുന്നു. (ബു)', 'عَبْدِاللَّهِ', 'അബ്ദുല്ലാഹ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَطْعِمُهُ، فَأَطْعَمَهُ شَطْرَ وَسْقِ شَعِيرٍ، فَمَا زَالَ الرَّجُلُ يَأْكُلُ مِنْهُ وَامْرَأَتُهُ وَضَيْفُهُمَا حَتَّى كَالَهُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَوْ لَمْ تَكِلْهُ لَأَكَلْتُمْ مِنْهُ، وَلَقَامَ لَكُمْ". (م)', 'ജാബിർ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് ഭക്ഷണം ആവശ്യപ്പെട്ടുകൊണ്ട് വന്നു. നബി(സ) പകുതി വസ്ഖ് ബാർളി അയാളെ ഭക്ഷിപ്പിച്ചു. അദ്ദേഹവും അദ്ദേഹത്തിന്റെ ഭാര്യയും അവരുടെ അതിഥിയും അതിൽ നിന്ന് ഭക്ഷിച്ചുകൊണ്ടേയിരുന്നു. അങ്ങനെ അദ്ദേഹമത് അളന്നു. ശേഷം അദ്ദേഹം അടുത്ത് വന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളത് അളന്നില്ലായിരുന്നെങ്കിൽ അതിൽ നിന്ന് ഇനിയും ഭക്ഷിക്കുകയും നിങ്ങൾക്കത് ബാക്കിയുണ്ടാവുകയും ചെയ്യുമായിരുന്നു." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 300, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا حُفِرَ الْخَنْدَقُ رَأَيْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا، فَانْكَفَأْتُ إِلَى امْرَأَتِي فَقُلْتُ لَهَا: هَلْ عِنْدَكِ شَيْءٌ؟ فَإِنِّي رَأَيْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا شَدِيدًا، فَأَخْرَجَتْ لِي جِرَابًا فِيهِ صَاعٌ مِنْ شَعِيرٍ، وَلَنَا بُهَيْمَةٌ دَاجِنٌ، قَالَ: فَذَبَحْتُهَا وَطَحَنَتْ فَفَرَغَتْ إِلَى فَرَاغِي، فَقَطَّعْتُهَا فِي بُرْمَتِهَا، ثُمَّ وَلَّيْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: لَا تَفْضَحْنِي بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَنْ مَعَهُ، قَالَ: فَجِئْتُهُ فَسَارَرْتُهُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا قَدْ ذَبَحْنَا بُهَيْمَةً لَنَا وَطَحَنْتُ صَاعًا مِنْ شَعِيرٍ كَانَ عِنْدَنَا، فَتَعَالَ أَنْتَ فِي نَفَرٍ مَعَكَ. فَصَاحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "يَا أَهْلَ الْخَنْدَقِ، إِنَّ جَابِرًا قَدْ صَنَعَ لَكُمْ سُورًا، فَحَيَّ هَلًا بِكُمْ". وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُنْزِلُنَّ بُرْمَتَكُمْ، وَلَا تَخْبِزُنَّ عَجِينَتَكُمْ حَتَّى أَجِيءَ". فَجِئْتُ وَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْدُمُ النَّاسَ، حَتَّى جِئْتُ امْرَأَتِي، فَقَالَتْ: بِكَ وَبِكَ! فَقُلْتُ: قَدْ فَعَلْتُ الَّذِي قُلْتِ لِي، فَأَخْرَجَتْ لَهُ عَجِينَتَنَا فَبَصَقَ فِيهَا وَبَارَكَ، ثُمَّ عَمَدَ إِلَى بُرْمَتِنَا فَبَصَقَ فِيهَا وَبَارَكَ، ثُمَّ قَالَ: "ادْعِي خَابِزَةً فَلْتَخْبِزْ مَعَكِ، وَاقْدَحِي مِنْ بُرْمَتِكُمْ وَلَا تُنْزِلُوهَا". وَهُمْ أَلْفٌ، فَأُقْسِمُ بِاللَّهِ لَأَكَلُوا حَتَّى تَرَكُوهُ، وَانْحَرَفُوا وَإِنَّ بُرْمَتَنَا لَتَغِطُّ كَمَا هِيَ، وَإِنَّ عَجِينَتَنَا – أَوْ كَمَا قَالَ الضَّحَّاكُ – لَتُخْبَزُ كَمَا هُوَ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): കിടങ്ങ് കുഴിക്കപ്പെട്ടുകൊണ്ടിരിക്കെ (ഖന്ദഖ് യുദ്ധത്തിൽ) നബി(സ)ക്ക് വിശക്കുന്നുണ്ടെന്ന് എനിക്ക് മനസ്സിലായി. അപ്പോൾ ഞാനെന്റെ ഭാര്യയുടെ അടുത്തുവന്ന് അവളോട് ചോദിച്ചു: നിന്റെയടുത്ത് വല്ലതുമുണ്ടോ? റസൂൽ(സ)ക്ക് നല്ല വിശപ്പുള്ളതായി എനിക്ക് മനസ്സിലായി. അപ്പോൾ അവൾ എനിക്ക് ഒരു സ്വാഅ് ബാർളിയുള്ള ഒരു കുട്ട എടുത്തുതന്നു. ഞങ്ങൾക്ക് ഒരു ചെറിയ വളർത്തുമൃഗമുണ്ട്. അങ്ങനെ ഞാനതിനെ അറുത്തു. ഞാൻ അറുത്തുകഴിഞ്ഞപ്പോഴേക്ക് ഭാര്യ ബാർളി പൊടിച്ചുകഴിഞ്ഞു. മാംസം ഞാൻ ചട്ടിയിലിട്ട് കഷ്ണിച്ചു. പിന്നെ ഞാൻ റസൂൽ(സ)യുടെയടുത്തേക്ക് തിരിച്ചു. അവൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലിനെയും അവിടുത്തെ കൂടെയുള്ളവരെയുംകൊണ്ട് നിങ്ങളെന്നെ വഷളാക്കരുത്. ഞാൻ നബി(സ)യുടെ അടുത്തുചെന്ന് അവിടുത്തോട് രഹസ്യമായി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളുടെ ഒരു ചെറിയ ആടിനെ ഞങ്ങൾ അറുത്തിരിക്കുന്നു. ഞങ്ങളുടെ പക്കലുണ്ടായിരുന്ന ഒരു സ്വാഅ് ബാർളി എന്റെ ഭാര്യ ഇടിച്ചിട്ടുണ്ട്. അതിനാൽ അങ്ങയുടെ കൂടെ അൽപം ആളുകളുമായി അങ്ങ് വന്നാലും. അപ്പോൾ റസൂൽ(സ) വിളിച്ചുപറഞ്ഞു: "ഓ ഖന്ദഖുകാരേ, ജാബിർ നിങ്ങൾക്കുവേണ്ടി സദ്യയൊരുക്കിയിരിക്കുന്നു. അതുകൊണ്ട് നിങ്ങൾ വരിക." റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ വരുന്നതുവരെ നിങ്ങൾ കലമിറക്കുകയോ മാവ് കുഴക്കുക്യോ ചെയ്യരുത്." അങ്ങനെ ഞാൻ വന്നു. റസൂൽ(സ) ജനങ്ങൾക്ക് മുന്നിലായി വന്നു. അങ്ങനെ ഞാനെന്റെ ഭാര്യയുടെ അടുത്തുചെന്നു. അപ്പോൾ അവൾ ചോദിച്ചു: നിങ്ങളെന്താണീ ചെയ്തത്? അപ്പോൾ ഞാൻ പറഞ്ഞു: നീയെന്നോട് പറഞ്ഞത് ഞാൻ ചെയ്തു. നബി(സ)ക്ക് ഞാൻ ഞങ്ങളുടെ മാവെടുത്തുകൊടുത്തു. അവിടുന്നതിൽ തുപ്പുകയും ബറകത്ത് ചെയ്യുകയും പിന്നെ അവിടുന്ന് ഞങ്ങളുടെ ചട്ടിയുടെ അടുത്തുവന്ന് അതിൽ തുപ്പുകയും ബറകത്ത് ചെയ്യുകയും ചെയ്തു. പിന്നെ അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ പത്തിരി ഉണ്ടാക്കുന്ന ഒരു സ്ത്രീയെ വിളിക്കുക. അവൾ നിന്നോടൊപ്പം പത്തിരി ഉണ്ടാക്കട്ടെ. ചട്ടിയിൽ നിന്ന് കോരുക. ചട്ടി നിങ്ങൾ ഇറക്കരുത്." അവർ ആയിരം പേരുണ്ടായിരുന്നു. ഞാൻ അല്ലാഹുവിൽ സത്യം ചെയ്ത് പറയുന്നു: അവർ ഭക്ഷിക്കുകയും അങ്ങനെ ബാക്കി വരികയും ചെയ്തു. ശേഷം അവരെല്ലാം പിരിഞ്ഞുപോയി. എന്നിട്ടും ഞങ്ങളുടെ ചട്ടി അതുപോലെ തിളച്ചുകൊണ്ടിരിക്കുന്നുണ്ടായിരുന്നു. ഞങ്ങളുടെ മാവ് അതുപോലെ പത്തിരിയാക്കി പ്രത്തപ്പെടുന്നുമുണ്ടായിരുന്നു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثِينَ وَمِائَةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مَعَ أَحَدٍ مِنْكُمْ طَعَامٌ". فَإِذَا مَعَ رَجُلٍ صَاعٌ مِنْ طَعَامٍ أَوْ نَحْوُهُ، فَعُجِنَ، ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ مُشْعَانٌّ طَوِيلٌ بِغَنَمٍ يَسُوقُهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبَيْعٌ أَمْ عَطِيَّةٌ". أَوْ قَالَ: "أَمْ هِبَةٌ". فَقَالَ: لَا بَلْ بَيْعٌ، فَاشْتَرَى مِنْهُ شَاةً، فَصُنِعَتْ، وَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَوَادِ الْبَطْنِ أَنْ يُشْوَى، قَالَ: وَايْمُ اللَّهِ، مَا مِنَ الثَّلَاثِينَ وَمِائَةٍ إِلَّا حَزَّ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُزَّةً [حُزَّةً] مِنْ سَوَادِ بَطْنِهَا، إِنْ كَانَ شَاهِدًا أَعْطَاهُ، وَإِنْ كَانَ غَائِبًا خَبَأَ لَهُ، قَالَ: وَجَعَلَ قَصْعَتَيْنِ، فَأَكَلْنَا مِنْهُمَا أَجْمَعُونَ وَشَبِعْنَا، وَفَضَلَ فِي الْقَصْعَتَيْنِ، فَحَمَلْتُهُ عَلَى الْبَعِيرِ. أَوْ كَمَا قَالَ. (م)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ നൂറ്റിമുപ്പത് ആളുകളുണ്ടായിരുന്നു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങൾ ആരുടെ പക്കലെങ്കിലും ഭക്ഷണമുണ്ടോ?" അപ്പോൾ ഒരാളുടെ അടുത്ത് ഒരു സ്വാഅ് ഭക്ഷണമോ, അതുപോലോത്ത എന്തോ ഉണ്ട്. അത് മാവാക്കി കുഴച്ചു. പിന്നെ നീളമുള്ള മുടിയുള്ള ബഹുദൈവാരാധകനായ ഒരാൾ ഒരാടിനെ തെളിച്ചുവന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ഇത് വിൽക്കാനാണോ അതോ ദാനമാണോ?" അയാൾ പറഞ്ഞു; ഇത് വിൽക്കാനാണ്. നബി(സ) അയാളിൽ നിന്ന് ആടിനെ വാങ്ങി. അങ്ങനെ ആട് കറിവെച്ചു. നബി(സ) ആടിന്റെ കരൾ പൊരിക്കാൻ പറഞ്ഞു. നിവേദകൻ പറയുന്നു: ഞാൻ അല്ലാഹുവിൽ സത്യം ചെയ്ത് പറയുന്നു: ഞങ്ങൾ നൂറ്റിമുപ്പത് പേരിൽ ഓരോരുത്തർക്കും റസൂൽ(സ) ഒരു കഷ്ണം ആടിന്റെ കരൾ നൽകി. അവിടെ സന്നിഹിതരായവർക്ക് നൽകുകയും അവിടെ ഇല്ലാത്തവർക്ക് സൂക്ഷിച്ചുവെക്കുകയും ചെയ്തു. അത് രണ്ട് പാത്രത്തിലാക്കി വെച്ചു. ഞങ്ങൾ എല്ലാവരും അവയിൽ നിന്ന് ഭക്ഷിക്കുകയും വയർ നിറക്കുകയും ചെയ്തു. രണ്ട് പാത്രത്തിലും ഭക്ഷണം ബാക്കിവന്നു. അപ്പോൾ ഞാനത് ഒട്ടകപ്പുറത്ത് വഹിച്ചുകൊണ്ടുപോയി. (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'حُزَّةً', null, 302, 302, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَنَّ أَصْحَابَ الصُّفَّةِ كَانُوا نَاسًا فُقَرَاءَ، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَرَّةً: "مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ، وَمَنْ كَانَ عِنْدَهُ طَعَامُ أَرْبَعَةٍ فَلْيَذْهَبْ بِخَامِسٍ، بِسَادِسٍ". أَوْ كَمَا قَالَ، وَإِنَّ أَبَا بَكْرٍ جَاءَ بِثَلَاثَةٍ، وَانْطَلَقَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَشَرَةٍ وَأَبُو بَكْرٍ بِثَلَاثَةٍ، قَالَ: فَهُوَ وَأَنَا وَأَبِي وَأُمِّي، وَلَا أَدْرِي هَلْ قَالَ: وَامْرَأَتِي وَخَادِمٌ بَيْنَ بَيْتِنَا وَبَيْتِ أَبِي بَكْرٍ، [قَالَ]: وَإِنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ تَعَشَّى عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ لَبِثَ حَتَّى صُلِّيَتِ الْعِشَاءُ، ثُمَّ رَجَعَ فَلَبِثَ حَتَّى نَعِسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ بَعْدَمَا مَضَى مِنَ اللَّيْلِ مَا شَاءَ اللَّهُ، قَالَتْ لَهُ امْرَأَتُهُ: مَا حَبَسَكَ عَنْ أَضْيَافِكَ؟ – أَوْ قَالَتْ: ضَيْفِكَ – قَالَ: أَوَ مَا عَشَّيْتِهِمْ؟ قَالَتْ: أَبَوْا حَتَّى تَجِيءَ، قَدْ عَرَضُوا عَلَيْهِمْ فَغَلَبُوهُمْ، قَالَ: فَذَهَبْتُ أَنَا فَاخْتَبَأْتُ، وَقَالَ: يَا غُنْثَرُ، فَجَدَّعَ وَسَبَّ، وَقَالَ: كُلُوا لَا هَنِيئًا، وَقَالَ: وَاللَّهِ، لَا أَطْعَمُهُ أَبَدًا، قَالَ: وَايْمُ اللَّهِ مَا كُنَّا نَأْخُذُ مِنْ لُقْمَةٍ، إِلَّا رَبَا مِنْ أَسْفَلِهَا أَكْثَرَ مِنْهَا، قَالَ: [حَتَّى] شَبِعْنَا وَصَارَتْ أَكْثَرَ مِمَّا كَانَتْ قَبْلَ ذَلِكَ، فَنَظَرَ إِلَيْهَا أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، فَإِذَا هِيَ كَمَا هِيَ أَوْ أَكْثَرُ، قَالَ لِامْرَأَتِهِ: يَا أُخْتَ بَنِي فِرَاسٍ مَا هَذَا؟ قَالَتْ: لَا – وَقُرَّةِ عَيْنِي – لَهِيَ الْآنَ أَكْثَرُ مِنْهَا قَبْلَ ذَلِكَ بِثَلَاثِ مِرَارٍ. قَالَ: فَأَكَلَ مِنْهَا أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ وَقَالَ: إِنَّمَا كَانَ ذَلِكَ مِنَ الشَّيْطَانِ. يَعْنِي يَمِينَهُ، ثُمَّ أَكَلَ مِنْهَا لُقْمَةً، ثُمَّ حَمَلَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَصْبَحَتْ عِنْدَهُ، قَالَ: وَكَانَ بَيْنَنَا وَبَيْنَ قَوْمٍ عَقْدٌ، فَمَضَى الْأَجَلُ، فَعَرَّفْنَا اثْنَا عَشَرَ رَجُلًا، مَعَ كُلٍّ مِنْهُمْ أُنَاسٌ، اللَّهُ أَعْلَمُ كَمْ مَعَ كُلِّ رَجُلٍ، قَالَ: إِلَّا أَنَّهُ بَعَثَ مَعَهُمْ فَأَكَلُوا مِنْهَا أَجْمَعُونَ. أَوْ كَمَا قَالَ. (م)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ): സുഫ്ഫയിലെ ആളുകൾ ദരിദ്രരായിരുന്നു. ഒരിക്കൽ റസൂൽ(സ) പറഞ്ഞു: "ആരുടെയെങ്കിലും പക്കൽ രണ്ടാൾക്കുള്ള ഭക്ഷണമുണ്ടെങ്കിൽ അവൻ മൂന്നാളുകളെ കൊണ്ടുപോകട്ടെ. ആരുടെയെങ്കിലും പക്കൽ നാലാളുടെ ഭക്ഷമുണ്ടെങ്കിൽ അവൻ അഞ്ചാമത്തെയോ ആറാമത്തെയോ ആളെ കൊണ്ടുപോകട്ടെ." അബൂബക്കർ(റ) മൂന്നാളുകളുമായി വന്നു. അല്ലാഹുവിന്റെ റസൂൽ(സ) പത്താളുകളുമായി പോയി. അബൂബക്കർ(റ) മൂന്നാളുകളുമായി വന്നു. നിവേദകൻ പറഞ്ഞു: അദ്ദേഹവും ഞാനും എന്റെ ഉപ്പയും ഉമ്മയും, എന്റെ ഭാര്യയും എന്റെയും അബൂബക്കറിന്റെയും വീട്ടിലുള്ള സേവകനും എന്ന് അദ്ദേഹം പറഞ്ഞോ എന്നെനിക്കറിയില്ല. അബൂബക്കർ(റ) നബി(സ)യുടെ അടുത്തുവെച്ച് രാത്രി ഭക്ഷണം കഴിക്കുകയും ഇശാ നിസ്കരിക്കുന്നതുവരെ അവിടെ തങ്ങുകയും ചെയ്തു. പിന്നെ അദ്ദേഹം (നബി(സ)യുടെ അടുത്തേക്ക്) മടങ്ങിവരികയും റസൂൽ(സ) ഉറങ്ങുന്നതുവരെ അവിടെ നിൽക്കുകയും ചെയ്തു. പിന്നെ രാത്രി അൽപം കഴിഞ്ഞ് അദ്ദേഹം വന്നു. അബൂബക്കർ(റ)വിനോട് ഭാര്യ ചോദിച്ചു: നിങ്ങളുടെ അതിഥികളുടെ അടുത്തേക്ക് താങ്കൾ വരാതിരുന്നതെന്താണ്? അബൂബക്കർ(റ) ചോദിച്ചു: അവർക്ക് നിങ്ങൾ അത്താഴം നൽകിയോ? ഭാര്യ പറഞ്ഞു: നിങ്ങൾ വരുന്നതുവരെ അവർ (ഭക്ഷണം) വേണ്ടെന്ന് വെച്ചു. അവർ (അബൂബക്കർ(റ)വിന്റെ കുടുംബം) അതിഥികളുടെ അടുത്തു ചെന്ന് ഭക്ഷണത്തിന്റെ കാര്യം പറഞ്ഞെങ്കിലും അവരുടെ മറുപടിക്കെതിരെ ഒന്നും പറയാൻ കഴിഞ്ഞില്ല. നിവേദകൻ പറയുന്നു: ഞാൻ പോയി ഒളിച്ചിരുന്നു. അബൂബക്കർ(റ) ഓ ഗുൻസർ² എന്ന് വിളിച്ചു. അവിടുന്നെന്നെ ആക്ഷേപിക്കുകയും ചീത്തപറയുകയും ചെയ്തു. പിന്നെ പറഞ്ഞു: നിങ്ങൾ സുഭിക്ഷമായല്ലാതെ ഭക്ഷിക്കുക. വീണ്ടും പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അത് ഞാൻ ഭക്ഷിക്കുകയില്ല. നിവേദകൻ പറയുന്നു: ഞാൻ അല്ലാഹുവിൽ സത്യംചെയ്ത് പറയുന്നു: ഞങ്ങൾ ഒരു ഉരുള എടുക്കുമ്പോൾ അതിനിടയിൽ അതിനേക്കാൾ കൂടിവരുന്നു. അങ്ങനെ ഞങ്ങൾ വയർ നിറക്കുകയും മുമ്പുള്ളതിനേക്കാൾ അത് കൂടുകയും ചെയ്തു. അബൂബക്കർ(റ) ഭക്ഷണത്തിലേക്ക് നോക്കി. അത് അതുപോലെത്തന്നെയോ അതിലധികമോ ഉണ്ട്. അബൂബക്കർ(റ) തന്റെ ഭാര്യയോട് ചോദിച്ചു: ഓ ബനൂഫിറാസിന്റെ സഹോദരീ, ഇതെന്താണ്? അവർ പറഞ്ഞു: എന്റെ കൺകുളിർമ്മ തന്നെയാണ് സത്യം, അത് ഇപ്പോൾ മുമ്പുള്ളതിനേക്കാൾ മൂന്നിരട്ടിയുണ്ട്. നിവേദകൻ പറയുന്നു: അങ്ങനെ അബൂബക്കർ(റ) അതിൽനിന്ന് ഭക്ഷിച്ചു. എന്നിട്ട് പറഞ്ഞു: ആ സത്യം പിശാചിൽ നിന്നുള്ളതായിരുന്നു. പിന്നെ അബൂബക്കർ(റ) ഒരു ഉരുളകൂടി ഭക്ഷിച്ചു. ശേഷം അത് റസൂൽ(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുപോവുകയും ആ ഭക്ഷണം നബി(സ)യുടെ പക്കൽതന്നെ വെക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: ഞങ്ങൾക്കും ഒരു സമൂഹത്തിനുമിടയിൽ ഒരു കരാറുണ്ടായിരുന്നു. അങ്ങനെ അവധി അവസാനിച്ചപ്പോൾ ഞങ്ങൾ പന്ത്രണ്ട് ആളുകളെ വിവരം അറിയിച്ചു. അവരിൽ എല്ലാവരുടെ കൂടെയും കുറേ ജനങ്ങളുണ്ട്. ഓരോരുത്തരുടെ കൂടെയും എത്രയാളുണ്ടെന്ന് അല്ലാഹുവിനറിയാം. എന്നാൽ ഓരോരുത്തരുടെ പക്കലും ആ ഭക്ഷണം കൊടുത്തയക്കുകയും അവരെല്ലാവരും അതിൽ നിന്ന് ഭക്ഷിക്കുകയും ചെയ്തു. (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ)', '2. ആക്ഷേപിക്കാനുപയോഗിക്കുന്ന വാക്ക്', null, array['م']::text[], array['മു']::text[], 'حَتَّى', null, 302, 303, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ أَبُو طَلْحَةَ لِأُمِّ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهُمَا: لَقَدْ سَمِعْتُ صَوْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – يَعْنِي – ضَعِيفًا، أَعْرِفُ فِيهِ الْجُوعَ، فَهَلْ عِنْدَكِ مِنْ شَيْءٍ؟ فَقَالَتْ: نَعَمْ. فَأَخْرَجَتْ أَقْرَاصًا مِنْ شَعِيرٍ، ثُمَّ أَخْرَجَتْ خِمَارًا لَهَا، فَلَفَّتِ الْخُبْزَ بِبَعْضِهِ ثُمَّ دَسَّتْهُ فِي يَدِي وَرَدَّتْنِي بِبَعْضِهِ، ثُمَّ أَرْسَلَتْنِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَذَهَبْتُ بِهِ إِلَيْهِ فَوَجَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي الْمَسْجِدِ وَمَعَهُ النَّاسُ، قَالَ: فَقُمْتُ عَلَيْهِمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْسَلَكَ أَبُو طَلْحَةَ". فَقُلْتُ: نَعَمْ، قَالَ: "بِطَعَامٍ". فَقُلْتُ: نَعَمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَنْ مَعَهُ: "قُومُوا". قَالَ: فَانْطَلَقُوا، فَانْطَلَقْتُ بَيْنَ أَيْدِيهِمْ حَتَّى جِئْتُ أَبَا طَلْحَةَ فَأَخْبَرْتُهُ، فَقَالَ أَبُو طَلْحَةَ: يَا أُمَّ سُلَيْمٍ، قَدْ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ مَعَهُ، وَلَيْسَ عِنْدَنَا مَا نُطْعِمُهُمْ. قَالَتْ أُمُّ سُلَيْمٍ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: فَانْطَلَقَ أَبُو طَلْحَةَ حَتَّى لَقِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو طَلْحَةَ مَعَهُ حَتَّى دَخَلَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلُمِّي يَا أُمَّ سُلَيْمٍ مَا عِنْدَكِ". فَأَتَتْهُ بِذَلِكَ الْخُبْزِ، فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفُتَّ، وَعَصَرَتْ أُمُّ سُلَيْمٍ بُعُكَّةً لَهَا فَآدَمَتْهُ، ثُمَّ قَالَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ، ثُمَّ قَالَ: "ائْذَنْ لِعَشَرَةٍ". فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: "ائْذَنْ لِعَشَرَةٍ". فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، فَأَكَلَ الْقَوْمُ كُلُّهُمْ وَشَبِعُوا، وَالْقَوْمُ سَبْعُونَ – أَوْ ثَمَانُونَ – رَجُلًا. (ق,د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): അബൂത്വൽഹ(റ) ഉമ്മുസുലൈം(റ)യോട് പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ നേരിയ ശബ്ദം കേട്ടു. അതിൽ ഞാൻ വിശപ്പ് മനസ്സിലാക്കുന്നു. നിന്റെയടുത്ത് എന്തെങ്കിലുമുണ്ടോ? ഉണ്ട്, അവർ പറഞ്ഞു. അവർ ബാർളിയുടെ ഖുർസുകൾ പുറത്തെടുത്തു. പിന്നെ അവരുടെ മൂടുപടം കൊണ്ടുവന്നു. പിന്നെ അവർ അതിന്റെ ഒരു ഭാഗത്ത് പത്തിരി പൊതിഞ്ഞ് എന്റെ കയ്യിൽ വെച്ചു. ശേഷിച്ച ഭാഗം എനിക്ക് ഒരു പുതപ്പ് പോലെ ആക്കിത്തന്നു. എന്നിട്ട് എന്നെ അവർ റസൂൽ(സ)യുടെ അടുത്തേക്കയച്ചു. പത്തിരിയുമായി ഞാൻ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ റസൂൽ(സ) പള്ളിയിൽ ഇരിക്കുന്നതായി ഞാൻ കണ്ടു. അവിടുത്തോടൊപ്പം ജനങ്ങളുമുണ്ട്. ഞാനവരുടെ അടുത്തുനിന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിന്നെ അബൂത്വൽഹ(റ) അയച്ചതാണോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് ചോദിച്ചു: "ഭക്ഷണവുമായാണോ?" അതെ, ഞാൻ പ്രതിവചിച്ചു. റസൂൽ(സ) അവിടുത്തെ ചുറ്റുമുള്ളവരോടായി പറഞ്ഞു: "നിങ്ങൾ എഴുന്നേൽക്കുക." അങ്ങനെ അവർ പോയി. ഞാൻ അവരുടെ മുന്നിൽ പോയി അബൂത്വൽഹ(റ)വിനോട് വിവരം പറഞ്ഞു. അപ്പോൾ അബൂത്വൽഹ(റ) പറഞ്ഞു: ഓ ഉമ്മുസുലൈം, റസൂൽ(സ) അവിടുത്തോടൊപ്പമുള്ള ജനങ്ങളുടെ കൂടെയാണ് വരുന്നത്. അവരെ ഭക്ഷിപ്പിക്കാനുള്ള ഭക്ഷണം നമ്മുടെ കയ്യിലില്ല. ഉമ്മുസുലൈം(റ) പറഞ്ഞു: അല്ലാഹു വ റസൂലുഹു അഅ്ലം (അല്ലാഹുവും റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ). അപ്പോൾ അബൂത്വൽഹ(റ) പോയി റസൂൽ(സ)യെ കണ്ടു. റസൂൽ(സ) മുന്നിട്ടുവന്നു. അവിടുത്തോടൊപ്പം അബൂത്വൽഹ(റ)വും ഉണ്ട്. അങ്ങനെ അവർ രണ്ടുപേരും ഉള്ളിൽ പ്രവേശിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "ഉമ്മുസുലൈം, നിന്റെയടുത്തുള്ളത് കൊണ്ടുവരിക." അവർ ആ പത്തിരിയുമായി വന്നു. റസൂൽ(സ) അത് മാവാക്കാൻ പറഞ്ഞു. അപ്രകാരം അത് വീണ്ടും മാവാക്കപ്പെട്ടു. ഉമ്മുസുലൈം(റ) അത് അവരുടെ പാത്രത്തിൽ അളന്നു. അങ്ങനെ പത്തിരി പാചകം ചെയ്തു. പിന്നെ അല്ലാഹു ഉദ്ദേശിച്ച എന്തോ അവിടുന്ന് അതിൽ മന്ത്രിച്ചു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "പത്താളുകൾക്ക് അനുമതി കൊടുക്കുക." അങ്ങനെ അവർക്ക് അനുമതി കൊടുത്തു. അവർ വയറ് നിറയെ ഭക്ഷിച്ച് പോയി. വീണ്ടും പറഞ്ഞു: "പത്തുപേർക്ക് അനുമതി നൽകുക." അങ്ങനെ അവർക്ക് അനുമതി കൊടുത്തു. അവരും വയർ നിറയെ ഭക്ഷിച്ച് മടങ്ങി. അങ്ങനെ എല്ലാവരും വയർ നിറയെ ഭക്ഷിച്ചു. അവർ എഴുപതോ എൺപതോ ആളുകളുണ്ട്. (ബു,മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 303, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَتَدَاوَلُ فِي قَصْعَةٍ، مِنْ غُدْوَةٍ حَتَّى اللَّيْلِ، يَقُومُ عَشَرَةٌ وَيَقْعُدُ عَشَرَةٌ. قُلْنَا: فَمَا كَانَتْ تُمَدُّ؟ قَالَ: مِنْ أَيِّ شَيْءٍ تَعْجَبُ؟ مَا كَانَتْ تُمَدُّ إِلَّا مِنْ هَاهُنَا. وَأَشَارَ بِيَدِهِ إِلَى السَّمَاءِ. (ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): ഞങ്ങൾ നബി(സ)യോടുകൂടെ തളികയിൽ നിന്ന് രാവിലെ മുതൽ രാത്രിവരെ ഭക്ഷിക്കുകയായിരുന്നു. പത്ത് പേർ കഴിക്കും, പത്ത് പേർ ഇരിക്കും. ഞങ്ങൾ ചോദിച്ചു: എന്താണ് വർദ്ധിപ്പിക്കപ്പെടുന്നത്? നിവേദകൻ ചോദിച്ചു: "എന്തുകൊണ്ടാണ് നിങ്ങൾ അത്ഭുതപ്പെടുന്നത്? അവിടെ നിന്ന് മാത്രമാണ് അത് വർദ്ധിപ്പിക്കുന്നത്. അദ്ദേഹം കൈകൊണ്ട് ആകാശത്തേക്ക് ആംഗ്യം കാണിച്ചു. (തു)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 304, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ الْمِقْدَادِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَقْبَلْتُ أَنَا وَصَاحِبَانِ لِي، وَقَدْ ذَهَبَتْ أَسْمَاعُنَا وَأَبْصَارُنَا مِنَ الْجَهْدِ، قَالَ: فَجَعَلْنَا نَعْرِضُ أَنْفُسَنَا عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَيْسَ أَحَدٌ مِنْهُمْ يَقْبَلُنَا، فَأَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْطَلَقَ بِنَا إِلَى أَهْلِهِ، فَإِذَا ثَلَاثَةُ أَعْنُزٍ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "احْتَلِبُوا هَذَا اللَّبَنَ بَيْنَنَا". قَالَ: فَكُنَّا نَحْتَلِبُ، فَيَشْرَبُ كُلُّ إِنْسَانٍ مِنَّا نَصِيبَهُ، وَنَرْفَعُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَصِيبَهُ، قَالَ: فَيَجِيءُ مِنَ اللَّيْلِ فَيُسَلِّمُ تَسْلِيمًا لَا يُوقِظُ نَائِمًا وَيُسْمِعُ الْيَقْظَانَ، قَالَ: ثُمَّ يَأْتِي الْمَسْجِدَ فَيُصَلِّي، ثُمَّ يَأْتِي شَرَابَهُ فَيَشْرَبُ، فَأَتَانِي الشَّيْطَانُ ذَاتَ لَيْلَةٍ وَقَدْ شَرِبْتُ نَصِيبِي، فَقَالَ: مُحَمَّدٌ يَأْتِي الْأَنْصَارَ فَيُتْحِفُونَهُ وَيُصِيبُ عِنْدَهُمْ، مَا بِهِ حَاجَةٌ إِلَى هَذِهِ الْجُرْعَةِ، فَأَتَيْتُهَا فَشَرِبْتُهَا، فَلَمَّا أَنْ وَغَلَتْ فِي بَطْنِي، وَعَلِمْتُ أَنَّهُ لَيْسَ إِلَيْهَا سَبِيلٌ، قَالَ: نَدَّمَنِي الشَّيْطَانُ فَقَالَ: وَيْحَكَ مَا صَنَعْتَ؟ أَشَرِبْتَ شَرَابَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَجِيءُ فَلَا يَجِدُهُ، فَيَدْعُو عَلَيْكَ فَتَهْلِكُ، فَتَذْهَبُ دُنْيَاكَ وَآخِرَتُكَ؟ وَعَلَيَّ شَمْلَةٌ إِذَا وَضَعْتُهَا عَلَى قَدَمَيَّ خَرَجَ رَأْسِي، وَإِذَا وَضَعْتُهَا عَلَى رَأْسِي خَرَجَ قَدَمَايَ، وَجَعَلَ لَا يَجِيئُنِي النَّوْمُ، وَأَمَّا صَاحِبَايَ فَنَامَا وَلَمْ يَصْنَعَا مَا صَنَعْتُ، قَالَ: فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ كَمَا كَانَ يُسَلِّمُ، ثُمَّ أَتَى الْمَسْجِدَ فَصَلَّى، ثُمَّ أَتَى شَرَابَهُ فَكَشَفَ عَنْهُ فَلَمْ يَجِدْ فِيهِ شَيْئًا، فَرَفَعَ رَأْسَهُ إِلَى السَّمَاءِ، فَقُلْتُ: الْآنَ يَدْعُو عَلَيَّ فَأَهْلِكُ، فَقَالَ: "اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَأَسْقِ مَنْ أَسْقَانِي". قَالَ: فَعَمَدْتُ إِلَى الشَّمْلَةِ فَشَدَدْتُهَا عَلَيَّ، وَأَخَذْتُ الشَّفْرَةَ فَانْطَلَقْتُ إِلَى الْأَعْنُزِ أَيُّهَا أَسْمَنُ فَأَذْبَحُهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا هِيَ حَافِلٌ، وَإِذَا هُنَّ حُفَّلٌ كُلُّهُنَّ، فَعَمَدْتُ إِلَى إِنَاءٍ لِآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا كَانُوا يَطْمَعُونَ أَنْ يَحْتَلِبُوا فِيهِ، قَالَ: فَحَلَبْتُ فِيهِ حَتَّى عَلَتْهُ رَغْوَةٌ، فَجِئْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَشَرِبْتُمْ شَرَابَكُمُ اللَّيْلَةَ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ اشْرَبْ، فَشَرِبَ ثُمَّ نَاوَلَنِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، اشْرَبْ، فَشَرِبَ ثُمَّ نَاوَلَنِي، فَلَمَّا عَرَفْتُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ رَوِيَ وَأَصَبْتُ دَعْوَتَهُ، ضَحِكْتُ حَتَّى أُلْقِيتُ إِلَى الْأَرْضِ، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِحْدَى سَوْآتِكَ يَا مِقْدَادُ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، كَانَ مِنْ أَمْرِي كَذَا وَكَذَا، وَفَعَلْتُ كَذَا كَذَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا هَذِهِ إِلَّا رَحْمَةٌ مِنَ اللَّهِ عَزَّ وَجَلَّ، أَفَلَا كُنْتَ آذَنْتَنِي فَنُوقِظَ صَاحِبَيْنَا فَيُصِيبَانِ مِنْهَا". قَالَ: فَقُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا أُبَالِي إِذَا أَصَبْتَهَا وَأَصَبْتُهَا مَعَكَ مَنْ أَصَابَهَا مِنَ النَّاسِ. (م)', 'മിഖ്ദാദ്(റ): ഞാനും എന്റെ രണ്ട് സുഹൃത്തുക്കളും പുറപ്പെട്ടു. വിശപ്പ് കാരണം ഞങ്ങൾക്ക് ചെവി കേൾക്കാനോ കണ്ണുകാണാനോ പറ്റുന്നില്ല. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യുടെ അനുചരരുടെ അടുത്ത് ചെല്ലാൻ തുടങ്ങി. അവരാരും ഞങ്ങളെ സ്വീകരിക്കുന്നില്ല. അങ്ങനെ ഞങ്ങൾ നബി(സ)യുടെ അടുത്ത് ചെന്നു. നബി(സ) ഞങ്ങളെയും കൂട്ടി അവിടുത്തെ ഭാര്യയുടെ അടുത്ത് ചെന്നു. അപ്പോൾ അവിടെ മൂന്ന് ആടുകളുണ്ട്. നബി(സ) പറഞ്ഞു: "നമ്മുടെ മുമ്പിലുള്ള ഈ പാൽ നിങ്ങൾ കറന്നെടുക്കുക." മിഖ്ദാദ്(റ) പറയുന്നു: ഞങ്ങൾ പാൽ കറന്നെടുക്കും. ഞങ്ങളിലോരോരുത്തരും തന്റെ ഓഹരി കുടിക്കും. നബി(സ)ക്ക് അവിടുത്തെ ഓഹരി ഞങ്ങളെത്തിക്കും. നബി(സ) രാത്രി വന്ന്, ഉറങ്ങുന്നവനെ ഉണർത്താതെ, ഉണർന്നവനെ കേൾപ്പിക്കുന്ന വിധത്തിൽ സലാം പറയും. ശേഷം പള്ളിയിൽ പോയി നിസ്കരിക്കും. പിന്നെ നബി(സ) അവിടുത്തെ പാലിന്റെയരികിൽ ചെന്ന് അത് കുടിക്കും. ഒരു രാത്രി എന്റെ ഓഹരി ഞാൻ കുടിച്ചു കഴിഞ്ഞപ്പോൾ പിശാച് എന്റെയടുത്ത് വന്ന് പറഞ്ഞു: മുഹമ്മദ്(സ) അൻസ്വാറുകളുടെ അടുത്ത് ചെല്ലും. അവർ നബി(സ)ക്ക് സമ്മാനം നൽകും. അവരുടെ അടുത്ത് നിന്ന് നബി(സ) ഭക്ഷണം കഴിക്കും. ഈയൊരു മുറുക്ക് അവിടുത്തേക്ക് ആവശ്യമുണ്ടാകില്ല. ഞാനടുത്ത് ചെന്ന് അത് കുടിച്ചു. അതെന്റെ വയറ്റിലെത്തിയപ്പോൾ ഇനി അതെടുക്കാൻ ഒരു മാർഗ്ഗവുമില്ലെന്ന് ഞാൻ മനസ്സിലാക്കി. നിവേദകൻ പറയുന്നു: (ഞാൻ സ്വന്തത്തോട് പറഞ്ഞു) എന്നെ പിശാച് കുടിപ്പിച്ചു, നിനക്ക് നാശം, നീ എന്താണ് ചെയ്തത്? മുഹമ്മദ്(സ)യുടെ പാനീയമാണോ നീ കുടിച്ചത്. അവിടുന്ന് വന്നാൽ പാൽ കാണില്ല. അപ്പോൾ നബി(സ) നിനക്കെതിരെ പ്രാർത്ഥിക്കുകയും അങ്ങനെ നീ നശിക്കുകയും ചെയ്യും. നിന്റെ ഇഹലോകവും പരലോകവും നഷ്ടപ്പെടും. എന്റെയടുത്തൊരു പുതപ്പുണ്ട്. അതെന്റെ കാൽഭാഗങ്ങളിൽ പുതച്ചാൽ തല പുറത്താകും. തല ഭാഗത്ത് പുതച്ചാൽ കാൽ പുറത്താകും. എനിക്ക് ഉറക്കം വരുന്നില്ല. എന്റെ കൂട്ടുകാർ ഉറങ്ങിയിട്ടുണ്ട്. ഞാൻ ചെയ്തത് അവർ ചെയ്തിട്ടില്ല. അങ്ങനെ നബി(സ) വന്നു. തിരുമേനി(സ) സലാം ചൊല്ലാറുള്ളതുപോലെ സലാം ചൊല്ലി. പിന്നെ പള്ളിയിൽ ചെന്ന് നിസ്കരിച്ചു. ശേഷം പാനീയത്തിന്റെ അടുത്ത് ചെന്ന് പാത്രം തുറന്നു നോക്കി. നബി(സ) അതിൽ ഒന്നും കണ്ടില്ല. അവിടുന്ന് ആകാശത്തേക്ക് തലയുയർത്തി. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഇപ്പോൾ നബി(സ) എനിക്കെതിരെ പ്രാർത്ഥിക്കുകയും ഞാൻ നശിക്കുകയും ചെയ്യും. നബി(സ) ദുആ ചെയ്തു: "അല്ലാഹുവേ, എന്നെ ഭക്ഷിപ്പിച്ചവന് നീ ഭക്ഷണം നൽകണേ, എന്നെ കുടിപ്പിച്ചവനെ നീ കുടിപ്പിക്കണേ." ഞാൻ പുതപ്പെടുത്ത് എന്റെ ശരീരത്തിൽ കെട്ടി. ആടുകളുടെ കൂട്ടത്തിൽ ഏറ്റവും തടിയുള്ളതിനെ റസൂൽ(സ)ക്ക് അറുക്കാൻ വേണ്ടി ഞാൻ കത്തിയെടുത്ത് അവയുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ അത് പാൽ ചുരത്തിയിരുന്നു. അവയെല്ലാം പാൽ ചുരത്തിയിട്ടുണ്ട്. അങ്ങനെ ഞാൻ മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന്റെ ഒരു പാത്രമെടുത്തു, അതിൽ അവർ പാൽ കറക്കാറുണ്ടായിരുന്നില്ല. ഞാനതിൽ പാൽ കറന്നു. അങ്ങനെ അതിൽ നുര പൊന്തി. ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചന്നു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "ഇന്നലെ രാത്രി നിങ്ങളുടെ പാൽ നിങ്ങൾ കുടിച്ചോ?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് കുടിച്ചാലും. അവിടുന്ന് കുടിച്ചതിനുശേഷം അത് എനിക്ക് തന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് കുടിച്ചാലും. അവിടുന്ന് കുടിച്ച ശേഷം എനിക്ക് തന്നു. നബി(സ) വയർ നിറക്കുകയും ഞാനവിടുത്തെ വിളി കേൾക്കുകയും ചെയ്തെന്ന് ഞാൻ മനസ്സിലാക്കിയപ്പോൾ, ഞാൻ ചിരിച്ച് നിലത്ത് വീണു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ ഇരു നഗ്നതകളിലൊന്ന് വെളിവായിരിക്കുന്നു." അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പക്കൽ ഇപ്രകാരമെല്ലാം സംഭവിച്ചു, ഞാൻ ഇപ്രകാരമെല്ലാം ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് അല്ലാഹുവിന്റെ അനുഗ്രഹം മാത്രമാണ്. നീയെന്നോട് പറയുകയാണെങ്കിൽ നമ്മുടെ രണ്ടു കൂട്ടുകാരെയും നമുക്ക് ഉണർത്താമായിരുന്നു. അവർക്കതിൽ നിന്ന് കുടിക്കാമായിരുന്നു." അപ്പോൾ ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി നിയോഗിച്ചവൻ തന്നെ സത്യം, അങ്ങ് അത് കുടിക്കുകയും അങ്ങയോടൊപ്പം ഞാനത് കുടിക്കുകയും ചെയ്താൽ, ശേഷം ജനങ്ങളിൽ ആരാണത് കുടിക്കുന്നതെന്ന് ഞാൻ ഗൗനിക്കുന്നില്ല. (മു)', 'الْمِقْدَادِ', 'മിഖ്ദാദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 305, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُمَّ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا كَانَتْ تُهْدِي لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عُكَّةٍ لَهَا سَمْنًا، فَيَأْتِيهَا بَنُوهَا فَيَسْأَلُونَ الْأُدْمَ وَلَيْسَ عِنْدَهُمْ شَيْءٌ، فَتَعْمِدُ إِلَى الَّذِي كَانَتْ تُهْدِي فِيهِ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَجِدُ فِيهِ سَمْنًا، فَمَا زَالَ يُقِيمُ لَهَا أُدْمَ بَيْتِهَا حَتَّى عَصَرَتْهُ، فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "عَصَرْتِيهَا". قَالَتْ: نَعَمْ، قَالَ: "لَوْ تَرَكْتِيهَا مَا زَالَ قَائِمًا". (م)', 'ജാബിർ(റ): ഉമ്മുമാലിക്(റ) തിരുമേനി(സ)ക്ക് ഒരു പാത്രത്തിൽ നെയ്യ് സമ്മാനമായി നൽകാറുണ്ടായിരുന്നു. അങ്ങനെ തങ്ങളുടെ പക്കൽ ഒന്നുമില്ലാത്ത സന്ദർഭങ്ങളിൽ ഉമ്മുമാലിക്(റ)യുടെ കുട്ടികൾ വന്ന് അവരോട് കറി ചോദിക്കും. അപ്പോൾ ഉമ്മുമാലിക്(റ) താൻ നബി(സ)ക്ക് നെയ്യ് സമ്മാനിച്ച പാത്രത്തിന്റെയടുത്ത് ചെല്ലും. അവർക്കതിൽ നിന്ന് നെയ്യ് ലഭിക്കും. ആ പാത്രം അവർക്ക് വീട്ടിലെ കറി(നെയ്യ്) നൽകിക്കൊണ്ടിരുന്നു. അങ്ങനെ അവരത് അളന്നു. ശേഷം മഹതി നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങളത് അളന്നുവോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "നിങ്ങളത് അളന്നിട്ടില്ലായിരുന്നെങ്കിൽ, അത് ഇപ്പോഴുമുണ്ടാകുമായിരുന്നു." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 306, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى إِذَا انْفَلَقَ الْقَمَرُ فِلْقَتَيْنِ، فَكَانَتْ فِلْقَةٌ وَرَاءَ الْجَبَلِ وَفِلْقَةٌ دُونَهُ، فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اشْهَدُوا". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): മിനായിൽ ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെയുള്ളപ്പോൾ ചന്ദ്രൻ രണ്ട് പിളർപ്പായി മാറി. ഒരു പിളർപ്പ് മലയുടെ പിന്നിലും ഒന്ന് മലയുടെ മുന്നിലും. അപ്പോൾ റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങൾ സാക്ഷികളാവുക." (മു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 307, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
