insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عُبَادَةَ بْنِ الْوَلِيدِ بْنِ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْتُ أَنَا وَأَبِي نَطْلُبُ الْعِلْمَ فِي هَذَا الْحَيِّ مِنَ الْأَنْصَارِ قَبْلَ أَنْ يَهْلِكُوا، فَكَانَ أَوَّلَ مَنْ لَقِينَا أَبَا الْيَسَرِ صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَعَهُ غُلَامٌ لَهُ مَعَهُ ضِمَامَةٌ مِنْ صُحُفٍ، وَعَلَى أَبِي الْيَسَرِ بُرْدَةٌ وَمَعَافِرِيٌّ، وَعَلَى غُلَامِهِ بُرْدَةٌ وَمَعَافِرِيٌّ، فَقَالَ لَهُ أَبِي: يَا عَمِّ إِنِّي أَرَى فِي وَجْهِكَ سَفْعَةً مِنْ غَضَبٍ. قَالَ: أَجَلْ، كَانَ لِي عَلَى فُلَانِ بْنِ فُلَانٍ الْحَرَامِيِّ مَالٌ، فَأَتَيْتُ أَهْلَهُ فَسَلَّمْتُ عَلَيْهِ، فَقُلْتُ: ثَمَّ هُوَ؟ قَالُوا: لَا، فَخَرَجَ عَلَيَّ ابْنٌ لَهُ جَفْرٌ، فَقُلْتُ لَهُ: أَيْنَ أَبُوكَ؟ قَالَ: سَمِعَ صَوْتَكَ فَدَخَلَ أَرِيكَةَ أُمِّي. فَقُلْتُ: اخْرُجْ إِلَيَّ، فَقَدْ عَلِمْتُ أَيْنَ أَنْتَ، فَخَرَجَ فَقُلْتُ: مَا حَمَلَكَ عَلَى أَنِ اخْتَبَأْتَ مِنِّي؟ قَالَ: أَنَا وَاللَّهِ أُحَدِّثُكَ ثُمَّ لَا أَكْذِبُكَ، خَشِيتُ وَاللَّهِ أَنْ أُحَدِّثَكَ فَأَكْذِبَكَ، وَأَنْ أَعِدَكَ فَأُخْلِفَكَ، وَكُنْتَ صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكُنْتَ وَاللَّهِ مُعْسِرًا. قَالَ: قُلْتُ: آللَّهِ؟ قَالَ: اللَّهِ. قُلْتُ: آللَّهِ؟ قَالَ: اللَّهِ. [قُلْتُ: آللَّهِ؟ قَالَ: اللَّهِ] قَالَ: فَأَتَى بِصَحِيفَتِهِ فَمَحَاهَا بِيَدِهِ، قَالَ: إِنْ وَجَدْتَ قَضَاءً فَاقْضِنِي وَإِلَّا أَنْتَ فِي حِلٍّ. فَأَشْهَدُ، بَصُرَ عَيْنَيَّ هَاتَيْنِ – وَوَضَعَ إِصْبَعَيْهِ عَلَى عَيْنَيْهِ – وَسَمْعُ أُذُنَيَّ هَاتَيْنِ، وَوَعَاهُ قَلْبِي هَذَا – وَأَشَارَ إِلَى مَنَاطِ قَلْبِهِ – رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يَقُولُ: "مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ". قَالَ: فَقُلْتُ لَهُ أَنَا: يَا عَمِّ لَوْ أَنَّكَ أَخَذْتَ بُرْدَةَ غُلَامِكَ وَأَعْطَيْتَهُ مَعَافِرِيَّكَ، وَأَخَذْتَ مَعَافِرِيَّهُ وَأَعْطَيْتَهُ بُرْدَتَكَ، فَكَانَتْ عَلَيْكَ حُلَّةٌ وَعَلَيْهِ حُلَّةٌ؟ فَمَسَحَ رَأْسِي وَقَالَ: اللَّهُمَّ بَارِكْ فِيهِ، يَا ابْنَ أَخِي، بَصُرَ عَيْنَيَّ هَاتَيْنِ وَسَمْعُ أُذُنَيَّ هَاتَيْنِ، وَوَعَاهُ قَلْبِي هَذَا – وَأَشَارَ إِلَى مَنَاطِ قَلْبِهِ – رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: "أَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ، وَأَلْبِسُوهُمْ مِمَّا تَلْبَسُونَ". وَكَانَ أَنْ أُعْطِيَهُ مِنْ مَتَاعِ الدُّنْيَا أَهْوَنَ عَلَيَّ مِنْ أَنْ يَأْخُذَ مِنْ حَسَنَاتِي يَوْمَ الْقِيَامَةِ. ثُمَّ مَضَيْنَا حَتَّى أَتَيْنَا جَابِرَ بْنَ عَبْدِ اللَّهِ فِي مَسْجِدِهِ وَهُوَ يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُشْتَمِلًا بِهِ، فَتَخَطَّيْتُ الْقَوْمَ حَتَّى جَلَسْتُ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ، فَقُلْتُ: يَرْحَمُكَ اللَّهُ، أَتُصَلِّي فِي ثَوْبٍ وَاحِدٍ وَرِدَاؤُكَ إِلَى جَنْبِكَ؟ قَالَ: فَقَالَ بِيَدِهِ فِي صَدْرِي هَكَذَا – وَفَرَّقَ بَيْنَ أَصَابِعِهِ وَقَوَّسَهَا – أَرَدْتُ أَنْ يَدْخُلَ عَلَيَّ الْأَحْمَقُ مِثْلُكَ، فَيَرَانِي كَيْفَ أَصْنَعُ فَيَصْنَعُ مِثْلَهُ. أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِنَا هَذَا وَفِي يَدِهِ عُرْجُونُ ابْنِ طَابٍ، فَرَأَى فِي قِبْلَةِ الْمَسْجِدِ نُخَامَةً فَحَكَّهَا بِالْعُرْجُونِ، ثُمَّ أَقْبَلَ عَلَيْنَا فَقَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللَّهُ عَنْهُ". قَالَ: فَخَشَعْنَا، ثُمَّ قَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللَّهُ عَنْهُ". قَالَ: فَخَشَعْنَا، ثُمَّ قَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللَّهُ عَنْهُ". قُلْنَا: لَا أَيُّنَا يَا رَسُولَ اللَّهِ، قَالَ: "فَإِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قِبَلَ وَجْهِهِ، فَلَا يَبْصُقَنَّ قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ، وَلْيَبْصُقْ عَنْ يَسَارِهِ تَحْتَ رِجْلِهِ الْيُسْرَى، فَإِنْ عَجِلَتْ بِهِ بَادِرَةٌ فَلْيَقُلْ بِثَوْبِهِ هَكَذَا". ثُمَّ طَوَى ثَوْبَهُ بَعْضَهُ عَلَى بَعْضٍ، فَقَالَ: "أَرُونِي عَبِيرًا". فَقَامَ فَتًى مِنَ الْحَيِّ يَشْتَدُّ إِلَى أَهْلِهِ، فَجَاءَ بِخَلُوقٍ فِي رَاحَتِهِ، فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَهُ عَلَى رَأْسِ الْعُرْجُونِ، ثُمَّ لَطَخَ بِهِ عَلَى أَثَرِ النُّخَامَةِ، فَقَالَ جَابِرٌ: فَمِنْ هُنَاكَ جَعَلْتُمُ الْخَلُوقَ فِي مَسَاجِدِكُمْ. سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَطْنِ بُوَاطٍ، وَهُوَ يَطْلُبُ الْمَجْدِيَّ بْنَ عَمْرٍو الْجُهَنِيَّ، وَكَانَ النَّاضِحُ يَعْقُبُهُ مِنَّا الْخَمْسَةُ وَالسِّتَّةُ وَالسَّبْعَةُ، فَدَارَتْ عُقْبَةُ رَجُلٍ مِنَ الْأَنْصَارِ عَلَى نَاضِحٍ لَهُ، فَأَنَاخَهُ فَرَكِبَهُ ثُمَّ بَعَثَهُ، فَتَلَدَّنَ عَلَيْهِ بَعْضَ التَّلَدُّنِ، فَقَالَ لَهُ: شَأْ لَعَنَكَ اللَّهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ هَذَا اللَّاعِنُ بَعِيرَهُ". قَالَ: أَنَا يَا رَسُولَ اللَّهِ، قَالَ: "انْزِلْ عَنْهُ، فَلَا تَصْحَبْنَا بِمَلْعُونٍ. لَا تَدْعُوا عَلَى أَنْفُسِكُمْ، وَلَا تَدْعُوا عَلَى أَوْلَادِكُمْ، وَلَا تَدْعُوا عَلَى أَمْوَالِكُمْ، لَا تُوَافِقُوا مِنَ اللَّهِ سَاعَةً يُسْأَلُ فِيهَا عَطَاءٌ فَيَسْتَجِيبُ لَكُمْ". سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا كَانَتْ عُشَيْشِيَةٌ، وَدَنَوْنَا مَاءً مِنْ مِيَاهِ الْعَرَبِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ رَجُلٌ يَتَقَدَّمُنَا فَيَمْدُرُ الْحَوْضَ، فَيَشْرَبُ وَيَسْقِينَا". قَالَ جَابِرٌ: فَقُمْتُ فَقُلْتُ: هَذَا رَجُلٌ يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّ رَجُلٍ مَعَ جَابِرٍ". فَقَامَ جَبَّارُ بْنُ صَخْرٍ، فَانْطَلَقْنَا إِلَى الْبِئْرِ فَنَزَعْنَا فِي الْحَوْضِ سَجْلًا أَوْ سَجْلَيْنِ، ثُمَّ مَدَرْنَاهُ، ثُمَّ نَزَعْنَا فِيهِ حَتَّى أَفْهَقْنَاهُ، فَكَانَ أَوَّلَ طَالِعٍ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَتَأْذَنَانِ". قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ، فَأَشْرَعَ نَاقَتَهُ فَشَرِبَتْ، شَنَقَ لَهَا فَشَجَتْ، فَبَالَتْ، ثُمَّ عَدَلَ بِهَا فَأَنَاخَهَا، ثُمَّ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْحَوْضِ فَتَوَضَّأَ مِنْهُ، ثُمَّ قُمْتُ فَتَوَضَّأْتُ مِنْ مُتَوَضَّإِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَهَبَ جَبَّارُ بْنُ صَخْرٍ يَقْضِي حَاجَتَهُ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ، وَكَانَتْ عَلَيَّ بُرْدَةٌ ذَهَبْتُ أَنْ أُخَالِفَ بَيْنَ طَرَفَيْهَا فَلَمْ تَبْلُغْ لِي، وَكَانَتْ لَهَا ذَبَاذِبُ فَنَكَّسْتُهَا، ثُمَّ خَالَفْتُ بَيْنَ طَرَفَيْهَا، ثُمَّ تَوَاقَصْتُ عَلَيْهَا، ثُمَّ جِئْتُ حَتَّى قُمْتُ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ بِيَدِي فَأَدَارَنِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ، ثُمَّ جَاءَ جَبَّارُ بْنُ صَخْرٍ، فَتَوَضَّأَ ثُمَّ جَاءَ فَقَامَ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ [رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ] بِيَدَيْنَا جَمِيعًا، فَدَفَعَنَا حَتَّى أَقَامَنَا خَلْفَهُ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْمُقُنِي وَأَنَا لَا أَشْعُرُ، ثُمَّ فَطِنْتُ بِهِ، فَقَالَ هَكَذَا بِيَدِهِ، يَعْنِي شُدَّ وَسَطَكَ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا جَابِرُ". قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ، قَالَ: "إِذَا كَانَ وَاسِعًا فَخَالِفْ بَيْنَ طَرَفَيْهِ، وَإِذَا كَانَ ضَيِّقًا فَاشْدُدْهُ عَلَى حَقْوِكَ".
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَنَس بْنِ مَالِك رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خطَب إِلَى لِزْق جِذْعٍ، وَاتَّخَذُوا لَهُ مِنْبَرًا فَخَطَبَ عَلَيْهِ، فَحَنَّ الْجِذْعُ حَنِينَ النَّاقَةِ، فَنَزَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَمَسَّهُ فَسَكَنَ. (ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഒരു മരത്തടിയിൽ നിന്ന് പ്രസംഗിച്ചിരുന്നു. സ്വഹാബികൾ റസൂൽ(സ)ക്ക് വേണ്ടി മറ്റൊരു മിമ്പർ പണിതു. റസൂൽ(സ) അതിന്മേൽ പ്രസംഗിച്ചു. അപ്പോൾ ആ മരത്തടി ഒട്ടകം കരയുന്നത് പോലെ കരഞ്ഞു. നബി(സ) ഇറങ്ങിവന്ന് അതിനെ സ്പർശിച്ചപ്പോൾ അത് ശാന്തമായി. (തു,ജ)', 'أَنَس بْنِ مَالِك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: بِمَ أَعْرِفُ أَنَّكَ نَبِيٌّ؟ قَالَ: "إِنْ دَعَوْتُ هَذَا الْعِذْقَ مِنْ هَذِهِ النَّخْلَةِ، أَتَشْهَدُ أَنِّي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟" فَدَعَاهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يَنْزِلُ مِنَ النَّخْلَةِ حَتَّى سَقَطَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "ارْجِعْ". فَعَادَ، فَأَسْلَمَ الْأَعْرَابِيُّ. حَسَنٌ صَحِيحٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു അഅ്റാബി റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: താങ്കൾ നബിയാണെന്ന് എനിക്കെങ്ങനെയാണ് മനസ്സിലാക്കാനാവുക? നബി(സ) പറഞ്ഞു: "ഈ ഈത്തപ്പനയിലെ പൂക്കുലയെ ഞാൻ വിളിച്ചുവരുത്തിയാൽ ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് നീ സാക്ഷ്യംവഹിക്കുമോ?" അങ്ങനെ ആ പൂക്കുലയെ റസൂൽ(സ) വിളിക്കുകയും അത് മരത്തിൽ നിന്ന് ഇറങ്ങിവന്ന് നബി(സ)യുടെ അടുത്ത് വീഴുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) (കുലയോട്) പറഞ്ഞു: "നീ തിരിച്ചുപോകുക." അപ്പോൾ അത് മടങ്ങിച്ചെന്നു. അങ്ങനെ ആ അഅ്റാബി മുസ്ലിമായി. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْرِفُ حَجَرًا بِمَكَّةَ كَانَ يُسَلِّمُ عَلَيَّ قَبْلَ أَنْ أُبْعَثَ، إِنِّي لَأَعْرِفُهُ الْآنَ". (م,ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകനായി നിയോഗിക്കപ്പെടുന്നതിന് മുമ്പ് എന്നോട് സലാം പറഞ്ഞിരുന്ന മക്കയിലെ ഒരു കല്ലിനെ എനിക്കറിയാം. നിശ്ചയം ഇപ്പോഴും അതിനെ എനിക്കറിയാം." (മു,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ، فَخَرَجْنَا فِي بَعْضِ نَوَاحِيهَا، فَمَا اسْتَقْبَلَهُ جَبَلٌ وَلَا شَجَرٌ إِلَّا وَهُوَ يَقُولُ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللهِ. حَسَنٌ. (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ)യുടെ കൂടെ ഞാൻ മക്കയിലായിരിക്കെ, അവിടത്തെ ഒരു ഭാഗത്തേക്ക് ഞങ്ങൾ പുറപ്പെട്ടു. അങ്ങനെ നബി(സ)യെ എതിരേറ്റ എല്ലാ പർവതങ്ങളും മരങ്ങളും അവിടുത്തോട് ''അസ്സലാമുഅലൈക്ക യാ റസൂലല്ലാഹ്'' എന്ന് പറയുന്നുണ്ടായിരുന്നു. ഹദീസ് ഹസനാണ്. (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 314, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو جَهْلٍ: هَلْ يُعَفِّرُ مُحَمَّدٌ وَجْهَهُ بَيْنَ أَظْهُرِكُمْ؟ قَالَ: فَقِيلَ: نَعَمْ، فَقَالَ: وَاللَّاتِ وَالْعُزَّى، لَئِنْ رَأَيْتُهُ يَفْعَلُ ذَلِكَ لَأَطَأَنَّ عَلَى رَقَبَتِهِ، أَوْ لَأُعَفِّرَنَّ وَجْهَهُ فِي التُّرَابِ. قَالَ: فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي، زَعَمَ لِيَطَأَ عَلَى رَقَبَتِهِ، قَالَ: فَمَا فَجِئَهُمْ مِنْهُ إِلَّا وَهُوَ يَنْكِصُ عَلَى عَقِبَيْهِ وَيَتَّقِي بِيَدَيْهِ، قَالَ: فَقِيلَ لَهُ: مَا لَكَ؟ فَقَالَ: إِنَّ بَيْنِي وَبَيْنَهُ لَخَنْدَقًا مِنْ نَارٍ وَهَوْلًا وَأَجْنِحَةً. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ دَنَا مِنِّي لَاخْتَطَفَتْهُ الْمَلَائِكَةُ عُضْوًا عُضْوًا". قَالَ: فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ – لَا نَدْرِي فِي حَدِيثِ أَبِي هُرَيْرَةَ أَوْ شَيْءٌ بَلَغَهُ – {كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَى. أَنْ رَآهُ اسْتَغْنَى. إِنَّ إِلَى رَبِّكَ الرُّجْعَى. أَرَأَيْتَ الَّذِي يَنْهَى. عَبْدًا إِذَا صَلَّى. أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى. أَوْ أَمَرَ بِالتَّقْوَى. أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى} – يَعْنِي أَبَا جَهْلٍ – {أَلَمْ يَعْلَمْ بِأَنَّ اللهَ يَرَى. كَلَّا لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ. نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ. فَلْيَدْعُ نَادِيَهُ. سَنَدْعُ الزَّبَانِيَةَ. كَلَّا لَا تُطِعْهُ}. وَفِي رِوَايَةٍ قَالَ: "وَأَمَرَهُ بِمَا أَمَرَهُ بِهِ" وَفِي رِوَايَةٍ: {فَلْيَدْعُ نَادِيَهُ} يَعْنِي قَوْمَهُ. (م)', 'അബൂഹുറൈറ(റ): അബൂജഹ്ൽ ചോദിച്ചു: മുഹമ്മദ് നിങ്ങളുടെ മുന്നിൽ വെച്ച് (പരസ്യമായി) തന്റെ മുഖം മണ്ണിൽ വെക്കുമോ (നിസ്കരിക്കുമോ)? അപ്പോൾ അബൂജഹ്ലിനോട് ആരോ പറഞ്ഞു: അതെ. ഉടനെ അവൻ പറഞ്ഞു: ലാത്തയും ഉസ്സയും തന്നെ സത്യം, മുഹമ്മദ് അപ്രകാരം ചെയ്യുന്നത് ഞാൻ കാണുകയാണെങ്കിൽ അവന്റെ കഴുത്തിൽ ചവിട്ടും. അല്ലെങ്കിൽ മുഹമ്മദിന്റെ മുഖം ഞാൻ മണ്ണിലമർത്തും. അങ്ങനെ റസൂൽ(സ) നിസ്കരിക്കുമ്പോൾ അബൂജഹ്ൽ വന്നു. അവൻ റസൂൽ(സ)യുടെ കഴുത്തിൽ ചവിട്ടണമെന്ന് തീരുമാനിച്ചിരുന്നു. നിവേദകൻ പറയുന്നു: എന്നാൽ അബൂജഹ്ലിനെ അവർ കണ്ടതേയുള്ളൂ. അപ്പോഴുണ്ട് അവൻ തന്റെ കൈകൾകൊണ്ട് (എന്തോ) തടുത്തുകൊണ്ട് പിറകോട്ടടിച്ച് പോകുന്നു. അപ്പോൾ അവനോടാരോ ചോദിച്ചു: നിനക്കെന്തുപറ്റി? അബൂജഹ്ൽ പറഞ്ഞു: എന്റെയും മുഹമ്മദിന്റെയുമിടയിൽ അഗ്നിയുടെ കിടങ്ങും ഭീതിപ്പെടുത്തുന്ന എന്തോ ചിലതും ചിറകുകളുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൻ എന്റെ അടുത്തെത്തിയിരുന്നെങ്കിൽ മലക്കുകൾ അവന്റെ ഓരോ അവയവങ്ങളും വെവ്വേറെയാക്കി റാഞ്ചിയെടുക്കുമായിരുന്നു." അപ്പോൾ അല്ലാഹു ഈ സൂക്തം അവതരിപ്പിച്ചു - ഈ ഹദീസ് അബൂഹുറൈറ(റ) നേരിട്ടുദ്ധരിക്കുന്നതാണോ അതോ അദ്ദേഹം മറ്റുള്ളവരിൽ നിന്ന് ഉദ്ധരിക്കുന്നതോ എന്ന് നമുക്കറിയില്ല -: ''നിസ്സംശയം, താൻ സ്വയംപര്യാപ്തനാണെന്ന് മനസ്സിലാക്കിയതിനാൽ മനുഷ്യൻ ധിക്കാരിയായിത്തീരുന്നു. നിശ്ചയം നിന്റെ രക്ഷിതാവിന്റെ അടുക്കലേക്കാണ് മടക്കം. ഒരടിയൻ (പ്രവാചകൻ) നമസ്കരിച്ചാൽ അത് വിലക്കുന്നവനെ (അബൂജഹൽ) താങ്കൾ കണ്ടുവോ. അദ്ദേഹം സന്മാർഗത്തിലാണെങ്കിൽ, അവൻ സൂക്ഷ്മത കൈക്കൊള്ളാൻ കൽപിച്ചവനാണെങ്കിൽ (അവന്റെ അവസ്ഥ എന്തായിരിക്കുമെന്ന്) നീ കണ്ടുവോ? അവൻ, നിഷേധിച്ചുതള്ളുകയും തിരിഞ്ഞുകളയുകയും ചെയ്തിരിക്കയാണെങ്കിൽ (അവന്റെ അവസ്ഥ എന്തായിരിക്കുമെന്ന്) നീ കണ്ടുവോ?'' - അതായത് അബൂജഹ്ൽ - ''അവൻ മനസ്സിലാക്കിയിട്ടില്ലേ, അല്ലാഹു കാണുന്നുണ്ടെന്ന്? നിസ്സംശയം അവൻ വിരമിച്ചിട്ടില്ലെങ്കിൽ നാം ആ കുടുമ പിടിച്ചുവലിക്കുക തന്നെ ചെയ്യും. കള്ളം പറയുന്ന പാപംചെയ്യുന്ന കുടുമ. അവൻ തന്റെ സഭയിലുള്ളവരെ വിളിച്ചുകൊള്ളട്ടെ. നാം സബാനിയ്യത്തിനെ (നരക പാലകരായ മലക്കുകളെ) വിളിച്ചുകൊള്ളാം. നിസ്സംശയം, താങ്കളവനെ അനുസരിച്ചുപോകരുത്.'' മറ്റൊരു നിവേദനം: "അല്ലാഹു റസൂൽ(സ)യോട് കൽപിച്ചത് കൽപിച്ചു." മറ്റൊരു നിവേദനം: ''അവൻ തന്റെ സഭയെ വിളിക്കട്ടെ'' അതായത് തന്റെ സമൂഹത്തെ. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ قَالَ: "وَأَمَرَهُ بِمَا أَمَرَهُ بِهِ"', 'മറ്റൊരു നിവേദനം: "അല്ലാഹു റസൂൽ(സ)യോട് കൽപിച്ചത് കൽപിച്ചു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=52), 2, 'وَفِي رِوَايَةٍ: {فَلْيَدْعُ نَادِيَهُ} يَعْنِي قَوْمَهُ. (م)', 'മറ്റൊരു നിവേദനം: ''അവൻ തന്റെ സഭയെ വിളിക്കട്ടെ'' അതായത് തന്റെ സമൂഹത്തെ. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَزَوْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَزْوَةً قِبَلَ نَجْدٍ، فَأَدْرَكَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي وَادٍ كَثِيرِ الْعِضَاهِ، فَنَزَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَحْتَ شَجَرَةٍ، فَعَلَّقَ سَيْفَهُ بِغُصْنٍ مِنْ أَغْصَانِهَا، قَالَ: وَتَفَرَّقَ النَّاسُ فِي الْوَادِي يَسْتَظِلُّونَ بِالشَّجَرِ [قَالَ]: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ رَجُلًا أَتَانِي وَأَنَا نَائِمٌ فَأَخَذَ السَّيْفَ، فَاسْتَيْقَظْتُ وَهُوَ قَائِمٌ عَلَى رَأْسِي، فَلَمْ أَشْعُرْ إِلَّا وَالسَّيْفُ صَلْتًا فِي يَدِهِ، فَقَالَ لِي: مَنْ يَمْنَعُكَ مِنِّي؟ قَالَ: قُلْتُ: اللهُ، ثُمَّ قَالَ فِي الثَّانِيَةِ: مَنْ يَمْنَعُكَ مِنِّي؟ قَالَ: قُلْتُ: اللهُ، قَالَ: فَشَامَ السَّيْفَ، فَهَا هُوَ جَالِسٌ". ثُمَّ لَمْ يَعْرِضْ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ നജ്ദിനെതിരെ യുദ്ധം ചെയ്തു. അങ്ങനെ മുൾച്ചെടികൾ ധാരാളമുള്ള ഒരു മലഞ്ചെരുവിൽ വെച്ച് റസൂൽ(സ) ഞങ്ങളോടൊപ്പമെത്തി. അവിടുന്ന് ഒരു മരച്ചുവട്ടിലിറങ്ങുകയും മരത്തിന്റെയൊരു കൊമ്പിൽ വാൾ തൂക്കിയിടുകയും ചെയ്തു. മരത്തണൽ തേടി ജനങ്ങൾ മലഞ്ചെരുവിൽ പലയിടങ്ങളിൽ ചെന്നു. നിവേദകൻ പറയുന്നു: റസൂൽ(സ) പറയുന്നു: "ഞാൻ ഉറങ്ങുമ്പോൾ ഒരാൾ എന്റെ അടുത്തുവന്ന് വാളെടുത്തു. ഞാൻ ഉണർന്നപ്പോൾ അയാൾ എന്റെ തലക്കരികിൽ നിൽക്കുന്നുണ്ട്. അവന്റെ കയ്യിൽ വാളൂരിയെടുത്തപ്പോൾ മാത്രമാണ് ഞാനറിയുന്നത്. അയാളെന്നോട് പറഞ്ഞു: എന്നിൽനിന്ന് നിന്നെ ആരാണ് രക്ഷപ്പെടുത്തുക? അല്ലാഹു, ഞാൻ പറഞ്ഞു. രണ്ടാം പ്രാവശ്യം അവനെന്നോട് ചോദിച്ചു: എന്നിൽ നിന്ന് ആരാണ് നിന്നെ രക്ഷിക്കുക? ഞാൻ പറഞ്ഞു: അല്ലാഹു. അപ്പോൾ അവൻ വാൾ ഉറയിലിട്ടു. അയാളിപ്പോൾ ഇതാ ഇരിക്കുന്നു." പിന്നെ റസൂൽ(സ) അയാളെ പ്രതികാരം ചെയ്തില്ല. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 316, 316, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً يَهُودِيَّةً أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ مَسْمُومَةٍ، فَأَكَلَ مِنْهَا، فَجِيءَ بِهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهَا عَنْ ذَلِكَ؟ فَقَالَتْ: أَرَدْتُ لِأَقْتُلَكَ. فَقَالَ: "مَا كَانَ اللهُ لِيُسَلِّطَكِ عَلَى ذَلِكِ". قَالَ: أَوْ قَالَ: "عَلَيَّ". قَالَ: فَقَالُوا: أَلَا نَقْتُلُهَا؟ قَالَ: "لَا". قَالَ: فَمَا زِلْتُ أَعْرِفُهَا فِي لَهَوَاتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അനസ്(റ): ഒരു ജൂതസ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് വിഷം പുരട്ടിയ ആട്ടിറച്ചി കൊണ്ടുവന്നു. റസൂൽ(സ) അതിൽനിന്നും ഭക്ഷിച്ചു. അവളെ റസൂൽ(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. അതിനെക്കുറിച്ച് അവളോട് റസൂൽ(സ) ചോദിച്ചപ്പോൾ അവൾ പറഞ്ഞു: ഞാൻ നിങ്ങളെ വധിക്കാൻ ഉദ്ദേശിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്കതിന് ശക്തി തരില്ല." നിവേദകൻ പറയുന്നു: അല്ലെങ്കിൽ റസൂൽ(സ) പറഞ്ഞത് "എനിക്കെതിരിൽ" എന്നാണ്. നിവേദകൻ പറയുന്നു: അപ്പോൾ ജനങ്ങൾ ചോദിച്ചു: ഞങ്ങൾ അവളെ വധിക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട." നിവേദകൻ പറയുന്നു: വിഷത്തിന്റെ പ്രതിഫലനം ഞാൻ റസൂൽ(സ)യുടെ അധരങ്ങളിൽ കാണാറുണ്ടായിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 316, 316, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ تَبُوكَ، فَأَتَيْنَا وَادِيَ الْقُرَى عَلَى حَدِيقَةٍ لِامْرَأَةٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اخْرُصُوهَا". فَخَرَصْنَاهَا، وَخَرَصَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَشَرَةَ أَوْسُقٍ، وَقَالَ: "أَحْصِيهَا حَتَّى نَرْجِعَ إِلَيْكِ إِنْ شَاءَ اللهُ". وَانْطَلَقْنَا حَتَّى قَدِمْنَا تَبُوكَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَتَهُبُّ عَلَيْكُمُ اللَّيْلَةَ رِيحٌ شَدِيدَةٌ، فَلَا يَقُمْ فِيهَا أَحَدٌ مِنْكُمْ، فَمَنْ كَانَ لَهُ بَعِيرٌ فَلْيَشُدَّ عِقَالَهُ". فَهَبَّتْ رِيحٌ شَدِيدَةٌ، فَقَامَ رَجُلٌ، فَحَمَلَتْهُ الرِّيحُ حَتَّى أَلْقَتْهُ بِجَبَلَيْ طَيِّئٍ، وَجَاءَ رَسُولُ ابْنِ الْعَلْمَاءِ صَاحِبِ أَيْلَةَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكِتَابٍ، وَأَهْدَى لَهُ بَغْلَةً بَيْضَاءَ، فَكَتَبَ إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَهْدَى لَهُ بُرْدًا، ثُمَّ أَقْبَلْنَا حَتَّى قَدِمْنَا وَادِيَ الْقُرَى، فَسَأَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَرْأَةَ عَنْ حَدِيقَتِهَا كَمْ بَلَغَ ثَمَرُهَا؟ فَقَالَتْ: عَشَرَةَ أَوْسُقٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي مُسْرِعٌ، فَمَنْ شَاءَ مِنْكُمْ فَلْيُسْرِعْ مَعِي، وَمَنْ شَاءَ فَلْيَمْكُثْ". فَخَرَجْنَا حَتَّى أَشْرَفْنَا عَلَى الْمَدِينَةِ، فَقَالَ: "هَذِهِ طَابَةُ، وَهَذَا أُحُدٌ، وَهُوَ جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ". ثُمَّ قَالَ: "إِنَّ خَيْرَ دُورِ الْأَنْصَارِ دَارُ بَنِي النَّجَّارِ، ثُمَّ دَارُ بَنِي عَبْدِ الْأَشْهَلِ، ثُمَّ دَارُ بَنِي عَبْدِ الْحَارِثِ بْنِ الْخَزْرَجِ، ثُمَّ دَارُ بَنِي سَاعِدَةَ، وَفِي كُلِّ دُورِ الْأَنْصَارِ خَيْرٌ". فَلَحِقَنَا سَعْدُ بْنُ عُبَادَةَ، فَقَالَ أَبُو أُسَيْدٍ: أَلَمْ تَرَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَيَّرَ دُورَ الْأَنْصَارِ، فَجَعَلَنَا آخِرًا؟ فَأَدْرَكَ سَعْدٌ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، خَيَّرْتَ دُورَ الْأَنْصَارِ فَجَعَلْتَنَا آخِرًا؟ فَقَالَ: "أَوَ لَيْسَ بِحَسْبِكُمْ أَنْ تَكُونُوا مِنَ الْخِيَارِ". (م)', 'അബൂഹുമൈദ്(റ): ഞങ്ങൾ തബൂക് യുദ്ധത്തിന് റസൂൽ(സ)യുടെ കൂടെ പുറപ്പെട്ടു. ഞങ്ങൾ വാദിഖുറയിൽ, ഒരു സ്ത്രീയുടെ തോട്ടത്തിനടുത്തെത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തോട്ടത്തിലുള്ള കാരക്കയുടെ മതിപ്പു കണക്കാക്കുക." ഞങ്ങളത് കണക്കാക്കി. റസൂൽ(സ) അത് പത്ത് വസ്ഖായിട്ടാണ് കണക്കാക്കിയത്. അവിടുന്ന് പറഞ്ഞു: "നീ അത് അളന്ന് തിട്ടപ്പെടുത്തുക, ഇൻശാഅല്ലാഹ്, ഞങ്ങൾ നിന്റെയടുത്തേക്ക് മടങ്ങിവരുന്നതാണ്." അങ്ങനെ ഞങ്ങൾ പുറപ്പെട്ട് തബൂക്കിലെത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇന്ന് രാത്രി നിങ്ങളുടെ മേൽ ശക്തമായ കൊടുങ്കാറ്റ് അടിച്ചുവീശും. കൊടുങ്കാറ്റിന്റെ സമയത്ത് നിങ്ങളാരും എണീറ്റ് നിൽക്കരുത്. ഒട്ടകമുള്ളവർ അതിന്റെ കയർ ബന്ധിക്കണം." അങ്ങനെ കൊടുങ്കാറ്റ് അടിച്ചുവീശി. അപ്പോൾ ഒരാൾ എഴുന്നേറ്റുനിന്നു. കാറ്റയാളെ ത്വയ്യിഅ് പർവതത്തിൽ കൊണ്ടുപോയിട്ടു. ഐലയിലെ ഭരണാധിപൻ ഇബ്നുഅൽമാഇന്റെ ദൂതൻ റസൂൽ(സ)യുടെ അടുത്ത് ഒരു കത്തുമായി വന്നു. അദ്ദേഹം റസൂൽ(സ)ക്ക് ഒരു വെളുത്ത കോവർകഴുതയെ സമ്മാനമായി നൽകി. റസൂൽ(സ) അദ്ദേഹത്തിന് തിരിച്ച് ഒരു കത്തെഴുതുകയും വരകളുള്ള ഒരു പുതപ്പ് സമ്മാനമായി നൽകുകയും ചെയ്തു. പിന്നീട് ഞങ്ങൾ നടന്ന് വാദിൽഖുറയിലെത്തി. റസൂൽ(സ) ആ സ്ത്രീയോട് തന്റെ തോട്ടത്തിലെ പഴങ്ങളെത്രയുണ്ടായിരുന്നുവെന്ന് ചോദിച്ചു. പത്ത് വസ്ഖാണെന്ന് അവൾ മറുപടി പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ധൃതിയിൽ പോവുകയാണ്. ധൃതിയിൽ പോരാനുദ്ദേശിക്കുന്നവർ എന്റെ കൂടെ പെട്ടെന്ന് പോരുക. ഇവിടെ തങ്ങാൻ ഉദ്ദേശിക്കുന്നവർ തങ്ങിക്കൊള്ളുക." ഞങ്ങൾ പുറപ്പെട്ട് മദീനയിലെത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇത് ത്വാബയാണ്, ഇത് ഉഹ്ദാണ്. നമ്മെ സ്നേഹിക്കുന്ന, നാം സ്നേഹിക്കുന്ന പർവതമാണ് ഉഹ്ദ്." വീണ്ടും റസൂൽ(സ) പറഞ്ഞു: "അൻസാറുകളുടെ ഗൃഹങ്ങളിൽ ഏറ്റവും നല്ലത് ബനൂനജ്ജാറിന്റെ വീടാണ്. പിന്നെ ബനൂഅബ്ദിൽ അശ്ഹലിന്റെ വീടാണ്. പിന്നെ ബനൂഅബ്ദിൽ ഹാരിസുബ്നുൽ ഖസ്റജിന്റെ വീടാണ്. പിന്നെ ബനൂസാഇദയുടെ വീടാണ്. അൻസാറുകളുടെ എല്ലാ വീടുകളിലും നന്മയുണ്ട്." പിന്നീട് സഅ്ദുബ്നു ഉബാദ(റ) ഞങ്ങളെ കണ്ടുമുട്ടി. അപ്പോൾ അബൂഉസൈദ്(റ) പറഞ്ഞു: റസൂൽ(സ) അൻസാറുകളുടെ വീടുകൾ തെരഞ്ഞെടുത്തതും നമ്മെ അവസാനമാക്കിയതും താങ്കൾ അറിഞ്ഞില്ലേ? അപ്പോൾ സഅ്ദ്(റ) റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് അൻസാറുകളുടെ വീട് തെരഞ്ഞെടുക്കുകയും ഞങ്ങളെ അവിടുന്ന് അവസാനമാക്കുകയും ചെയ്തല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഉത്തമരിൽ പെടുന്നുവെന്നത് തന്നെ നിങ്ങൾക്ക് പോരേ." (മു)', 'أَبِي حُمَيْدٍ', 'അബൂഹുമൈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 316, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلِي كَمَثَلِ رَجُلٍ اسْتَوْقَدَ نَارًا، فَلَمَّا أَضَاءَتْ مَا حَوْلَهَا جَعَلَ الْفَرَاشُ وَهَذِهِ الدَّوَابُّ الَّتِي فِي النَّارِ يَقَعْنَ فِيهَا، وَجَعَلَ يَحْجُزُهُنَّ وَيَغْلِبْنَهُ فَيَتَقَحَّمْنَ فِيهَا، قَالَ: فَذَلِكُمْ مَثَلِي وَمَثَلُكُمْ، أَنَا آخِذٌ بِحُجَزِكُمْ عَنِ النَّارِ، هَلُمَّ عَنِ النَّارِ، هَلُمَّ عَنِ النَّارِ، فَتَغْلِبُونِي وَتَقَحَّمُونَ فِيهَا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഉപമ തീ കത്തിച്ചുവെച്ച ഒരാളുടെ ഉപമയാണ്. തീ ചുറ്റുമുള്ളതിനെ പ്രകാശിപ്പിച്ചപ്പോൾ പാറ്റകളും ഈ കീടങ്ങളും അതിൽ വന്ന് വീണു. അദ്ദേഹം അവയെ അകറ്റുന്നു. അവ അദ്ദേഹത്തെ മറികടന്ന് തീയിൽ ചാടിവീഴുന്നു. ഇതാണ് എന്റെയും നിങ്ങളുടെയും ഉപമ. നിങ്ങളെ നരകത്തിൽ നിന്ന് രക്ഷപ്പെടുത്താൻ നിങ്ങളുടെ അരയിൽ പിടിച്ചു നിർത്തിയിരിക്കുകയാണ് ഞാൻ. നിങ്ങൾ നരകത്തിൽ നിന്ന് രക്ഷപ്പെടുക, നിങ്ങൾ നരകത്തിൽ നിന്ന് രക്ഷപ്പെടുക (എന്നു ഞാൻ പറയുന്നു). അപ്പോൾ നിങ്ങളെന്നെ കവച്ചുവെക്കുകയും അതിൽ ചെന്ന് ചാടുകയും ചെയ്യുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 318, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَمْرٍ، فَتَنَزَّهَ عَنْهُ نَاسٌ مِنَ النَّاسِ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَغَضِبَ حَتَّى بَانَ الْغَضَبُ فِي وَجْهِهِ، ثُمَّ قَالَ: "مَا بَالُ قَوْمٍ يَرْغَبُونَ عَمَّا رُخِّصَ لِي فِيهِ؟ فَوَاللهِ لَأَنَا أَعْلَمُهُمْ بِاللهِ عَزَّ وَجَلَّ، وَأَشَدُّهُمْ لَهُ خَشْيَةً". (م)', 'ആഇശ(റ): ഒരു വിഷയത്തിൽ റസൂൽ(സ) ഇളവ് നൽകി. അപ്പോൾ ജനങ്ങളിൽ ഒരു വിഭാഗം അത് നിരാകരിച്ചു. ഈ വിവരം നബി(സ)യുടെ അടുക്കലെത്തി. അപ്പോൾ ദേഷ്യം അവിടുത്തെ മുഖത്തിൽ പ്രകടമാകും വിധം റസൂൽ(സ) ദേഷ്യപ്പെട്ടു. പിന്നെ അവിടുന്ന് പറഞ്ഞു: "എനിക്ക് ഇളവ് നൽകപ്പെട്ട കാര്യം നിരാകരിക്കുന്ന ആളുകളുടെ അവസ്ഥയെന്താണ്? അല്ലാഹു തന്നെ സത്യം, ഞാനവരേക്കാൾ അല്ലാഹുവിനെ അറിയുന്നവനും അവരേക്കാൾ അല്ലാഹുവിനെ ഭയക്കുന്നവനുമാണ്." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 318, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: مَا خُيِّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلَّا أَخَذَ أَيْسَرَهُمَا مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ إِلَّا أَنْ تُنْتَهَكَ حُرْمَةُ اللهِ عَزَّ وَجَلَّ. (م)', 'നബി(സ)യുടെ ഭാര്യയായ ആഇശ(റ): റസൂൽ(സ)യോട് രണ്ട് കാര്യങ്ങൾക്കിടയിൽ ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ പറയുമ്പോളെല്ലാം, പാപമല്ലെങ്കിൽ അവിടുന്ന് അതിൽ ഏറ്റവും എളുപ്പമുള്ളത് സ്വീകരിക്കും. അത് പാപമാണെങ്കിൽ അതിൽ നിന്ന് ഏറ്റവും അകന്നുനിൽക്കുന്നത് തിരുമേനി(സ)യായിരിക്കും. അല്ലാഹുവിന്റെ പവിത്രത ഹനിക്കപ്പെടുമ്പോഴല്ലാതെ റസൂൽ(സ) സ്വന്തത്തിന് വേണ്ടി പ്രതികാരം ചെയ്തിട്ടില്ല. (മു)', 'عَائِشَةَ', 'നബി(സ)യുടെ ഭാര്യയായ ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 318, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى حَتَّى انْتَفَخَتْ قَدَمَاهُ، فَقِيلَ لَهُ: أَتَكَلَّفُ هَذَا، وَقَدْ غَفَرَ اللهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ؟ قَالَ: "أَفَلَا أَكُونُ عَبْدًا شَكُورًا". (م)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): നബി(സ) നിസ്കരിച്ച് അവിടുത്തെ ഇരുകാലുകളിലും നീര് വന്നുവീർത്തു. അപ്പോൾ അവിടുത്തോട് ആരോ ചോദിച്ചു: അവിടുന്നെന്തിനാണ് ഇങ്ങനെ പ്രയാസപ്പെടുന്നത്? മുൻകഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ അങ്ങയുടെ പാപങ്ങൾ അല്ലാഹു പൊറുത്തുതന്നിട്ടില്ലേ? നബി(സ) പറഞ്ഞു: "ഞാനൊരു നന്ദിയുള്ള അടിമയായിത്തീരേണ്ടേ." (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 319, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَوْضِي مَسِيرَةُ شَهْرٍ، وَزَوَايَاهُ سَوَاءٌ، وَمَاؤُهُ أَبْيَضُ مِنَ الْوَرِقِ، وَرِيحُهُ أَطْيَبُ مِنَ الْمِسْكِ، كِيزَانُهُ كَنُجُومِ السَّمَاءِ، فَمَنْ شَرِبَ مِنْهُ فَلَا يَظْمَأُ بَعْدَهُ أَبَدًا". قَالَ: وَقَالَتْ أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي عَلَى الْحَوْضِ حَتَّى أَنْظُرَ مَنْ يَرِدُ عَلَيَّ مِنْكُمْ، وَسَيُؤْخَذُ أُنَاسٌ دُونِي، فَأَقُولُ: يَا رَبِّ مِنِّي وَمِنْ أُمَّتِي، فَيُقَالُ: أَمَا شَعَرْتَ مَا عَمِلُوا بَعْدَكَ، وَاللهِ مَا بَرِحُوا بَعْدَكَ يَرْجِعُونَ عَلَى أَعْقَابِهِمْ". قَالَ: فَكَانَ ابْنُ أَبِي مُلَيْكَةَ يَقُولُ: اللَّهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نَرْجِعَ عَلَى أَعْقَابِنَا، أَوْ [أَنْ] نُفْتَنَ عَنْ دِينِنَا. (م)', 'അബ്ദുല്ലാഹിബ്നു അംറിബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഹൗളിന് ഒരു മാസത്തെ യാത്രാദൂരമുണ്ട്. അതിന്റെ എല്ലാ ഭാഗങ്ങളും സമമാണ്. അതിലെ പാനീയം വെള്ളിയേക്കാൾ വെളുത്തതാണ്. അതിന്റെ വാസന കസ്തൂരിയേക്കാൾ സുഗന്ധപൂർണമാണ്. അതിലെ കോപ്പകൾ ആകാശത്തിലെ നക്ഷത്രങ്ങൾ പോലെയാണ്. അതിൽ നിന്നാരെങ്കിലും കുടിച്ചാൽ പിന്നീടൊരിക്കലും അവന് ദാഹിക്കുകയില്ല." അസ്മാഉബിൻത് അബീബക്ർ(റ) പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ഹൗളിന്റെ അരികിലുണ്ടാകും. അങ്ങനെ നിങ്ങളിൽ ആരാണ് എന്റടുത്ത് വരുന്നതെന്ന് ഞാൻ വീക്ഷിക്കും. ചിലയാളുകളെ എന്റെ മുന്നിൽവെച്ച് പിടികൂടപ്പെടും. അപ്പോൾ ഞാൻ ചോദിക്കും: എന്റെ രക്ഷിതാവേ, എന്നിൽനിന്നും എന്റെ സമൂഹത്തിൽ നിന്നുമാണോ പിടകൂടപ്പെടുന്നത്? അപ്പോൾ (റസൂൽ(സ)യോട്) പറയപ്പെടും: അങ്ങേക്ക് ശേഷം അവർ എന്താണ് ചെയ്തതെന്ന് അങ്ങേക്കറിയുമോ? അല്ലാഹു തന്നെ സത്യം, അവർ (ദീനിൽ നിന്ന്) പിൻവാങ്ങിക്കൊണ്ടിരുന്നു." നിവേദകൻ പറയുന്നു: ഇബ്നുഅബീമുലൈക(റ) പറയുമായിരുന്നു: അല്ലാഹുവേ, ദീനിൽ നിന്ന് പിന്തിരിയുകയും ദീനിൽ പരീക്ഷിക്കപ്പെടുകയും ചെയ്യുന്നതിൽ നിന്ന് ഞങ്ങൾ നിന്നോട് കാവൽ ചോദിക്കുന്നു. (മു)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറിബ്നുൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'أَنْ', null, 319, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ حَارِثَةَ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حَوْضُهُ مَا بَيْنَ صَنْعَاءَ وَالْمَدِينَةِ". فَقَالَ لَهُ الْمُسْتَوْرِدُ: أَلَمْ تَسْمَعْهُ قَالَ: الْأَوَانِي؟ [قَالَ: لَا] فَقَالَ الْمُسْتَوْرِدُ: "تُرَى فِيهِ الْآنِيَةُ مِثْلَ الْكَوَاكِبِ". (م)', 'ഹാരിസതുബ്നു വഹബ്(റ): അദ്ദേഹം നബി(സ) പറയുന്നത് കേട്ടു: "നബി(സ)യുടെ ഹൗളിന് സൻആയുടെയും മദീനയുടെയുമിടയിലുള്ള ദൂരമുണ്ട്." ഹാരിസുബ്നു വഹ്ബ്(റ)വിനോട് മുസ്തൗരിദ്(റ) ചോദിച്ചു: നബി(സ) അതിലെ പാത്രങ്ങളെ കുറിച്ച് പറയുന്നത് നിങ്ങൾ കേട്ടിട്ടുണ്ടോ? അദ്ദേഹം ഇല്ലെന്ന് മറുപടി പറഞ്ഞു. അപ്പോൾ മുസ്തൗരിദ്(റ) പറഞ്ഞു: "അതിലെ പാത്രങ്ങൾ നക്ഷത്രങ്ങളെപ്പോലെ കാണാം." (മു)', 'حَارِثَةَ بْنِ وَهْبٍ', 'ഹാരിസതുബ്നു വഹബ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ: لَا', null, 319, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَمَامَكُمْ حَوْضًا كَمَا بَيْنَ جَرْبَاءَ وَأَذْرُحَ". وَفِي رِوَايَةٍ: "حَوْضِي". وَفِي رِوَايَةٍ: قَالَ عُبَيْدُ اللهِ: فَسَأَلْتُهُ – يَعْنِي نَافِعًا – فَقَالَ: قَرْيَتَيْنِ بِالشَّامِ، بَيْنَهُمَا مَسِيرَةُ ثَلَاثِ لَيَالٍ، وَفِي رِوَايَةٍ: ثَلَاثَةِ أَيَّامٍ. (م)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ജർബാഇനും അസ്റുഹിനുമിടയിലുള്ള ദൂരത്തോളം വലിപ്പമുള്ള ഒരു ഹൗള് നിശ്ചയം നിങ്ങൾക്കു മുമ്പിലുണ്ട്." മറ്റൊരു നിവേദനത്തിൽ "എന്റെ ഹൗള്" എന്നാണ്. മറ്റൊരു നിവേദനത്തിൽ ഉബൈദുല്ലാഹ്(റ) പറയുന്നു: ഞാൻ അതിനെ സംബന്ധിച്ച് നാഫിഅ്(റ)വിനോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവ ശാമിലെ രണ്ട് ഗ്രാമങ്ങളാണ്. അവക്കിടയിൽ മൂന്ന് രാത്രിയുടെ യാത്രാദൂരമുണ്ട്. മറ്റൊരു നിവേദനത്തിൽ മൂന്ന് ദിവസത്തെ എന്നാണ്. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=62), 1, 'وَفِي رِوَايَةٍ: "حَوْضِي".', 'മറ്റൊരു നിവേദനത്തിൽ "എന്റെ ഹൗള്" എന്നാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=62), 2, 'وَفِي رِوَايَةٍ: قَالَ عُبَيْدُ اللهِ: فَسَأَلْتُهُ – يَعْنِي نَافِعًا – فَقَالَ: قَرْيَتَيْنِ بِالشَّامِ، بَيْنَهُمَا مَسِيرَةُ ثَلَاثِ لَيَالٍ،', 'മറ്റൊരു നിവേദനത്തിൽ ഉബൈദുല്ലാഹ്(റ) പറയുന്നു: ഞാൻ അതിനെ സംബന്ധിച്ച് നാഫിഅ്(റ)വിനോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവ ശാമിലെ രണ്ട് ഗ്രാമങ്ങളാണ്. അവക്കിടയിൽ മൂന്ന് രാത്രിയുടെ യാത്രാദൂരമുണ്ട്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=62), 3, 'وَفِي رِوَايَةٍ: ثَلَاثَةِ أَيَّامٍ. (م)', 'മറ്റൊരു നിവേദനത്തിൽ മൂന്ന് ദിവസത്തെ എന്നാണ്. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا إِنِّي فَرَطٌ لَكُمْ عَلَى الْحَوْضِ، وَإِنَّ بُعْدَ مَا بَيْنَ طَرَفَيْهِ كَمَا بَيْنَ صَنْعَاءَ وَأَيْلَةَ، كَأَنَّ الْأَبَارِيقَ فِيهِ النُّجُومُ". (م)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറിയുക, നിങ്ങൾക്കു മുമ്പേ ഞാൻ ഹൗളിനടുത്തെത്തുന്നതാണ്. അതിന്റെ രണ്ട് അറ്റങ്ങൾക്കിടയിലുള്ള ദൂരം സ്വൻആഇന്റെയും ഐലയുടെയും ഇടയിലുള്ള ദൂരമാണ്. അതിലെ കോപ്പകൾ നക്ഷത്രങ്ങളെപ്പോലെയായിരിക്കും." (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، مَا آنِيَةُ الْحَوْضِ؟ قَالَ: "وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ نُجُومِ السَّمَاءِ وَكَوَاكِبِهَا، أَلَا فِي اللَّيْلَةِ الْمُظْلِمَةِ الْمُصْحِيَةِ، آنِيَةُ الْجَنَّةِ مَنْ شَرِبَ مِنْهَا لَمْ يَظْمَأْ آخِرَ مَا عَلَيْهِ، يَشْخَبُ فِيهِ مِيزَابَانِ مِنَ الْجَنَّةِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ، عَرْضُهُ مِثْلُ طُولِهِ مَا بَيْنَ عَمَّانَ إِلَى أَيْلَةَ، مَاؤُهُ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ وَأَحْلَى مِنَ الْعَسَلِ". (م)', 'അബൂദർറ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഹൗളിലെ പാത്രങ്ങൾ ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "മുഹമ്മദിന്റെ ശരീരം ആരുടെ കയ്യിലാണോ, അവൻ തന്നെ സത്യം, അതിലെ പാത്രങ്ങൾ കൂരിരുട്ടുള്ള രാത്രിയിലെ ആകാശത്തെ നക്ഷത്രങ്ങളേക്കാളും ഗ്രഹങ്ങളേക്കാളുമധികമാണ്. സ്വർഗത്തിലെ പാത്രങ്ങളിൽ നിന്നാരെങ്കിലും കുടിച്ചാൽ പിന്നെ അവനൊരിക്കലും ദാഹിക്കില്ല. സ്വർഗ്ഗത്തിൽ നിന്നുള്ള രണ്ട് അരുവികൾ അതിൽ ചേരുന്നുണ്ട്. അതിൽനിന്ന് കുടിച്ചവന് പിന്നെ ദാഹിക്കുകയില്ല. അതിന്റെ വീതിയും നീളവും ഒരുപോലെയാണ്, അഥവാ അമ്മാന്റെയും ഐലയുടെയും ഇടയിലുള്ള യാത്രാദൂരത്തോളമാണ്. അതിലെ പാനീയം പാലിനേക്കാൾ വെളുത്തതും തേനിനേക്കാൾ മധുരമുള്ളതുമാണ്." (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي لَبِعُقْرِ حَوْضِي أَذُودُ النَّاسَ لِأَهْلِ الْيَمَنِ، أَضْرِبُ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ". فَسُئِلَ عَنْ عَرْضِهِ؟ فَقَالَ: "مِنْ مَقَامِي إِلَى عَمَّانَ". وَسُئِلَ عَنْ شَرَابِهِ؟ فَقَالَ: "أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ، يَغُتُّ فِيهِ مِيزَابَانِ يَمُدَّانِهِ مِنَ الْجَنَّةِ، أَحَدُهُمَا مِنْ ذَهَبٍ وَالْآخَرُ مِنْ وَرِقٍ". (م)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "യമനുകാർക്ക് വഴി നൽകാൻ ജനങ്ങളെ തടഞ്ഞുകൊണ്ട് ഞാൻ എന്റെ ഹൗളിന്റെയരികെ നിൽക്കും. അവർക്ക് ഹൗള് വിശാലമായി ഒഴുകാൻ ഞാൻ അതിൽ അടിക്കും." അപ്പോൾ റസൂൽ(സ)യോട് അതിന്റെ വീതിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "എന്റെ ഈ സ്ഥലത്തുനിന്ന് അമ്മാൻ വരെ." അതിലെ പാനീയത്തെക്കുറിച്ച് അവിടത്തോട് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "പാലിനേക്കാൾ വെളുപ്പ് നിറമുള്ളതും തേനിനേക്കാൾ മധുരമുള്ളതുമാണ്. സ്വർഗത്തിൽ നിന്നുള്ള രണ്ട് അരുവികൾ അതിലേക്ക് കുത്തിയൊഴുകുന്നുണ്ട്. അതിലൊന്ന് സ്വർണത്തിന്റേതും മറ്റേത് വെള്ളിയുടേതുമാണ്." (മു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 320, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يَوْمًا فَصَلَّى عَلَى أَهْلِ أُحُدٍ صَلَاتَهُ عَلَى الْمَيِّتِ، ثُمَّ انْصَرَفَ إِلَى الْمِنْبَرِ فَقَالَ: "إِنِّي فَرَطٌ لَكُمْ وَأَنَا شَهِيدٌ عَلَيْكُمْ، وَإِنِّي وَاللهِ لَأَنْظُرُ إِلَى حَوْضِي الْآنَ، وَإِنِّي قَدْ أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ الْأَرْضِ، أَوْ: مَفَاتِيحَ الْأَرْضِ، وَإِنِّي وَاللهِ مَا أَخَافُ عَلَيْكُمْ أَنْ تُشْرِكُوا بَعْدِي، وَلَكِنْ أَخَافُ عَلَيْكُمْ أَنْ تَتَنَافَسُوا فِيهَا". (ق)', 'ഉബ്ബതുബ്നു ആമിർ(റ): ഒരു ദിവസം റസൂൽ(സ) പുറത്തുവന്ന് ഉഹ്ദിലെ ആളുകളുടെ (രക്തസാക്ഷികളുടെ) മേൽ, മയ്യിത്തിനുവേണ്ടി നമസ്കരിക്കുംവിധം, നമസ്കരിച്ചു. പിന്നെ മിമ്പറിൽ കയറിക്കൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: "നിശ്ചയം ഞാൻ നിങ്ങളെ (പാരത്രിക ലോകത്ത്) പ്രതീക്ഷിച്ചിരിക്കുന്നവനാണ്, ഞാൻ നിങ്ങൾക്കുമേൽ സാക്ഷിയുമാണ്. അല്ലാഹു തന്നെ സത്യം, ഇപ്പോൾ നിശ്ചയം ഞാൻ എന്റെ ഹൗളിലേക്ക് നോക്കുന്നു. എനിക്ക് ഭൂമിയിലെ ഖജനാവുകളുടെ താക്കോലുകൾ (അല്ലെങ്കിൽ ഭൂമിയുടെ താക്കോലുകൾ) നൽകപ്പെട്ടിരിക്കുന്നു. അല്ലാഹു തന്നെ സത്യം, എനിക്കുശേഷം നിങ്ങൾ ബഹുദൈവാരാധകരാകുമെന്ന് തീർച്ചയായും ഞാൻ ഭയക്കുന്നില്ല. എന്നാൽ നിങ്ങൾ ഐഹിക ജീവിതത്തിൽ പരസ്പരം മത്സരിക്കുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു." (ബു,മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉബ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي، وَإِذَا مَاتَ صَاحِبُكُمْ فَدَعُوهُ". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വന്തം കുടുംബത്തോട് നല്ലനിലയിൽ പെരുമാറുന്നവരാണ് നിങ്ങളിൽ ഉത്തമർ. ഞാൻ നിങ്ങൾക്കിടയിൽ കുടുംബത്തോട് ഏറ്റവും നല്ലനിലയിൽ പെരുമാറുന്നവനാണ്. നിങ്ങളുടെ സഹചാരി മരണപ്പെട്ടാൽ നിങ്ങളയാളെ ഒഴിവാക്കിയിടുക (ആക്ഷേപിക്കരുത്)." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ مِنْ أَصْحَابِي شَيْئًا، فَإِنِّي أُحِبُّ أَنْ أَخْرُجَ إِلَيْهِمْ وَأَنَا سَلِيمُ الصَّدْرِ". قَالَ عَبْدُ اللهِ: فَأُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَالٍ، فَقَسَمَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْتَهَيْتُ إِلَى رَجُلَيْنِ جَالِسَيْنِ وَهُمَا يَقُولَانِ: وَاللهِ مَا أَرَادَ مُحَمَّدٌ بِقِسْمَتِهِ الَّتِي قَسَمَهَا وَجْهَ اللهِ وَلَا الدَّارَ الْآخِرَةَ. فَتَثَبَّتُّ حِينَ سَمِعْتُهُمَا، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَخْبَرْتُهُ، فَاحْمَرَّ وَجْهُهُ وَقَالَ: "دَعْنِي عَنْكَ، فَقَدْ أُوذِيَ مُوسَى بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ". وَفِي رِوَايَةٍ: "لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ شَيْئًا". (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അനുചരരിൽ ഒരാളെപ്പറ്റിയും ആരും എനിക്ക് ഒന്നും അറിയിച്ചു തരരുത്. നിഷ്കളങ്ക ഹൃദയത്തോടെ (മനസ്സിൽ ഒന്നുമില്ലാതെ) അവരുടെ അടുത്തേക്ക് ചെല്ലുന്നതാണ് എനിക്കിഷ്ടം." അബ്ദുല്ല(റ) പറഞ്ഞു: ഒരിക്കൽ നബി(സ)യുടെ അടുത്ത് എന്തോ മുതൽ എത്തുകയും നബി(സ) അത് വീതിക്കുകയും ചെയ്തു. അങ്ങനെ (അവിടെ) ഇരിക്കുകയായിരുന്ന രണ്ടാളുകളുടെ അടുത്തേക്ക് ഞാൻ ചെന്നു. അവർ ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: അല്ലാഹു തന്നെ സത്യം, ഈ വിഹിതം വെക്കലിൽ മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ തൃപ്തിയോ പാരത്രിക ലോകത്തെയോ ആഗ്രഹിച്ചിട്ടില്ല (നീതി പാലിച്ചിട്ടില്ല). അതു കേട്ടപ്പോൾ ഞാൻ അവിടെ നിൽക്കുകയും ശേഷം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് വിവരം പറയുകയും ചെയ്തു. അപ്പോൾ അവിടുത്തെ മുഖം ചുവക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഇക്കാര്യം നീ എന്നോട് പറയേണ്ട, മൂസാ(അ)മിന് ഇതിനേക്കാൾ അധികം പ്രയാസം ഏൽക്കുകയും എന്നിട്ട് ക്ഷമിക്കുകയും ചെയ്തിട്ടുണ്ട്." മറ്റൊരു നിവേദനം: "ഒരാളും മറ്റൊരാളെക്കുറിച്ച് എനിക്ക് ഒന്നും അറിയിച്ചു തരരുത്." (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 321, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=68), 1, 'وَفِي رِوَايَةٍ: "لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ شَيْئًا". (ت)', 'മറ്റൊരു നിവേദനം: "ഒരാളും മറ്റൊരാളെക്കുറിച്ച് എനിക്ക് ഒന്നും അറിയിച്ചു തരരുത്." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، وَقَدْ سُئِلَ: مَنْ آذَنَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْجِنِّ لَيْلَةَ اسْتَمَعُوا الْقُرْآنَ؟ فَقَالَ: إِنَّهُ آذَنَتْ بِهِمْ شَجَرَةٌ. (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ജിന്നുകൾ രാത്രി ഖുർആൻ ശ്രദ്ധിച്ചുകേട്ട സംഭവം ആരാണ് നബി(സ)യെ അറിയിച്ചത് എന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവരെക്കുറിച്ച് നബി(സ)ക്ക് വിവരമറിയിച്ചത് ഒരു വൃക്ഷമാണ്. (ബു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَحْمِلُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِدَاوَةً لِوَضُوئِهِ وَحَاجَتِهِ. قَدْ تَقَدَّمَ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصْدَقُ كَلِمَةٍ قَالَهَا الشَّاعِرُ، كَلِمَةُ لَبِيدٍ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنِ ابْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا: وَقَدْ سُئِلَ عَنْ أَشَدِّ مَا صَنَعَهُ الْمُشْرِكُونَ بِالنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي حِجْرِ الْكَعْبَةِ، إِذْ أَقْبَلَ عُقْبَةُ بْنُ أَبِي مُعَيْطٍ، فَوَضَعَ ثَوْبَهُ فِي عُنُقِهِ فَخَنَقَهُ خَنْقًا شَدِيدًا، فَأَقْبَلَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ حَتَّى أَخَذَ بِمَنْكِبِهِ وَدَفَعَهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: {أَتَقْتُلُونَ رَجُلًا أَنْ يَقُولَ رَبِّيَ اللهُ} الْآيَةَ. (خ)', 'ഇബ്നുഅംറുബ്നുൽ ആസ്(റ): ബഹുദൈവവിശ്വാസികൾ നബി(സ)യോട് ചെയ്ത ഏറ്റവും കഠിനമായ കൃത്യത്തെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) കഅ്ബയുടെ ഹിജ്റിൽ വെച്ച് നിസ്കരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ ഉഖ്ബതുബ്നു അബീമുഐത് വരികയും തന്റെ വസ്ത്രം നബി(സ)യുടെ കഴുത്തിലിട്ട് ശക്തമായി മുറുക്കുകയും ചെയ്തു. ഉടനെ അബൂബക്കർ(റ) വന്ന് അവന്റെ ചുമലിൽ പിടിച്ച് നബി(സ)യുടെ അടുത്ത് നിന്ന് അവനെ മാറ്റുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: ''എന്റെ നാഥൻ അല്ലാഹുവാണ് എന്ന് പറഞ്ഞതിന്റെ പേരിൽ ഒരു മനുഷ്യനെ നിങ്ങൾ വധിക്കുന്നുവോ?'' (ബു)', 'ابْنِ عَمْرِو بْنِ الْعَاصِ', 'ഇബ്നുഅംറുബ്നുൽ ആസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 322, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَمَّا كَذَّبَتْنِي قُرَيْشٌ قُمْتُ فِي الْحِجْرِ، فَجَلَا اللهُ لِي بَيْتَ الْمَقْدِسِ، فَطَفِقْتُ أُخْبِرُهُمْ عَنْ آيَاتِهِ وَأَنَا أَنْظُرُ إِلَيْهِ". (ق,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് നിശ്ചയം അദ്ദേഹം കേട്ടു: "ഖുറൈശികൾ എന്നെ (എന്റെ പ്രവാചകത്വത്തെ) നിഷേധിച്ചപ്പോൾ ഞാൻ ഹിജ്റിൽ പോയി നിന്നു. അന്നേരം അല്ലാഹു എനിക്ക് ബൈതുൽമുഖദ്ദസ് ദൃശ്യമാക്കിത്തന്നു. അങ്ങനെ ഞാൻ അങ്ങോട്ട് നോക്കി അതിലെ ദൃഷ്ടാന്തങ്ങൾ സത്യനിഷേധികൾക്ക് വിവരിച്ചു നൽകാൻ തുടങ്ങി." (ബു,മു,തു,ന)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ مَالِكِ بْنِ صَعْصَعَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُمْ عَنْ لَيْلَةِ أُسْرِيَ بِهِ، قَالَ: "بَيْنَمَا أَنَا فِي الْحَطِيمِ، وَرُبَّمَا قَالَ: فِي الْحِجْرِ، مُضْطَجِعًا إِذْ أَتَانِي آتٍ فَقَدَّ قَالَ: وَسَمِعْتُهُ يَقُولُ: فَشَقَّ مَا بَيْنَ هَذِهِ إِلَى هَذِهِ، قَالَ الرَّاوِي: مِنْ ثُغْرَةِ نَحْرِهِ إِلَى شِعْرَتِهِ، فَاسْتَخْرَجَ قَلْبِي، ثُمَّ أُتِيتُ بِطَسْتٍ مِنْ ذَهَبٍ مَمْلُوءَةٍ إِيمَانًا، فَغُسِلَ قَلْبِي ثُمَّ حُشِيَ، ثُمَّ أُعِيدَ، ثُمَّ أُتِيتُ بِدَابَّةٍ دُونَ الْبَغْلِ وَفَوْقَ الْحِمَارِ، أَبْيَضَ، قَالَ الرَّاوِي: وَهُوَ الْبُرَاقُ، يَضَعُ خَطْوَهُ عِنْدَ أَقْصَى طَرْفِهِ فَحُمِلْتُ عَلَيْهِ، فَانْطَلَقَ بِي جِبْرِيلُ حَتَّى أَتَى السَّمَاءَ الدُّنْيَا، فَاسْتَفْتَحَ، فَقِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قِيلَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَفُتِحَ، فَلَمَّا خَلَصْتُ فَإِذَا فِيهَا آدَمُ، فَقَالَ: هَذَا أَبُوكَ آدَمُ فَسَلِّمْ عَلَيْهِ، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ السَّلَامَ ثُمَّ قَالَ: مَرْحَبًا بِالِابْنِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ صَعِدَ بِي حَتَّى أَتَى السَّمَاءَ الثَّانِيَةَ، فَاسْتَفْتَحَ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قِيلَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَفُتِحَ، فَلَمَّا خَلَصْتُ إِذَا يَحْيَى وَعِيسَى، وَهُمَا ابْنَا الْخَالَةِ، قَالَ: هَذَا يَحْيَى وَعِيسَى فَسَلِّمْ عَلَيْهِمَا، فَسَلَّمْتُ، فَرَدَّا ثُمَّ قَالَا: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ صَعِدَ بِي إِلَى السَّمَاءِ الثَّالِثَةِ، فَاسْتَفْتَحَ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قِيلَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَفُتِحَ، فَلَمَّا خَلَصْتُ إِذَا يُوسُفُ، قَالَ: هَذَا يُوسُفُ فَسَلِّمْ عَلَيْهِ، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ ثُمَّ قَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ صَعِدَ بِي حَتَّى أَتَى السَّمَاءَ الرَّابِعَةَ، فَاسْتَفْتَحَ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: أَوَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قِيلَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَفُتِحَ، فَلَمَّا خَلَصْتُ إِذَا إِدْرِيسُ، قَالَ: هَذَا إِدْرِيسُ فَسَلِّمْ عَلَيْهِ، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ ثُمَّ قَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ صَعِدَ بِي حَتَّى أَتَى السَّمَاءَ الْخَامِسَةَ، فَاسْتَفْتَحَ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قِيلَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَلَمَّا خَلَصْتُ فَإِذَا هَارُونُ، قَالَ: هَذَا هَارُونُ فَسَلِّمْ عَلَيْهِ، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ ثُمَّ قَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ صَعِدَ بِي حَتَّى أَتَى السَّمَاءَ السَّادِسَةَ، فَاسْتَفْتَحَ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: مَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، قَالَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَلَمَّا خَلَصْتُ فَإِذَا مُوسَى، قَالَ: هَذَا مُوسَى فَسَلِّمْ عَلَيْهِ، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ ثُمَّ قَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. فَلَمَّا تَجَاوَزْتُ بَكَى، قِيلَ لَهُ: مَا يُبْكِيكَ؟ قَالَ: أَبْكِي لِأَنَّ غُلَامًا بُعِثَ بَعْدِي يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِهِ أَكْثَرُ مِمَّنْ يَدْخُلُهَا مِنْ أُمَّتِي. ثُمَّ صَعِدَ بِي إِلَى السَّمَاءِ السَّابِعَةِ، فَاسْتَفْتَحَ جِبْرِيلُ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: نَعَمْ، قَالَ: مَرْحَبًا بِهِ فَنِعْمَ الْمَجِيءُ جَاءَ، فَلَمَّا خَلَصْتُ فَإِذَا إِبْرَاهِيمُ، قَالَ: هَذَا أَبُوكَ فَسَلِّمْ عَلَيْهِ، قَالَ: فَسَلَّمْتُ عَلَيْهِ فَرَدَّ السَّلَامَ، قَالَ: مَرْحَبًا بِالِابْنِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ. ثُمَّ رُفِعْتُ إِلَيَّ سِدْرَةُ الْمُنْتَهَى، فَإِذَا نَبْقُهَا مِثْلُ قِلَالِ هَجَرَ، وَإِذَا وَرَقُهَا مِثْلُ آذَانِ الْفِيَلَةِ، قَالَ: هَذِهِ سِدْرَةُ الْمُنْتَهَى، وَإِذَا أَرْبَعَةُ أَنْهَارٍ: نَهْرَانِ ظَاهِرَانِ وَنَهْرَانِ بَاطِنَانِ، فَقُلْتُ: مَا هَذَانِ يَا جِبْرِيلُ؟ قَالَ: أَمَّا الْبَاطِنَانِ فَنَهْرَانِ فِي الْجَنَّةِ، وَأَمَّا الظَّاهِرَانِ فَالنِّيلُ وَالْفُرَاتُ، ثُمَّ رُفِعَ لِي الْبَيْتُ الْمَعْمُورُ، فَإِذَا هُوَ يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ، ثُمَّ أُتِيتُ بِإِنَاءٍ مِنْ خَمْرٍ وَإِنَاءٍ مِنْ لَبَنٍ وَإِنَاءٍ مِنْ عَسَلٍ، فَأَخَذْتُ اللَّبَنَ فَقَالَ: هِيَ الْفِطْرَةُ الَّتِي أَنْتَ عَلَيْهَا وَأُمَّتُكَ، ثُمَّ فُرِضَتْ عَلَيَّ الصَّلَوَاتُ، خَمْسِينَ صَلَاةً كُلَّ يَوْمٍ، فَرَجَعْتُ فَمَرَرْتُ عَلَى مُوسَى، فَقَالَ: بِمَا أُمِرْتَ؟ قَالَ: أُمِرْتُ بِخَمْسِينَ صَلَاةً كُلَّ يَوْمٍ، قَالَ: إِنَّ أُمَّتَكَ لَا تَسْتَطِيعُ خَمْسِينَ صَلَاةً كُلَّ يَوْمٍ، وَإِنِّي وَاللهِ قَدْ جَرَّبْتُ النَّاسَ قَبْلَكَ وَعَالَجْتُ بَنِي إِسْرَائِيلَ أَشَدَّ الْمُعَالَجَةِ، فَارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ لِأُمَّتِكَ، فَرَجَعْتُ فَوَضَعَ عَنِّي عَشْرًا، فَرَجَعْتُ إِلَى مُوسَى، فَقَالَ مِثْلَهُ، فَرَجَعْتُ فَوَضَعَ عَنِّي عَشْرًا، فَرَجَعْتُ إِلَى مُوسَى فَقَالَ مِثْلَهُ، فَرَجَعْتُ فَوَضَعَ عَنِّي عَشْرًا، فَرَجَعْتُ إِلَى مُوسَى فَقَالَ مِثْلَهُ، فَرَجَعْتُ، فَأُمِرْتُ بِعَشْرِ صَلَوَاتٍ كُلَّ يَوْمٍ، فَرَجَعْتُ فَقَالَ مِثْلَهُ، فَرَجَعْتُ فَأُمِرْتُ بِخَمْسِ صَلَوَاتٍ كُلَّ يَوْمٍ، فَرَجَعْتُ إِلَى مُوسَى فَقَالَ: بِمَ أُمِرْتَ؟ قُلْتُ: أُمِرْتُ بِخَمْسِ صَلَوَاتٍ كُلَّ يَوْمٍ، قَالَ: إِنَّ أُمَّتَكَ لَا تَسْتَطِيعُ خَمْسَ صَلَوَاتٍ كُلَّ يَوْمٍ، وَإِنِّي قَدْ جَرَّبْتُ النَّاسَ قَبْلَكَ، وَعَالَجْتُ بَنِي إِسْرَائِيلَ أَشَدَّ الْمُعَالَجَةِ، فَارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ لِأُمَّتِكَ، قَالَ: سَأَلْتُ رَبِّي حَتَّى اسْتَحْيَيْتُ، وَلَكِنِّي أَرْضَى وَأُسَلِّمُ، قَالَ: فَلَمَّا جَاوَزْتُ نَادَى مُنَادٍ: أَمْضَيْتُ فَرِيضَتِي، وَخَفَّفْتُ عَنْ عِبَادِي، وَقَدْ تَقَدَّمَ حَدِيثُ الْإِسْرَاءِ عَنْ أَنَسٍ فِي أَوَّلِ كِتَابِ الصَّلَاةِ، وَفِي كُلِّ وَاحِدٍ مِنْهُمَا مَا لَيْسَ فِي الْآخَرِ. (خ)', 'മാലികുബ്നു സ്വഅ്സ്വഅഃ(റ): തന്നെ രാപ്രയാണം ചെയ്യപ്പെട്ട രാത്രിയെക്കുറിച്ച് വിവരിച്ചുകൊണ്ട് നിശ്ചയം നബി(സ) അനുചരരോട് ഇപ്രകാരം പറഞ്ഞു: "ഒരിക്കൽ ഞാൻ ഹതീമിൽ - അല്ലെങ്കിൽ ഹിജ്റിൽ എന്നാണ് അവിടുന്ന് പറഞ്ഞത് - കിടക്കുന്നതിനിടയിൽ ഒരാൾ എന്റെയടുത്ത് വന്നു." മാലിക്(റ) പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അദ്ദേഹം ഇതുമുതൽ ഇതുവരെ കീറി." - നിവേദകൻ പറഞ്ഞു: നെഞ്ചിന്റെ മുകൾഭാഗം മുതൽ പൊക്കിളിന്റെ താഴ്ഭാഗം വരെ എന്നാണ് ഉദ്ദേശ്യം - "എന്നിട്ട് എന്റെ ഹൃദയം പുറത്തെടുത്തു. ശേഷം ഈമാൻ നിറക്കപ്പെട്ട സ്വർണ്ണത്തിന്റെ ഒരു തളിക എന്റടുത്തേക്ക് കൊണ്ടുവരികയും എന്റെ ഹൃദയം കഴുകുകയും അതിൽ (ഈമാൻ) നിറക്കപ്പെടുകയും പൂർവ്വസ്ഥാനത്തേക്ക് മടക്കപ്പെടുകയും ചെയ്തു. അനന്തരം കോവർകഴുതയേക്കാൾ ചെറുതും കഴുതയേക്കാൾ വലുതുമായ വെളുത്ത ഒരു മൃഗത്തെ കൊണ്ടുവന്നു." നിവേദകൻ പറഞ്ഞു: അത് ബുറാഖ് ആണ്. "അതിന്റെ കണ്ണ് എത്തുന്ന അത്രയും ദൂരത്തേക്കാണത് കാലടി വെക്കുക. അങ്ങനെ എന്നെ അതിന്മേൽ കയറ്റി. അങ്ങനെ ജിബ്രീൽ(അ) എന്നെയും കൂട്ടി പോവുകയും ഒന്നാം ആകാശത്ത് എത്തുകയും ചെയ്തു. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് (മുഹമ്മദ്(സ)ക്ക്) സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറന്നു, ഞാൻ കടന്നു ചെന്നപ്പോൾ അവിടെയതാ ആദം(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് അങ്ങയുടെ പിതാവ് ആദം(അ) ആണ്. അവരോട് സലാം പറഞ്ഞാലും. അപ്പോൾ ഞാൻ അവരോട് സലാം ചൊല്ലി. ആദം(അ) സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പുത്രനും ഉൽകൃഷ്ട നബിക്കും സ്വാഗതം. ശേഷം എന്നെയുംകൊണ്ട് ജിബ്രീൽ(അ) കയറുകയും രണ്ടാം ആകാശത്ത് എത്തുകയും ചെയ്തു. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറന്നു, ഞാൻ കടന്നു ചെന്നപ്പോൾ അവിടെയതാ യഹ്യാ(അ)മും ഈസാ(അ)മും. അവർ രണ്ടുപേരും സഹോദരീ സഹോദരന്മാരുടെ സന്താനങ്ങളാണ്. ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് യഹ്യാ(അ)മും ഈസാ(അ)മും ആണ്. അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. അപ്പോൾ ഞാൻ അവരോട് സലാം ചൊല്ലി. അവർ സലാം മടക്കി, എന്നിട്ട് പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട സഹോദരനും സ്വാഗതം! അനന്തരം എന്നെയുംകൊണ്ട് ജിബ്രീൽ(അ) മൂന്നാം ആകാശത്തേക്ക് കയറി. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറക്കപ്പെട്ടു, ഞാൻ കടന്നു ചെന്നപ്പോൾ അവിടെയതാ യൂസുഫ്(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് യൂസുഫ്(അ) ആണ്, അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. ഞാൻ അവരോട് സലാം ചൊല്ലി. അവർ സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട സഹോദരനും സ്വാഗതം. ശേഷം ജിബ്രീൽ(അ) എന്നെയുംകൊണ്ട് കയറുകയും നാലാം ആകാശത്ത് എത്തുകയും ചെയ്തു. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറന്നു, ഞാൻ കടന്നു ചെന്നപ്പോൾ അവിടെയതാ ഇദ്‌രീസ്(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് ഇദ്‌രീസ്(അ) ആണ്. അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. ഞാൻ അവരോട് സലാം പറഞ്ഞു. അവർ സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട സഹോദരനും സ്വാഗതം. അനന്തരം ജിബ്രീൽ(അ) എന്നെയുംകൊണ്ട് കയറുകയും അഞ്ചാം ആകാശത്ത് എത്തുകയും ചെയ്തു. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ ഞാൻ കടന്നുചെന്നപ്പോൾ അവിടെയതാ ഹാറൂൻ നബി(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് ഹാറൂൻ നബി(അ) ആണ്. അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. ഞാൻ അവരോട് സലാം പറഞ്ഞു. അവർ സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട സഹോദരനും സ്വാഗതം. അനന്തരം ജിബ്രീൽ(അ) എന്നെയുംകൊണ്ട് കയറുകയും ആറാം ആകാശത്ത് എത്തുകയും ചെയ്തു. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറന്നു, ഞാൻ കടന്നുചെന്നപ്പോൾ അവിടെയതാ മൂസാ(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് മൂസാ(അ) ആണ്. അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. ഞാൻ അവരോട് സലാം പറഞ്ഞു. അവർ സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട സഹോദരനും സ്വാഗതം. ഞാൻ അവിടെനിന്ന് കടന്നുപോയപ്പോൾ അവർ കരഞ്ഞു. ''എന്തിനാണ് നിങ്ങൾ കരയുന്നത്'' എന്ന് ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: എന്റെ ശേഷം പ്രവാചകനായി വന്ന ഒരു ചെറുപ്പക്കാരന്റെ സമുദായത്തിൽ നിന്നും എന്റെ സമുദായത്തിലേതിനേക്കാൾ അധികമാളുകൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നു എന്നതോർത്താണ് ഞാൻ കരയുന്നത്. അനന്തരം ജിബ്രീൽ(അ) എന്നെയും കൂട്ടി ഏഴാം ആകാശത്തേക്ക് കയറി. ജിബ്രീൽ(അ) വാതിൽ തുറക്കാനാവശ്യപ്പെട്ടു. ''ആരാണിത്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: ജിബ്രീലാണ്. ''താങ്കളുടെ കൂടെയാരാണ്?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്(സ). ''അവർ പ്രവാചകനായി നിയുക്തനായിട്ടുണ്ടോ?'' എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അപ്പോൾ ഇപ്രകാരം പറയപ്പെട്ടു: ''അവർക്ക് സ്വാഗതം, വരവ് വളരെ നന്നായിരിക്കുന്നു.'' അങ്ങനെ വാതിൽ തുറന്നു, ഞാൻ കടന്നുചെന്നപ്പോൾ അവിടെയതാ ഇബ്റാഹീം(അ). ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് അങ്ങയുടെ പിതാവ് ഇബ്റാഹീം(അ) ആണ്. അങ്ങ് അവരോട് സലാം ചൊല്ലിയാലും. ഞാൻ അവരോട് സലാം പറഞ്ഞു. അവർ സലാം മടക്കി, ശേഷം പറഞ്ഞു: ഉത്തമ പ്രവാചകനും ഉൽകൃഷ്ട പുത്രനും സ്വാഗതം. പിന്നീട് എന്നെ സിദ്റതുൽ മുൻതഹായിലേക്ക് ഉയർത്തപ്പെട്ടു. അതിലെ കായ്കൾ ഹജറിലെ പാത്രങ്ങൾ പോലെയും അതിലെ ഇലകൾ ആനയുടെ ചെവി പോലെയുമുണ്ട്. ജിബ്രീൽ(അ) പറഞ്ഞു: ഇതാണ് സിദ്റതുൽ മുൻതഹാ. അവിടെ നാല് നദികളുണ്ടായിരുന്നു. പ്രത്യക്ഷമായ രണ്ട് നദികളും ആന്തരികമായ രണ്ട് നദികളും. ഞാൻ ചോദിച്ചു: ജിബ്രീലേ, ഇവ രണ്ടുമെന്താണ്? ജിബ്രീൽ(അ) പറഞ്ഞു: ആന്തരികമായി ഒഴുകുന്നവ സ്വർഗ്ഗത്തിലെ രണ്ട് നദികളാണ്. പ്രത്യക്ഷമായി ഒഴുകുന്നവ നൈൽ നദിയും യൂഫ്രട്ടീസ് നദിയുമാണ്. പിന്നീട് എന്നെ ബൈതുൽ മഅ്മൂറിലേക്ക് ഉയർത്തപ്പെട്ടു. അതിൽ ഓരോ ദിവസവും എഴുപതിനായിരം മലക്കുകൾ പ്രവേശിക്കുന്നുണ്ട്. ശേഷം മദ്യവും പാലും തേനും നിറച്ച ഓരോ പാത്രങ്ങൾ എന്റെയടുത്ത് കൊണ്ടുവരപ്പെട്ടു. ഞാൻ പാൽ എടുത്തു. ജിബ്രീൽ(അ) പറഞ്ഞു: അതാണ് താങ്കളും താങ്കളുടെ സമുദായവും നിലകൊള്ളുന്ന ശുദ്ധ പ്രകൃതം. പിന്നീട് എനിക്ക് ദിവസവും അമ്പത് നിസ്കാരം നിർബന്ധമാക്കപ്പെട്ടു. ശേഷം ഞാൻ മടങ്ങുകയും മൂസാ(അ)മിന്റെ അടുത്തുകൂടെ പോവുകയും ചെയ്തു. അപ്പോൾ മൂസാ(അ) ചോദിച്ചു: അങ്ങയോട് എന്താണ് കൽപിക്കപ്പെട്ടത്? ഞാൻ പറഞ്ഞു: ദിവസവും അമ്പത് നിസ്കാരം എന്നോട് കൽപിക്കപ്പെട്ടു. മൂസാ(അ) പറഞ്ഞു: അങ്ങയുടെ സമുദായത്തിന് ദിവസവും അമ്പത് നിസ്കാരം നിസ്കരിക്കാൻ സാധിക്കുകയില്ല. അല്ലാഹു തന്നെ സത്യം, താങ്കൾക്കു മുന്നെ ജനങ്ങളെ ഞാൻ പരീക്ഷിച്ചു നോക്കിയിട്ടുണ്ട്. ബനൂഇസ്റാഈല്യരെ ഞാൻ ശക്തമായി നിയന്ത്രിച്ചു നോക്കിയിട്ടുണ്ട്. അതിനാൽ അങ്ങ് തന്റെ നാഥന്റെയടുത്തേക്ക് മടങ്ങിച്ചെന്ന് തന്റെ സമുദായത്തിന് വേണ്ടി ലഘൂകരിച്ചു തരാൻ ആവശ്യപ്പെടുക. അങ്ങനെ ഞാൻ മടങ്ങിച്ചെല്ലുകയും പത്ത് നിസ്കാരം എനിക്ക് ഒഴിവാക്കിത്തരികയും ചെയ്തു. വീണ്ടും ഞാൻ മൂസാ(അ)മിന്റെ അടുത്തേക്ക് മടങ്ങിച്ചെന്നു. അവർ ആദ്യം പറഞ്ഞതു പോലെ അപ്പോഴും പറഞ്ഞു. ഞാൻ മടങ്ങിച്ചെല്ലുകയും പത്ത് നിസ്കാരം കൂടി എനിക്ക് ഒഴിവാക്കിത്തരികയും ചെയ്തു. വീണ്ടും ഞാൻ മൂസാ(അ)മിന്റെ അടുത്തേക്ക് മടങ്ങിച്ചെന്നു. അവർ ആദ്യം പറഞ്ഞതു പോലെത്തന്നെ പറഞ്ഞു. ഞാൻ മടങ്ങിച്ചെല്ലുകയും പത്ത് നിസ്കാരം കൂടി എനിക്ക് ഒഴിവാക്കിത്തരികയും ചെയ്തു. വീണ്ടും ഞാൻ മൂസാ(അ)മിന്റെ അടുത്തേക്ക് മടങ്ങിച്ചെന്നു. അവർ ആദ്യം പറഞ്ഞതു പോലെത്തന്നെ പറഞ്ഞു. ഞാൻ മടങ്ങിച്ചെല്ലുകയും പത്ത് നിസ്കാരംകൂടി എനിക്ക് ഒഴിവാക്കിത്തരികയും ചെയ്തു. അങ്ങനെ ഒരു ദിവസം പത്ത് നിസ്കാരം എന്നോട് കൽപിക്കപ്പെട്ടു. വീണ്ടും ഞാൻ മടങ്ങുകയും മൂസാ(അ) ആദ്യത്തേതു പോലെത്തന്നെ പറയുകയും ചെയ്തു. അങ്ങനെ ഞാൻ മടങ്ങുകയും ദിവസവും അഞ്ച് നിസ്കാരം എന്നോട് കൽപിക്കപ്പെടുകയും ചെയ്തു. ശേഷം ഞാൻ മൂസാ(അ)മിന്റെ അടുത്തേക്ക് മടങ്ങി. അവർ ചോദിച്ചു: എന്താണ് നിങ്ങളോട് കൽപിക്കപ്പെട്ടത്? ഞാൻ പറഞ്ഞു: ദിവസവും അഞ്ചു പ്രാവശ്യം നിസ്കരിക്കണമെന്ന് ഞാൻ കൽപിക്കപ്പെട്ടു. മൂസാ(അ) പറഞ്ഞു: ദിവസവും അഞ്ചു പ്രാവശ്യം നമസ്കരിക്കാൻ അങ്ങയുടെ സമുദായത്തിന് സാധിക്കുകയില്ല. നിശ്ചയം താങ്കൾക്കു മുമ്പ് ഞാൻ ജനങ്ങളെ പരീക്ഷിച്ചു നോക്കിയിട്ടുണ്ട്. ബനൂഇസ്റീഈല്യരെ ഞാൻ ശക്തമായി നിയന്ത്രിച്ച് നോക്കിയിട്ടുണ്ട്. അതിനാൽ അങ്ങ് തന്റെ നാഥന്റെ അടുത്തേക്ക് മടങ്ങിച്ചെന്ന് തന്റെ സമുദായത്തിന് വേണ്ടി ലഘൂകരിച്ച് തരാൻ ആവശ്യപ്പെടുക. ഞാൻ പറഞ്ഞു: ഞാൻ എന്റെ നാഥനോട് പലവട്ടം ചോദിച്ചു, ഇപ്പോൾ എനിക്ക് നാണം തോന്നുന്നു, അതിനാൽ ഞാനിത് തൃപ്തിപ്പെടുകയും സമ്മതിക്കുകയും ചെയ്യുന്നു." നബി(സ) പറഞ്ഞു: "ഞാൻ അവിടം വിട്ടുകടന്നപ്പോൾ ഒരാൾ എന്നോട് വിളിച്ചു പറഞ്ഞു: എന്റെ ചുമതല ഞാനിതാ നടപ്പിൽ വരുത്തിയിരിക്കുന്നു. എന്റെ അടിമകൾക്കിതാ ഞാൻ ലഘൂകരിച്ചു നൽകിയിരിക്കുന്നു." അനസ്(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യപ്പെട്ട ഇസ്റാഇന്റെ ഹദീസ് നമസ്കാരത്തിന്റെ അധ്യായത്തിന്റെ ആരംഭത്തിൽ വന്നിട്ടുണ്ട്. ഇവയിൽ ഓരോന്നിലും മറ്റേതിലില്ലാത്ത ചില ആശയങ്ങളുണ്ട്. (ബു)', 'مَالِكِ بْنِ صَعْصَعَةَ', 'മാലികുബ്നു സ്വഅ്സ്വഅഃ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 323, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عَبَّاسِ رَضِيَ اللَّهُ عَنْهُمَا فِي قَوْله تَعَالَى: {وَمَا جَعَلْنَا الرُّؤْيَا التي أَرَيْنَاكَ إلا فتْنَة للنَّاسِ} قَالَ: هِيَ رُؤْيَا عَيْنٍ أُرِيَهَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ أُسْرِيَ به إِلَى بَيْتِ الْمَقْدسِ، قَالَ: {وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْآنِ} قَالَ: هِيَ شَجَرَةُ الزَّقُّومِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നാം അങ്ങേക്ക് കാണിച്ചു തന്ന സ്വപ്നം ജനങ്ങൾക്ക് ഒരു പരീക്ഷണ വിഷയമാക്കി വെക്കുക മാത്രമാണ് നാം ചെയ്തിരിക്കുന്നത്'' എന്ന ഖുർആൻ വാക്യത്തെക്കുറിച്ച് അദ്ദേഹം പറഞ്ഞു: ''റസൂൽ(സ)യെ ബൈതുൽമുഖദ്ദസിലേക്ക് രാപ്രയാണം ചെയ്യിക്കപ്പെട്ട രാത്രിയിൽ അവിടുന്ന് സ്വന്തം കണ്ണു കൊണ്ടു കണ്ട കാഴ്ചതന്നെയാണത്.'' ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഖുർആനിൽ (പരാമർശിക്കപ്പെട്ട) ശപിക്കപ്പെട്ട വൃക്ഷം സക്കൂം വൃക്ഷമാണ്. (ബു)', 'ابْنِ عَبَّاسِ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَائشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا بِنْتُ سِتٍّ سِنِينَ، فَقَدِمْنَا الْمَدِينَةَ فَنَزَلْنَا فِي بَنِي الْحَارِث بْنِ خَزْرَجِ، فَوُعكْتُ، فَتَمَرَّقَ شَعَرِي فَوَفَى جُمَيْمَةً، فَأَتَتْنِي أُمِّي أُمُّ رُومَانَ، وَإِنِّي لَفِي أُرْجُوحَةٍ وَمَعِي صَوَاحِبُ لِي، فَصَرَخَتْ بِي، فَأَتَيْتُهَا لَا أَدْرِي مَا تُرِيدُ بِي، فَأَخَذَتْ بِيَدِي حَتَّى أَوْقَفَتْنِي عَلَى بَابِ الدَّارِ، وَإِنِّي لَأُنْهِجُ حَتَّى سَكَنَ بَعْضُ نَفَسِي، ثُمَّ أَخَذَتْ شَيْئًا مِنْ مَاءٍ فَمَسَحَتْ بِهِ وَجْهِي وَرَأْسِي، ثُمَّ أَدْخَلَتْنِي الدَّارَ، فَإِذَا نِسْوَةٌ مِنَ الْأَنْصَارِ فِي الْبَيْتِ، فَقُلْنَ: عَلَى الْخَيْرِ وَالْبَرَكَةِ وَعَلَى خَيْرِ طَائِرٍ، فَأَسْلَمَتْنِي إِلَيْهِنَّ فَأَصْلَحْنَ مِنْ شَأْنِي، فَلَمْ يَرُعْنِي إِلَّا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضُحًى، فَأَسْلَمْنَنِي إِلَيْهِ، وَأَنَا يَوْمَئِذٍ بِنْتُ تِسْعِ سِنِينَ. (خ)', 'ആഇശ(റ): എനിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് നബി(സ) എന്നെ വിവാഹം ചെയ്തത്. പിന്നീട് ഞങ്ങൾ മദീനയിലേക്ക് വരികയും ബനുൽ ഹാരിസുബ്നു ഖസ്റജ് ഗോത്രത്തിൽ താമസിക്കുകയും ചെയ്തു. അവിടന്ന് എനിക്ക് പനി പിടിക്കുകയും എന്റെ മുടിയെല്ലാം കൊഴിഞ്ഞുപോവുകയും ചെയ്തു. ശേഷം അത് തിങ്ങി വളർന്നു വന്നു. അങ്ങനെയിരിക്കെ ഒരിക്കൽ എന്റെ ഉമ്മ ഉമ്മുറൂമാൻ(റ) എന്റെയടുത്ത് വന്നു. ഞാൻ എന്റെ കൂട്ടുകാരികളുമൊത്ത് ഊഞ്ഞാലിൽ കളിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. മാതാവ് എന്നെ ഉച്ചത്തിൽ വിളിക്കുകയും ഞാൻ അവരുടെ അടുക്കൽ ചെല്ലുകയും ചെയ്തു. അവർ എന്നെക്കൊണ്ട് എന്താണ് ഉദ്ദേശിക്കുന്നതെന്ന് എനിക്ക് അറിയില്ലായിരുന്നു. അവർ എന്റെ കൈപിടിച്ച് വീടിന്റെ വാതിൽക്കൽ കൊണ്ടുപോയി നിർത്തി. ഞാൻ കിതക്കുന്നുണ്ടായിരുന്നു. കിതപ്പ് മാറിയപ്പോൾ അവർ അൽപം വെള്ളമെടുത്ത് എന്റെ മുഖവും തലയും തുടച്ചു. ശേഷം എന്നെ വീട്ടിനുള്ളിലേക്ക് കൊണ്ടുപോയി. വീട്ടിനുള്ളിൽ കുറേ അൻസാരീ സ്ത്രീകൾ ഒരുമിച്ചുകൂടിയിരുന്നു. അവർ പറഞ്ഞു: ക്ഷേമവും സൗഭാഗ്യവും ശുഭലക്ഷണവും നേർന്നു കൊള്ളുന്നു (കടന്നുവരിക). എന്റെ മാതാവ് എന്നെ അവർക്ക് ഏൽപിച്ചു കൊടുത്തു. അവർ എന്നെ ഒരുക്കിച്ചമയിപ്പിച്ചു. ശേഷം ളുഹാ സമയത്ത് റസൂൽ(സ) വന്നപ്പോൾ എനിക്ക് ഭയം തോന്നി. ആ സ്ത്രീകൾ എന്നെ റസൂൽ(സ)ക്ക് ഏൽപ്പിച്ചുകൊടുത്തു. അന്ന് എനിക്ക് ഒമ്പത് വയസ്സായിരുന്നു. (ബു)', 'عَائشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 327, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "أُرِيتُكِ فِي الْمَنَامِ مَرَّتَيْنِ، أَرَى أَنَّكِ فِي سَرَقَةٍ مِنْ حَرِيرٍ، وَيَقُولُ: هَذِهِ امْرَأَتُكَ، فَأَكْشِفُ عَنْهَا فَإِذَا هِيَ أَنْتِ، فَأَقُولُ: إِنْ يَكُ هَذَا مِنْ عِنْدِ اللَّهِ يُمْضِهِ". (خ)', 'ആഇശ(റ): റസൂൽ(സ) മഹതിയോട് ഇപ്രകാരം പറഞ്ഞു: "രണ്ട് പ്രാവശ്യം നിന്നെ എനിക്ക് സ്വപ്നത്തിൽ കാണിക്കപ്പെട്ടു. ഒരു പട്ടിന്റെ കഷ്ണത്തിലായിട്ടായിരുന്നു നിശ്ചയം ഞാൻ നിന്നെ കണ്ടത്. ''ഇത് അങ്ങയുടെ പത്നിയാണ്'' എന്ന് എന്നോട് പറയുന്നണ്ടായിരുന്നു. ഞാൻ മറനീക്കി നോക്കുമ്പോൾ അത് നീയായിരുന്നു. അപ്പോൾ ഞാൻ ഇപ്രകാരം പറഞ്ഞു: ഇത് അല്ലാഹുവിൽ നിന്നുള്ളതാണെങ്കിൽ അല്ലാഹു അത് നടപ്പാക്കുക തന്നെ ചെയ്യും." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 328, 328, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمْ أَعْقِلْ أَبَوَيَّ قَطُّ إِلَّا وَهُمَا يَدِينَانِ الدِّينَ، وَلَمْ يَمُرَّ عَلَيْنَا يَوْمٌ إِلَّا يَأْتِينَا فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَرَفَيِ النَّهَارِ بُكْرَةً وَعَشِيَّةً، فَلَمَّا ابْتُلِيَ الْمُسْلِمُونَ خَرَجَ أَبُو بَكْرٍ مُهَاجِرًا نَحْوَ أَرْضِ الْحَبَشَةِ، حَتَّى إِذَا بَلَغَ بَرْكَ الْغِمَادِ لَقِيَهُ ابْنُ الدَّغِنَةِ، وَهُوَ سَيِّدُ الْقَارَةِ، فَقَالَ: أَيْنَ تُرِيدُ يَا أَبَا بَكْرٍ؟ فَقَالَ أَبُو بَكْرٍ: أَخْرَجَنِي قَوْمِي فَأُرِيدُ أَنْ أَسِيحَ فِي الْأَرْضِ وَأَعْبُدَ رَبِّي، فَقَالَ ابْنُ الدَّغِنَةِ: فَإِنَّ مِثْلَكَ يَا أَبَا بَكْرٍ لَا يَخْرُجُ وَلَا يُخْرَجُ، إِنَّكَ تَكْسِبُ الْمَعْدُومَ، وَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ، فَأَنَا لَكَ جَارٌ، ارْجِعْ وَاعْبُدْ رَبَّكَ بِبَلَدِكَ. فَرَجَعَ وَارْتَحَلَ مَعَهُ ابْنُ الدَّغِنَةِ، فَطَافَ ابْنُ الدَّغِنَةِ عَشِيَّةً فِي أَشْرَافِ قُرَيْشٍ، فَقَالَ لَهُمْ: إِنَّ أَبَا بَكْرٍ لَا يَخْرُجُ مِثْلُهُ وَلَا يُخْرَجُ، أَتُخْرِجُونَ رَجُلًا يَكْسِبُ الْمَعْدُومَ، وَيَصِلُ الرَّحِمَ، وَيَحْمِلُ الْكَلَّ، وَيَقْرِي الضَّيْفَ، وَيُعِينُ عَلَى نَوَائِبِ الْحَقِّ، فَلَمْ تُكَذِّبْ قُرَيْشٌ بِجِوَارِ ابْنِ الدَّغِنَةِ، وَقَالُوا لِابْنِ الدَّغِنَةِ: مُرْ أَبَا بَكْرٍ فَلْيَعْبُدْ رَبَّهُ فِي دَارِهِ، فَلْيُصَلِّ فِيهَا وَلْيَقْرَأْ مَا شَاءَ، وَلَا يُؤْذِينَا بِذَلِكَ وَلَا يَسْتَعْلِنْ بِهِ، فَإِنَّا نَخْشَى أَنْ يَفْتِنَ نِسَاءَنَا وَأَبْنَاءَنَا، فَقَالَ ذَلِكَ ابْنُ الدَّغِنَةِ لِأَبِي بَكْرٍ، فَلَبِثَ أَبُو بَكْرٍ بِذَلِكَ يَعْبُدُ رَبَّهُ فِي دَارِهِ، وَلَا يَسْتَعْلِنُ بِصَلَاتِهِ وَلَا يَقْرَأُ فِي غَيْرِ دَارِهِ، ثُمَّ بَدَا لِأَبِي بَكْرٍ، فَابْتَنَى مَسْجِدًا بِفِنَاءِ دَارِهِ، وَكَانَ يُصَلِّي فِيهِ وَيَقْرَأُ الْقُرْآنَ، فَيَنْقَذِفُ عَلَيْهِ نِسَاءُ الْمُشْرِكِينَ وَأَبْنَاؤُهُمْ، وَهُمْ يَعْجَبُونَ مِنْهُ وَيَنْظُرُونَ إِلَيْهِ، وَكَانَ أَبُو بَكْرٍ رَجُلًا بَكَّاءً، لَا يَمْلِكُ عَيْنَيْهِ إِذَا قَرَأَ الْقُرْآنَ، وَأَفْزَعَ ذَلِكَ أَشْرَافَ قُرَيْشٍ مِنَ الْمُشْرِكِينَ، فَأَرْسَلُوا إِلَى ابْنِ الدَّغِنَةِ فَقَدِمَ عَلَيْهِمْ، فَقَالُوا: إِنَّا كُنَّا أَجَرْنَا أَبَا بَكْرٍ بِجِوَارِكَ، عَلَى أَنْ يَعْبُدَ رَبَّهُ فِي دَارِهِ، فَقَدْ جَاوَزَ ذَلِكَ فَابْتَنَى مَسْجِدًا بِفِنَاءِ دَارِهِ، فَأَعْلَنَ بِالصَّلَاةِ وَالْقِرَاءَةِ فِيهِ، وَإِنَّا قَدْ خَشِينَا أَنْ يَفْتِنَ نِسَاءَنَا وَأَبْنَاءَنَا، فَانْهَهُ، فَإِنْ أَحَبَّ أَنْ يَقْتَصِرَ عَلَى أَنْ يَعْبُدَ رَبَّهُ فِي دَارِهِ فَعَلَ، وَإِنْ أَبَى إِلَّا أَنْ يُعْلِنَ بِذَلِكَ فَسَلْهُ أَنْ يَرُدَّ إِلَيْكَ ذِمَّتَكَ، فَإِنَّا قَدْ كَرِهْنَا أَنْ نُخْفِرَكَ، وَلَسْنَا مُقِرِّينَ لِأَبِي بَكْرٍ الِاسْتِعْلَانَ، قَالَتْ عَائِشَةُ: فَأَتَى ابْنُ الدَّغِنَةِ إِلَى أَبِي بَكْرٍ فَقَالَ: قَدْ عَلِمْتَ الَّذِي عَاقَدْتُ لَكَ عَلَيْهِ، فَإِمَّا أَنْ تَقْتَصِرَ عَلَى ذَلِكَ، وَإِمَّا أَنْ تَرْجِعَ إِلَيَّ ذِمَّتِي، فَإِنِّي لَا أُحِبُّ أَنْ تَسْمَعَ الْعَرَبُ أَنِّي أُخْفِرْتُ فِي رَجُلٍ عَقَدْتُ لَهُ، فَقَالَ أَبُو بَكْرٍ: فَإِنِّي أَرُدُّ إِلَيْكَ جِوَارَكَ، وَأَرْضَى بِجِوَارِ اللَّهِ عَزَّ وَجَلَّ. وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ بِمَكَّةَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْمُسْلِمِينَ: "إِنِّي أُرِيتُ دَارَ هِجْرَتِكُمْ ذَاتَ نَخْلٍ بَيْنَ لَابَتَيْنِ" - وَهُمَا الْحَرَّتَانِ - فَهَاجَرَ مَنْ هَاجَرَ قِبَلَ الْمَدِينَةِ، وَرَجَعَ عَامَّةُ مَنْ كَانَ هَاجَرَ بِأَرْضِ الْحَبَشَةِ إِلَى الْمَدِينَةِ، وَتَجَهَّزَ أَبُو بَكْرٍ قِبَلَ الْمَدِينَةِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَى رِسْلِكَ، فَإِنِّي أَرْجُو أَنْ يُؤْذَنَ لِي". فَقَالَ أَبُو بَكْرٍ: وَهَلْ تَرْجُو ذَلِكَ بِأَبِي أَنْتَ؟ قَالَ: "نَعَمْ". فَحَبَسَ أَبُو بَكْرٍ نَفْسَهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَصْحَبَهُ، وَعَلَفَ رَاحِلَتَيْنِ كَانَتَا عِنْدَهُ وَرَقَ السَّمُرِ - وَهُوَ الْخَبَطُ - أَرْبَعَةَ أَشْهُرٍ، قَالَتْ عَائِشَةُ: فَبَيْنَمَا نَحْنُ يَوْمًا جُلُوسٌ فِي بَيْتِ أَبِي بَكْرٍ فِي نَحْرِ الظَّهِيرَةِ، قَالَ قَائِلٌ لِأَبِي بَكْرٍ: هَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَقَنِّعًا فِي سَاعَةٍ لَمْ يَكُنْ يَأْتِينَا فِيهَا، فَقَالَ أَبُو بَكْرٍ: فِدَاءً لَهُ أَبِي وَأُمِّي، وَاللَّهِ مَا جَاءَ بِهِ فِي هَذِهِ السَّاعَةِ إِلَّا أَمْرٌ، قَالَتْ عَائِشَةُ: فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَأْذَنَ، فَأُذِنَ لَهُ فَدَخَلَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ: "أَخْرِجْ مَنْ عِنْدَكَ". فَقَالَ أَبُو بَكْرٍ: إِنَّمَا هُمْ أَهْلُكَ بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: "فَإِنِّي قَدْ أُذِنَ لِي فِي الْخُرُوجِ". فَقَالَ أَبُو بَكْرٍ: الصَّحْبَةَ بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ أَبُو بَكْرٍ: فَخُذْ بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ إِحْدَى رَاحِلَتَيَّ هَاتَيْنِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِالثَّمَنِ". قَالَتْ عَائِشَةُ: فَجَهَّزْنَاهُمَا أَحَثَّ الْجِهَازِ، وَصَنَعْنَا لَهُمَا سُفْرَةً فِي جِرَابٍ، فَقَطَعَتْ أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ قِطْعَةً مِنْ نِطَاقِهَا فَرَبَطَتْ بِهِ عَلَى فَمِ الْجِرَابِ، فَبِذَلِكَ سُمِّيَتْ ذَاتَ النِّطَاقَيْنِ، قَالَتْ: ثُمَّ لَحِقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ بِغَارٍ فِي جَبَلِ ثَوْرٍ، فَكَمَنَا فِيهِ ثَلَاثَ لَيَالٍ، يَبِيتُ عِنْدَهُمَا عَبْدُاللَّهِ بْنُ أَبِي بَكْرٍ، وَهُوَ غُلَامٌ شَابٌّ ثَقِفٌ لَقِنٌ، فَيُدْلِجُ مِنْ عِنْدِهِمَا بِسَحَرٍ، فَيُصْبِحُ مَعَ قُرَيْشٍ بِمَكَّةَ كَبَائِتٍ، فَلَا يَسْمَعُ أَمْرًا يُكْتَادَانِ بِهِ إِلَّا وَعَاهُ، حَتَّى يَأْتِيَهُمَا بِخَبَرِ ذَلِكَ حِينَ يَخْتَلِطُ الظَّلَامُ، وَيَرْعَى عَلَيْهِمَا عَامِرُ بْنُ فُهَيْرَةَ مَوْلَى أَبِي بَكْرٍ مِنْحَةً مِنْ غَنَمٍ، فَيُرِيحُهَا عَلَيْهِمَا حِينَ تَذْهَبُ سَاعَةٌ مِنَ الْعِشَاءِ، فَيَبِيتَانِ فِي رِسْلٍ، وَهُوَ لَبَنُ مِنْحَتِهِمَا وَرَضِيفِهِمَا، حَتَّى يَنْعِقَ بِهَا عَامِرُ بْنُ فُهَيْرَةَ بِغَلَسٍ، يَفْعَلُ ذَلِكَ فِي كُلِّ لَيْلَةٍ مِنْ تِلْكَ اللَّيَالِي الثَّلَاثِ، وَاسْتَأْجَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ رَجُلًا مِنْ بَنِي الدِّيلِ، وَهُوَ مِنْ بَنِي عَبْدِ بْنِ عَدِيٍّ، هَادِيًا خِرِّيتًا، وَالْخِرِّيتُ الْمَاهِرُ بِالْهِدَايَةِ، قَدْ غَمَسَ حِلْفًا فِي آلِ الْعَاصِ بْنِ وَائِلٍ السَّهْمِيِّ، وَهُوَ عَلَى دِينِ كُفَّارِ قُرَيْشٍ، فَأَمِنَاهُ فَدَفَعَا إِلَيْهِ رَاحِلَتَيْهِمَا، وَوَاعَدَاهُ غَارَ ثَوْرٍ بَعْدَ ثَلَاثِ لَيَالٍ، بِرَاحِلَتَيْهِمَا صُبْحَ ثَلَاثٍ، وَانْطَلَقَ مَعَهُمَا عَامِرُ بْنُ فُهَيْرَةَ وَالدَّلِيلُ، فَأَخَذَ بِهِمْ طَرِيقَ السَّوَاحِلِ، قَالَ سُرَاقَةُ بْنُ جُعْشُمٍ: جَاءَنَا رُسُلُ كُفَّارِ قُرَيْشٍ، يَجْعَلُونَ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ دِيَةَ كُلِّ وَاحِدٍ مِنْهُمَا، لِمَنْ قَتَلَهُ أَوْ أَسَرَهُ، فَبَيْنَمَا أَنَا جَالِسٌ فِي مَجْلِسٍ مِنْ مَجَالِسِ قَوْمِي بَنِي مُدْلِجٍ، إِذْ أَقْبَلَ رَجُلٌ مِنْهُمْ حَتَّى قَامَ عَلَيْنَا، وَنَحْنُ جُلُوسٌ، فَقَالَ: يَا سُرَاقَةُ، إِنِّي قَدْ رَأَيْتُ آنِفًا أَسْوِدَةً بِالسَّاحِلِ، أُرَاهَا مُحَمَّدًا وَأَصْحَابَهُ، قَالَ سُرَاقَةُ: فَعَرَفْتُ أَنَّهُمْ هُمْ، فَقُلْتُ لَهُ: إِنَّهُمْ لَيْسُوا بِهِمْ، وَلَكِنَّكَ رَأَيْتَ فُلَانًا وَفُلَانًا، انْطَلَقُوا بِأَعْيُنِنَا، ثُمَّ لَبِثْتُ فِي المَجْلِسِ سَاعَةً، ثُمَّ قُمْتُ فَدَخَلْتُ، فَأَمَرْتُ جَارِيَتِي أَنْ تُخْرِجَ بِفَرَسِي، وَهِيَ مِنْ وَرَاءِ أَكَمَةٍ فَتَحْبِسَهَا عَلَيَّ، وَأَخَذْتُ رُمْحِي فَخَرَجْتُ بِهِ مِنْ ظَهْرِ الْبَيْتِ، فَخَطَطْتُ بِزُجِّهِ الْأَرْضَ وَخَفَضْتُ عَالِيَهُ، حَتَّى أَتَيْتُ فَرَسِي، فَرَكِبْتُهَا فَرَفَعْتُهَا تُقَرِّبُ بِي حَتَّى دَنَوْتُ مِنْهُمْ، فَعَثَرَتْ بِي فَرَسِي فَخَرَرْتُ عَنْهَا، فَقُمْتُ فَأَهْوَيْتُ يَدِي إِلَى كِنَانَتِي، فَاسْتَخْرَجْتُ مِنْهَا الْأَزْلَامَ فَاسْتَقْسَمْتُ بِهَا، أَضُرُّهُمْ أَمْ لَا، فَخَرَجَ الَّذِي أَكْرَهُ، فَرَكِبْتُ فَرَسِي وَعَصَيْتُ الْأَزْلَامَ تُقَرِّبُ بِي، حَتَّى إِذَا سَمِعْتُ قِرَاءَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ لَا يَلْتَفِتُ، وَأَبُو بَكْرٍ يُكْثِرُ الْاِلْتِفَاتَ، سَاخَتْ يَدَا فَرَسِي فِي الْأَرْضِ حَتَّى بَلَغَتَا الرُّكْبَتَيْنِ، فَخَرَرْتُ عَنْهَا ثُمَّ زَجَرْتُهَا، فَنَهَضَتْ، فَلَمْ تَكَدْ تُخْرِجُ يَدَيْهَا، فَلَمَّا اسْتَوَتْ قَائِمَةً إِذَا لِأَثَرِ يَدَيْهَا عُثَانٌ سَاطِعٌ فِي السَّمَاءِ مِثْلُ الدُّخَانِ، فَاسْتَقْسَمْتُ بِالْأَزْلَامِ، فَخَرَجَ الَّذِي أَكْرَهُ، فَنَادَيْتُهُمْ بِالْأَمَانِ، فَوَقَفُوا فَرَكِبْتُ فَرَسِي حَتَّى جِئْتُهُمْ، وَوَقَعَ فِي نَفْسِي حِينَ لَقِيتُ مَا لَقِيتُ مِنَ الْحَبْسِ عَنْهُمْ أَنْ سَيَظْهَرُ أَمْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ لَهُ: إِنَّ قَوْمَكَ قَدْ جَعَلُوا فِيكَ الدِّيَةَ، وَأَخْبَرْتُهُمْ أَخْبَارَ مَا يُرِيدُ النَّاسُ بِهِمْ، وَعَرَضْتُ عَلَيْهِمُ الزَّادَ وَالْمَتَاعَ، فَلَمْ يَرْزَآنِي وَلَمْ يَسْأَلَانِي إِلَّا أَنْ قَالَ: "أَخْفِ عَنَّا". فَسَأَلْتُهُ أَنْ يَكْتُبَ لِي كِتَابَ أَمْنٍ، فَأَمَرَ عَامِرَ بْنَ فُهَيْرَةَ فَكَتَبَ فِي رُقْعَةٍ مِنْ أَدِيمٍ، ثُمَّ مَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَقِيَ الزُّبَيْرَ فِي رَكْبٍ مِنَ الْمُسْلِمِينَ كَانُوا تُجَّارًا قَافِلِينَ مِنَ الشَّامِ، فَكَسَا الزُّبَيْرُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ ثِيَابَ بَيَاضٍ، وَسَمِعَ الْمُسْلِمُونَ بِالْمَدِينَةِ مَخْرَجَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ، فَكَانُوا يَغْدُونَ كُلَّ غَدَاةٍ إِلَى الْحَرَّةِ، فَيَنْتَظِرُونَهُ حَتَّى يَرُدَّهُمْ حَرُّ الظَّهِيرَةِ، فَانْقَلَبُوا يَوْمًا بَعْدَ مَا أَطَالُوا انْتِظَارَهُمْ، فَلَمَّا أَوَوْا إِلَى بُيُوتِهِمْ أَوْفَى رَجُلٌ مِنْ يَهُودَ عَلَى أُطُمٍ مِنْ أُطَامِهِمْ لِأَمْرٍ يَنْظُرُ إِلَيْهِ، فَبَصُرَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ مُبَيَّضِينَ يَزُولُ بِهِمُ السَّرَابُ، فَلَمْ يَمْلِكِ الْيَهُودِيُّ أَنْ قَالَ بِأَعْلَى صَوْتِهِ: يَا مَعْشَرَ الْعَرَبِ، هَذَا جَدُّكُمُ الَّذِي تَنْتَظِرُونَ، فَثَارَ الْمُسْلِمُونَ إِلَى السِّلَاحِ، فَتَلَقَّوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِظَهْرِ الْحَرَّةِ، فَعَدَلَ بِهِمْ ذَاتَ الْيَمِينِ حَتَّى نَزَلَ بِهِمْ فِي بَنِي عَمْرِو بْنِ عَوْفٍ، وَذَلِكَ يَوْمَ الِاثْنَيْنِ مِنْ شَهْرِ رَبِيعِ الْأَوَّلِ، فَقَامَ أَبُو بَكْرٍ لِلنَّاسِ وَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامِتًا، فَطَفِقَ مَنْ جَاءَ مِنَ الْأَنْصَارِ مِمَّنْ لَمْ يَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحَيِّي أَبَا بَكْرٍ، حَتَّى أَصَابَتِ الشَّمْسُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَقْبَلَ أَبُو بَكْرٍ حَتَّى ظَلَّلَ عَلَيْهِ بِرِدَائِهِ، فَعَرَفَ النَّاسُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ، فَلَبِثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَنِي عَمْرِو بْنِ عَوْفٍ بِضْعَ عَشْرَةَ لَيْلَةً، وَأُسِّسَ الْمَسْجِدُ الَّذِي أُسِّسَ عَلَى التَّقْوَى، وَصَلَّى فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ رَكِبَ رَاحِلَتَهُ فَسَارَ يَمْشِي مَعَهُ النَّاسُ، حَتَّى بَرَكَتْ عِنْدَ مَسْجِدِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ، وَهُوَ يُصَلِّي فِيهِ يَوْمَئِذٍ رِجَالٌ مِنَ الْمُسْلِمِينَ، وَكَانَ مِرْبَدًا لِلتَّمْرِ لِسُهَيْلٍ وَسَهْلٍ، غُلَامَيْنِ يَتِيمَيْنِ فِي حِجْرِ أَسْعَدَ بْنِ زُرَارَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ بَرَكَتْ بِهِ رَاحِلَتُهُ: "هَذَا إِنْ شَاءَ اللَّهُ الْمَنْزِلُ، ثُمَّ دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْغُلَامَيْنِ، فَسَاوَمَهُمَا بِالْمِرْبَدِ لِيَتَّخِذَهُ مَسْجِدًا، فَقَالَا: بَلْ نَهَبُهُ لَكَ يَا رَسُولَ اللَّهِ، فَأَبَى رَسُولُ اللَّهِ أَنْ يَقْبَلُهُ مِنْهُمَا هِبَةً، حَتَّى ابْتَاعَهُ مِنْهُمَا، ثُمَّ بَنَاهُ مَسْجِدًا، وَطَفِقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْقُلُ مَعَهُمُ اللَّبِنَ فِي بُنْيَانِهِ، وَيَقُولُ وَهُوَ يَنْقُلُ اللَّبِنَ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَسْمَاءَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا حَمَلَتْ بِعَبْدِاللهِ بْنِ الزُّبَيْرِ، قَالَتْ: فَخَرَجْتُ وَأَنَا مُتِمٌّ، فَأَتَيْتُ الْمَدِينَةَ، فَنَزَلْتُ بِقُبَاءَ فَوَلَدْتُهُ بِهَا، ثُمَّ أَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْتُهُ فِي حَجْرِهِ، ثُمَّ دَعَا بِتَمْرَةٍ فَمَضَغَهَا، ثُمَّ تَفَلَ فِي فِيهِ، فَكَانَ أَوَّلَ شَيْءٍ دَخَلَ جَوْفَهُ رِيقُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ حَنَّكَهُ بِتَمْرَةٍ، ثُمَّ دَعَا لَهُ وَبَرَّكَ عَلَيْهِ، وَكَانَ أَوَّلَ مَوْلُودٍ وُلِدَ فِي الْإِسْلَامِ. (خ)', 'അസ്മാഅ്(റ): മഹതി അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)വിനെ ഗർഭം ചുമന്നു. മഹതി പറയുന്നു: അങ്ങനെ പൂർണ്ണ ഗർഭിണിയായിരിക്കെയാണ് ഞാൻ (മദീനയിലേക്ക്) പോകുന്നത്. ഞാൻ മദീനയിലെത്തുകയും ഖുബാഅ് എന്ന സ്ഥലത്ത് ഇറങ്ങുകയും ചെയ്തു. അവിടെവെച്ച് ഞാൻ അബ്ദുല്ല(റ)വിനെ പ്രസവിച്ചു. ശേഷം കുട്ടിയുമായി ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെല്ലുകയും കുട്ടിയെ അവിടുത്തെ മടിയിൽ വെച്ചു കൊടുക്കുകയും ചെയ്തു. അവിടുന്ന് ഒരു കാരക്ക കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും അത് ചവക്കുകയും കുട്ടിയുടെ വായിലേക്ക് തുപ്പിക്കൊടുക്കുകയും ചെയ്തു. അബ്ദുല്ല(റ)വിന്റെ വയറ്റിൽ ആദ്യമായി ചെന്നത് റസൂൽ(സ)യുടെ തുപ്പുനീരായിരുന്നു. ശേഷം അവിടുന്ന് ഒരു കാരക്ക കൊണ്ട് കുട്ടിക്ക് മധുരം നൽകുകയും അവന് അനുഗ്രഹത്തിനായി പ്രാർത്ഥിക്കുകയും ചെയ്തു. അദ്ദേഹമായിരുന്നു ഇസ്ലാമിൽ (ഹിജ്റക്കു ശേഷം) ജനിച്ച ആദ്യ ശിശു. (ബു)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 334, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ آمَنَ بِي عَشَرَةٌ مِنَ الْيَهُودِ لَآمَنَ بِيَ الْيَهُودُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ജൂതന്മാരിൽ പത്തുപേർ എന്നിൽ വിശ്വസിക്കുന്ന പക്ഷം ജൂതന്മാർ മുഴുവൻ എന്നിൽ വിശ്വസിക്കുമായിരുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مَرْبُوعًا، بَعِيدَ مَا بَيْنَ الْمَنْكِبَيْنِ، عَظِيمَ الْجُمَّةِ إِلَى شَحْمَةِ أُذُنَيْهِ، عَلَيْهِ حُلَّةٌ حَمْرَاءُ، مَا رَأَيْتُ شَيْئًا قَطُّ أَحْسَنَ مِنْهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق)', 'ബറാഅ്(റ): റസൂൽ(സ) മിതമായ പൊക്കമുള്ളവരായിരുന്നു. അവിടുത്തെ രണ്ട് തോളുകൾക്കുമിടയിൽ വിശാലതയുണ്ടായിരുന്നു. ചെവിക്കുന്നിവരെ തലമുടി ചാഞ്ഞുകിടന്നിരുന്നു. റസൂൽ(സ) ഒരു ചുവന്ന മേൽവസ്ത്രമാണ് ധരിച്ചിരുന്നത്. റസൂൽ(സ)യേക്കാൾ സുന്ദരമായ ഒന്നും ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي الطُّفَيْلِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا عَلَى وَجْهِ الْأَرْضِ رَجُلٌ رَآهُ غَيْرِي، قَالَ: فَقُلْتُ [لَهُ]: فَكَيْفَ رَأَيْتَهُ؟ قَالَ: كَانَ أَبْيَضَ مَلِيحًا مُقَصَّدًا. قَالَ مُسْلِمٌ: مَاتَ أَبُو الطُّفَيْلِ سَنَةَ مِائَةٍ، وَكَانَ آخِرَ مَنْ مَاتَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബുത്വുഫൈൽ(റ): റസൂൽ(സ)യെ ഞാൻ കണ്ടു. ഞാനല്ലാതെ റസൂൽ(സ)യെ കണ്ട ഒരാളും ഇന്ന് ഭൂമുഖത്തില്ല. നിവേദകൻ (ജരീർ) പറയുന്നു: ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: താങ്കൾ ഏതു നിലയിലാണ് നബി(സ)യെ കണ്ടത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) സുന്ദരനും വെളുപ്പ് നിറമുള്ളവരും മിതമായ വലിപ്പമുള്ളവരുമായിരുന്നു. മുസ്ലിം നിവേദനം ചെയ്യുന്നു: നൂറാം വയസ്സിൽ അബൂത്വുഫൈൽ(റ) വഫാതായി. റസൂൽ(സ)യുടെ അനുചരരിൽ അവസാനമായി വഫാതായത് അദ്ദേഹമായിരുന്നു. (മു)', 'أَبِي الطُّفَيْلِ', 'അബുത്വുഫൈൽ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَهُ', null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ، فِي حُلَّةٍ حَمْرَاءَ، أَحْسَنَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَهُ شَعْرٌ يَضْرِبُ مَنْكِبَيْهِ، بَعِيدُ مَا بَيْنَ الْمَنْكِبَيْنِ، لَمْ يَكُنْ بِالْقَصِيرِ وَلَا بِالطَّوِيلِ. (ق,د,ت,ن,جه)', 'ബർറാഅ്(റ): തോളിനോളം മുടിയുള്ള ചുവന്ന മേൽ വസ്ത്രം ധരിച്ച ആരെയും ഞാൻ റസൂൽ(സ)യെക്കാൾ സുന്ദരനായി കണ്ടിട്ടില്ല. അവിടുത്തെ മുടി ഇരു തോളുകളോട് ചേർന്നിരുന്നു. രണ്ട് തോളുകൾക്കുമിടയിൽ വിശാലതയുണ്ടായിരുന്നു. റസൂൽ(സ) കുറിയവരോ നീളമുള്ളവരോ ആയിരുന്നില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബർറാഅ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ فِي سَاقَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُمُوشَةٌ، وَكَانَ لَا يَضْحَكُ إِلَّا تَبَسُّمًا، وَكُنْتُ إِذَا نَظَرْتُ إِلَيْهِ قُلْتُ: أَكْحَلُ الْعَيْنَيْنِ، وَلَيْسَ بِأَكْحَلَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ)യുടെ രണ്ടു കണങ്കാലുകളും നേർത്തതായിരുന്നു. ചിരിക്കുകയാണെങ്കിൽ അവിടുന്ന് പുഞ്ചിരിക്കുകയേ ചെയ്യാറുണ്ടായിരുന്നുള്ളൂ. ഞാൻ റസൂൽ(സ)യെ നോക്കുമ്പോൾ പറയുമായിരുന്നു: അവിടുത്തെ രണ്ടു കണ്ണുകളിലും സുറുമയിട്ടിരിക്കുന്നു. എന്നാലതിൽ സുറുമയിട്ടിട്ടുണ്ടായിരിക്കില്ല. (തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ – وَهُوَ ابْنُ أَرْبَعٍ وَتِسْعِينَ جَلْدًا مُعْتَدِلًا –: قَدْ عَلِمْتُ مَا مُتِّعْتُ بِهِ سَمْعِي وَبَصَرِي إِلَّا بِدُعَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّ خَالَتِي ذَهَبَتْ بِي إِلَيْهِ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي شَاكٍ فَادْعُ اللَّهَ لَهُ، قَالَ: فَدَعَا لِي. (خ)', 'സാഇബുബ്നു യസീദ്(റ): - തൊണ്ണൂറ്റിനാല് വയസ്സുള്ളപ്പോഴും അദ്ദേഹം ബലവാനും ആരോഗ്യവാനുമായിരുന്നു - അദ്ദേഹം പറഞ്ഞു: എന്റെ കേൾവിക്കും കാഴ്ചക്കും ഈ സുഖം കൈവന്നത് റസൂൽ(സ)യുടെ പ്രാർത്ഥനമൂലം മാത്രമാണെന്ന് തീർച്ചയായും എനിക്കറിയാം. എന്റെ മാതൃസഹോദരി എന്നെയും കൂട്ടി റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: എന്റെ സഹോദരീ പുത്രന് അസുഖം ബാധിച്ചിരിക്കുന്നു, അവനുവേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും. അന്നേരം നബി(സ) എനിക്കുവേണ്ടി പ്രാർത്ഥിച്ചു. (ബു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عُقْبَةَ بْنِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ الْعَصْرَ، ثُمَّ خَرَجَ يَمْشِي فَرَأَى الْحَسَنَ يَلْعَبُ مَعَ الصِّبْيَانِ، فَحَمَلَهُ عَلَى عَاتِقِهِ وَقَالَ: بِأَبِي شَبِيهٌ بِالنَّبِيِّ، لَا شَبِيهٌ بِعَلِيٍّ، وَعَلِيٌّ يَضْحَكُ. (خ)', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ): അബൂബക്കർ(റ) അസ്വർ നമസ്കരിക്കുകയും പിന്നീട് പുറത്തിറങ്ങി നടക്കുകയും ചെയ്യുമ്പോൾ ഹസൻ(റ) കുട്ടികളോടൊന്നിച്ച് കളിക്കുന്നത് കണ്ടു. അപ്പോൾ അബൂബക്കർ(റ) ഹസൻ(റ)വിനെ തന്റെ തോളിലേറ്റുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: എന്റെ പിതാവ് നിനക്ക് ബലി, നബി(സ)യോടാണ് നിനക്ക് സാദൃശ്യം, അലി(റ)വിനോടല്ല. അലി(റ) അപ്പോൾ ചിരിക്കുന്നുണ്ടായിരുന്നു. (ബു)', 'عُقْبَةَ بْنِ الْحَارِثِ', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ النَّاسِ وَجْهًا وَأَحْسَنَهُمْ خَلْقًا، لَيْسَ بِالطَّوِيلِ الْبَائِنِ وَلَا بِالْقَصِيرِ. (خ)', 'ബറാഅ്(റ): റസൂൽ(സ) ജനങ്ങളിൽ വെച്ചേറ്റവും മുഖസൗന്ദര്യമുള്ളവരും ശരീര സൗന്ദര്യമുള്ളവരും ആയിരുന്നു. അവിടുന്ന് അമിതമായി പൊക്കമുള്ളവരോ കുറിയവരോ ആയിരുന്നില്ല. (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَبْعَةً مِنَ الْقَوْمِ، لَيْسَ بِالطَّوِيلِ وَلَا بِالْقَصِيرِ، أَزْهَرَ اللَّوْنِ، لَيْسَ بِأَبْيَضَ أَمْهَقَ، وَلَا آدَمَ. لَيْسَ بِجَعْدٍ قَطَطٍ وَلَا سَبْطٍ رَجِلٍ. أُنْزِلَ عَلَيْهِ وَهُوَ ابْنُ أَرْبَعِينَ، فَلَبِثَ بِمَكَّةَ عَشْرَ سِنِينَ يُنْزَلُ عَلَيْهِ، وَبِالْمَدِينَةِ عَشْرَ سِنِينَ، وَقُبِضَ وَلَيْسَ فِي رَأْسِهِ وَلِحْيَتِهِ عِشْرُونَ شَعْرَةً بَيْضَاءَ. (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ജനങ്ങളിൽവെച്ച് മിതവലിപ്പമുള്ളവരായിരുന്നു. പൊക്കം കൂടിയവരോ കുറഞ്ഞവരോ ആയിരുന്നില്ല. തിളങ്ങുന്ന വർണ്ണമുള്ളവരായിരുന്നു. തനി വെള്ളയോ ശുദ്ധ തവിട്ട് നിറമോ ആയിരുന്നില്ല. മുടി ചുരുണ്ട് കട്ടപിടിച്ചതോ നീണ്ട് നിവർന്ന് കിടക്കുന്നതോ ആയിരുന്നില്ല. റസൂൽ(സ)ക്ക് നാൽപത് വയസ്സായപ്പോൾ അവിടത്തേക്ക് ഖുർആൻ അവതരിച്ചു. അവിടത്തേക്ക് ഖുർആൻ അവതരിച്ചുകൊണ്ടിരിക്കെ അവിടുന്ന് മക്കയിൽ പത്തു വർഷവും മദീനയിൽ പത്തു വർഷവും താമസിച്ചു. വഫാതാകുമ്പോൾ അവിടുത്തെ ശിരസ്സിലോ താടിയിലോ ഇരുപത് രോമം പോലും നരച്ചതായി ഉണ്ടായിരുന്നില്ല. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بُعِثْتُ مِنْ خَيْرِ قُرُونِ بَنِي آدَمَ قَرْنًا فَقَرْنًا، حَتَّى كُنْتُ مِنَ الْقَرْنِ الَّذِي كُنْتُ فِيهِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആദം സന്തതികളുടെ തലമുറകളിൽ ഏറ്റവും ഉൽകൃഷ്ടമായ തലമുറയിൽ നിന്നാണ് ഞാൻ പ്രവാചകനായി നിയോഗിക്കപ്പെട്ടത്. അതിനിടക്ക് ഞാൻ ഓരോ തലമുറയിലായി നീങ്ങുകയും അവസാനം ഞാൻ അവതരിച്ച ഈ തലമുറയിലെത്തുകയും ചെയ്തു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِالْبَطْحَاءِ وَبَيْنَ يَدَيْهِ عَنَزَةٌ، قَدْ تَقَدَّمَ هَذَا الْحَدِيثُ. وَفِي هَذِهِ الرِّوَايَةِ، قَالَ: فَجَعَلَ النَّاسُ يَأْخُذُونَ يَدَيْهِ فَيَمْسَحُونَ بِهَا وُجُوهَهُمْ، قَالَ: فَأَخَذْتُ بِيَدِهِ فَوَضَعْتُهَا عَلَى وَجْهِي، فَإِذَا هِيَ أَبْرَدُ مِنَ الثَّلْجِ وَأَطْيَبُ رَائِحَةً مِنَ الْمِسْكِ. (خ)', 'അബൂജുഹൈഫ(റ): അദ്ദേഹം നബി(സ) മരുഭൂമിയിൽവെച്ച് നമസ്കരിക്കുന്നത് കണ്ടു. അവിടുത്തെ മുമ്പിൽ ഒരു വടി നാട്ടിയിരുന്നു. ഈ ഹദീസ് മുമ്പ് വന്നിട്ടുണ്ട്. ഈ നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: ജനങ്ങൾ റസൂൽ(സ)യുടെ കരങ്ങൾ പിടിച്ച് തങ്ങളുടെ മുഖത്ത് തടവാൻ തുടങ്ങി. നിവേദകൻ പറയുന്നു: ഞാനും റസൂൽ(സ)യുടെ കൈ പിടിച്ച് എന്റെ മുഖത്ത് വെച്ചു. അപ്പോൾ അതിന് കസ്തൂരിയേക്കാൾ സുഗന്ധവും ഹിമത്തേക്കാൾ തണുപ്പുമുണ്ടായിരുന്നു. (ബു)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ لِي أَسْمَاءً: أَنَا مُحَمَّدٌ، وَأَنَا أَحْمَدُ، وَأَنَا الْمَاحِي الَّذِي يَمْحُو اللَّهُ بِيَ الْكُفْرَ، وَأَنَا الْحَاشِرُ الَّذِي يُحْشَرُ النَّاسُ عَلَى قَدَمِي، وَأَنَا الْعَاقِبُ الَّذِي لَيْسَ بَعْدَهُ أَحَدٌ". وَقَدْ سَمَّاهُ اللَّهُ رَءُوفًا رَحِيمًا. (م)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് കുറേ പേരുകൾ ഉണ്ട്. ഞാൻ മുഹമ്മദാണ്. ഞാൻ അഹ്മദാണ്, ഞാൻ മാഹിയാണ് (മായ്ക്കുന്നവൻ) - അല്ലാഹു എന്നെക്കൊണ്ട് സത്യനിഷേധത്തെ മായ്ച്ചുകളയും. ഞാൻ ഹാശിറാണ് (ഒരുമിച്ചു കൂട്ടുന്നവൻ) - ജനങ്ങൾ എന്റെ കീഴിൽ ഒരുമിച്ചുകൂട്ടപ്പെടും. ഞാൻ ആഖിബാണ് (അവസാനം വരുന്നവൻ). ആഖിബിനുശേഷം ഇനി ഒരാളും (പ്രവാചകത്വം) ഇല്ല." അല്ലാഹു റസൂൽ(സ)ക്ക് റഊഫ്(അനുകമ്പയുള്ളവർ) എന്നും റഹീം(കരുണയുള്ളവർ) എന്നും പേര് നൽകിയിട്ടുണ്ട്. (മു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَمِّي لَنَا نَفْسَهُ أَسْمَاءً فَقَالَ: "أَنَا مُحَمَّدٌ، وَأَحْمَدُ، وَالْمُقَفِّي، وَالْحَاشِرُ، وَنَبِيُّ التَّوْبَةِ، وَنَبِيُّ الرَّحْمَةِ". (م)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) ഞങ്ങൾക്ക് അവിടുത്തെ പേര് പറഞ്ഞുതന്നിരുന്നു. അപ്രകാരം അവിടുന്ന് പറഞ്ഞു: "ഞാൻ മുഹമ്മദും അഹ്മദും മുഖഫ്ഫയും (പിന്തുടരപ്പെടുന്നവർ) ഹാശിറും (ഒരുമിച്ചുകൂട്ടുന്നവർ) നബിയ്യുർറഹ്മയും (അനുഗ്രഹത്തിന്റെ പ്രവാചകർ) നബിയ്യുത്തൗബയും (പശ്ചാതാപത്തിന്റെ പ്രവാചകർ) ആണ്." (മു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْيَضَ قَدْ شَابَ، كَانَ الْحَسَنُ بْنُ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُمَا يُشْبِهُهُ. (م)', 'അബൂജുഹൈഫ(റ): റസൂൽ(സ)യെ വെളുത്ത് നരച്ച് ഞാൻ കണ്ടു. ഹസനുബ്നു അലി(റ) റസൂൽ(സ)യോട് സദൃശ്യമുള്ളവരായിരുന്നു. (മു)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 337, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سُئِلَ: هَلْ خَضَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: لَا، إِنَّمَا كَانَ شَيْءٌ فِي صُدْغَيْهِ. (خ)', 'അനസ്(റ): അദ്ദേഹത്തോട് ആരോ ചോദിച്ചു: റസൂൽ(സ) മൈലാഞ്ചിയിട്ടിരുന്നോ? അനസ്(റ) പറഞ്ഞു: ഇല്ല, രണ്ടു ചെന്നിയിലും അൽപം മാത്രം ഉണ്ടായിരുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ الْحَسَنُ بْنُ عَلِيٍّ عَلَيْهِمَا السَّلَامُ يُشْبِهُهُ، فَقِيلَ لَهُ: صِفْهُ لَنَا فَقَالَ: كَانَ أَبْيَضَ قَدْ شَمِطَ، وَأَمَرَ لَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثَ عَشْرَةَ قَلُوصًا، قَالَ: فَقُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ نَقْبِضَهَا. (خ)', 'അബൂജുഹൈഫ(റ): ഞാൻ നബി(സ)യെ കണ്ടു. ഹസനുബ്നു അലി(റ) നബി(സ)യോട് രൂപസാദൃശ്യമുണ്ടായിരുന്നു. നബി(സ)യെ ഞങ്ങൾക്ക് ഒന്നു വർണ്ണിച്ചുതരിക എന്ന് അബൂജുഹൈഫ(റ)വിനോട് പറയപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ)യുടെ നിറം വെളുപ്പായിരുന്നു. രോമം നരച്ചതും നരക്കാത്തതുമായി ഇടകലർന്നതായിരുന്നു. നബി(സ) ഞങ്ങൾക്ക് യൗവ്വന പ്രായത്തിലുള്ള പതിമൂന്ന് ഒട്ടകങ്ങളെ നൽകാൻ കൽപിച്ചു. പക്ഷേ, ഞങ്ങൾക്കത് ലഭിക്കുംമുമ്പ് അവിടുന്ന് വഫാതായി. (ബു)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَضِيَ عَنْهُ قِيلَ لَهُ: أَرَأَيْتَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ شَيْخًا، قَالَ: كَانَ فِي عَنْفَقَتِهِ شَعَرَاتٌ بِيضٌ. (خ)', 'നബി(സ)യുടെ സഹചാരിയായ അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)വിനോട് ചോദിക്കപ്പെട്ടു: നബി(സ) ഒരു വൃദ്ധനായിരുന്നോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ)യുടെ താടിക്കും കീഴ്ചുണ്ടിനും മധ്യേ ചില രോമങ്ങൾ നരച്ചിട്ടുണ്ടായിരുന്നു. (ബു)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَ', 'നബി(സ)യുടെ സഹചാരിയായ അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَضْرِبُ شَعْرُهُ مَنْكِبَيْهِ. (م)', 'അനസ്(റ): റസൂൽ(സ)യുടെ തലമുടി രണ്ട് തോളുകൾ വരെ ചാഞ്ഞുകിടന്നിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ شَعْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَنْصَافِ أُذُنَيْهِ. (م)', 'അനസ്(റ): റസൂൽ(സ)യുടെ തലമുടി രണ്ട് ചെവിയുടെ പകുതിവരെ ഉണ്ടായിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْدُلُ شَعْرَهُ، وَكَانَ الْمُشْرِكُونَ يَفْرُقُونَ رُءُوسَهُمْ، فَكَانَ أَهْلُ الْكِتَابِ يَسْدُلُونَ رُءُوسَهُمْ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ مُوَافَقَةَ أَهْلِ الْكِتَابِ فِيمَا لَمْ يُؤْمَرْ فِيهِ بِشَيْءٍ، ثُمَّ فَرَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأْسَهُ. (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) അവിടുത്തെ തലമുടി കീഴ്പോട്ട് താഴ്ത്തിയിടുകയായിരുന്നു പതിവ്. ബഹുദൈവാരാധകർ അവരുടെ തലമുടി ഇരു വശങ്ങളിലേക്കും വാർന്നുവെച്ചിരുന്നു. വേദക്കാരും മുടി കീഴ്പോട്ടു താഴ്ത്തിയിട്ടിരുന്നു. പ്രത്യേകം കൽപ്പനയൊന്നും വന്നിട്ടില്ലാത്ത കാര്യങ്ങളിൽ വേദക്കാരോട് യോജിക്കലായിരുന്നു തിരുമേനിക്കിഷ്ടം. പിന്നീട് അവിടുന്ന് തലമുടി ഇരുവശങ്ങളിലേക്കും വാർന്നുവെച്ചു. (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ، وَقَدْ سَأَلَهُ رَجُلٌ: أَكَانَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلَ السَّيْفِ؟ قَالَ: لَا، مِثْلَ الْقَمَرِ. (خ,ت)', 'ബറാഅ്(റ): അദ്ദേഹത്തോട് ഒരാൾ ചോദിച്ചു: റസൂൽ(സ)യുടെ മുഖം വാൾപോലെ ആയിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അല്ല, ചന്ദ്രനെപ്പോലെയാണ്. (ബു,തു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالطَّوِيلِ وَلَا بِالْقَصِيرِ، شَثْنَ الْكَفَّيْنِ وَالْقَدَمَيْنِ، ضَخْمَ الرَّأْسِ، ضَخْمَ الْكَرَادِيسِ، طَوِيلَ الْمَسْرُبَةِ، إِذَا مَشَى تَكَفَّأَ تَكَفُّؤًا كَأَنَّمَا انْحَطَّ مِنْ صَبَبٍ، لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'അലി(റ): റസൂൽ(സ) നീണ്ടവരോ കുറിയവരോ ആയിരുന്നില്ല. അവിടുത്തെ കരങ്ങളും പാദങ്ങളും ശിരസ്സും സന്ധിയെല്ലുകളുമെല്ലാം വലുതായിരുന്നു. അവിടുത്തെ നെഞ്ചുരോമം നീണ്ടതായിരുന്നു. അവിടുന്ന് നടക്കുമ്പോൾ കുന്നിൽ നിന്ന് ഇറങ്ങിവരുന്നതുപോലെ അൽപം മുന്നോട്ട് ചെരിഞ്ഞായിരുന്നു നടന്നിരുന്നത്. അവിടുത്തെ മുമ്പോ ശേഷമോ അവിടുത്തെ പോലെയുള്ള ഒരാളെ ഞാൻ കണ്ടിട്ടില്ല. (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ شَيْئًا أَحْسَنَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَشْيَتِهِ، كَأَنَّ الشَّمْسَ تَجْرِي فِي وَجْهِهِ. وَمَا رَأَيْتُ أَحَدًا أَسْرَعَ فِي مَشْيَتِهِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَأَنَّمَا الْأَرْضُ تُطْوَى لَهُ، إِنَّا لَنُجْهِدُ أَنْفُسَنَا وَإِنَّهُ لَغَيْرُ مُكْتَرِثٍ. (ت)', 'അബൂഹുറൈറ(റ): നടത്തത്തിൽ നബി(സ)യെക്കാൾ ഭംഗിയുള്ള ഒന്നിനെയും ഞാൻ കണ്ടിട്ടില്ല. അവിടുത്തെ മുഖത്ത് സൂര്യൻ സഞ്ചരിക്കുന്നതുപോലെ തോന്നുമായിരുന്നു. നബി(സ)യെക്കാൾ വേഗത്തിൽ നടക്കുന്ന ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. അവിടുത്തേക്കുവേണ്ടി ഭൂമി ചുരുട്ടപ്പെടുന്നതു പോലെയായിരുന്നു. അവിടുന്ന് അനായാസം അങ്ങനെ നടക്കുമ്പോഴും അവിടുത്തോടൊപ്പമെത്താൻ ഞങ്ങൾ പ്രയാസപ്പെടാറുണ്ടായിരുന്നു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَلِيعَ الْفَمِ، أَشْكَلَ الْعَيْنِ، مَنْهُوسَ الْعَقِبَيْنِ. قَالَ: قُلْتُ لِسِمَاكٍ: مَا ضَلِيعُ الْفَمِ؟ قَالَ: عَظِيمُ الْفَمِ، [قَالَ]: قُلْتُ: مَا أَشْكَلُ الْعَيْنِ؟ قَالَ: طَوِيلُ شَقِّ الْعَيْنِ. قَالَ: قُلْتُ: مَا مَنْهُوسُ الْعَقِبِ؟ قَالَ: قَلِيلُ لَحْمِ الْعَقِبِ. (م,ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) വിശാലമായ വായയുള്ളവരും കൺകോൺ നീളമുള്ളവരും മടമ്പുകലിലെ മാംസം കുറഞ്ഞവരുമായിരുന്നു. നിവേദകൻ പറയുന്നു: ഞാൻ സിമാക്(റ)വിനോട് ചോദിച്ചു: ''ളലീഉൽ ഫമി'' എന്നാൽ എന്താണ്? അദ്ദേഹം പറഞ്ഞു: വിശാലമായ വായയുള്ളവർ എന്നാണർത്ഥം. ഞാൻ ചോദിച്ചു: ''അശ്കലുൽ ഐനി'' എന്നാൽ എന്താണ്? അദ്ദേഹം പറഞ്ഞു: കൺകോൺ നീണ്ടവർ എന്നാണർത്ഥം. ഞാൻ ചോദിച്ചു: ''മൻഹൂസുൽ അഖിബ്'' എന്നാൽ എന്താണ്? അദ്ദേഹം പറഞ്ഞു: മടമ്പിലെ മാംസം കുറഞ്ഞവർ എന്നാണർത്ഥം. (മു,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], 'قَالَ', null, 339, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ يَكْرَهُ أَنْ يَنْتِفَ الرَّجُلُ الشَّعْرَةَ الْبَيْضَاءَ مِنْ رَأْسِهِ وَلِحْيَتِهِ، قَالَ: وَلَمْ يَخْتَضِبْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّمَا كَانَ الْبَيَاضُ فِي عَنْفَقَتِهِ وَفِي الصُّدْغَيْنِ، وَفِي الرَّأْسِ نَبْذٌ. (م)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ തന്റെ തലയിൽ നിന്നും താടിയിൽ നിന്നും വെളുത്ത രോമങ്ങളെ പറിച്ച് നീക്കുന്നത് അദ്ദേഹം വെറുക്കുമായിരുന്നു. അദ്ദേഹം പറയുന്നു: റസൂൽ(സ) മുടിയിൽ ചായം തേച്ചിട്ടുണ്ടായിരുന്നില്ല. അവിടുത്തെ രണ്ട് ചെന്നികളിലും കീഴ്ചുണ്ടിന് താഴെയുള്ള മുടിയിലും തലയിൽ അൽപം സ്ഥലത്തും മാത്രമായിരുന്നു നരയുണ്ടായിരുന്നത്. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ بَيْنَ أَظْهُرِنَا إِذْ أَغْفَى إِغْفَاءَةً، ثُمَّ رَفَعَ رَأْسَهُ مُتَبَسِّمًا، فَقُلْنَا: مَا أَضْحَكَكَ يَا رَسُولَ اللَّهِ؟ قَالَ: "نَزَلَتْ عَلَيَّ آنِفًا سُورَةٌ، فَقَرَأَ: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ، فَصَلِّ لِرَبِّكَ وَانْحَرْ، إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ}". ثُمَّ قَالَ: "أَتَدْرُونَ مَا الْكَوْثَرُ". فَقُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "فَإِنَّهُ نَهْرٌ وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ، عَلَيْهِ خَيْرٌ كَثِيرٌ، هُوَ حَوْضٌ تَرِدُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ، آنِيَتُهُ عَدَدُ النُّجُومِ، فَيُخْتَلَجُ الْعَبْدُ مِنْهُمْ، فَأَقُولُ: رَبِّ إِنَّهُ مِنْ أُمَّتِي، فَيَقُولُ: مَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ". (م)', 'അനസ്(റ): ഒരു ദിവസം ഞങ്ങൾക്കിടയിൽ നിൽക്കെ റസൂൽ(സ) ഒരു ചെറിയ ഉറക്കം ഉറങ്ങി. ശേഷം പുഞ്ചിരിച്ചുകൊണ്ട് അവിടുന്ന് തലയുയർത്തി. ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്തിനാണ് അവിടുന്ന് ചിരിച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "ഇപ്പോൾ എനിക്ക് ഒരു അധ്യായം അവതരിച്ചു." അവിടുന്ന് അത് പാരായണം ചെയ്തു: കരുണാവാരിധിയും കാരുണ്യവാനുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ. നിശ്ചയം നാം അങ്ങേക്ക് കൗസർ നൽകിയിരിക്കുന്നു. അതിനാൽ അങ്ങ് അങ്ങയുടെ നാഥനുവേണ്ടി നമസ്കരിക്കുകയും അറവ് നടത്തുകയും ചെയ്യുക. നിശ്ചയം അങ്ങയോട് ദേഷ്യം വെക്കുന്നവനാണ് നന്മയറ്റവൻ." ശേഷം അവിടുന്ന് ചോദിച്ചു: "കൗസർ എന്താണെന്ന് നിങ്ങൾക്കറിയുമോ?" ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. റസൂൽ(സ) പറഞ്ഞു: "അത്യുത്തമനും അഭിമാനിയുമായ എന്റെ രക്ഷിതാവ് എനിക്ക് വാഗ്ദാനം ചെയ്ത ഒരു നദിയാണത്. അതിനു സമീപം ധാരാളം നന്മകളുണ്ട്. അന്ത്യനാളിൽ എന്റെ സമുദായം (വെള്ളം കുടിക്കാൻ) വരുന്ന ഒരു തടാകമാണത്. അതിലെ കോപ്പകൾ നക്ഷത്രങ്ങളുടെ എണ്ണത്തിനനുസൃതമാണ്. അങ്ങനെ അവരിൽപെട്ട ഒരടിമയെ (അതിൽ നിന്നും) തടയപ്പെടും. അപ്പോൾ ഞാൻ പറയും: എന്റെ രക്ഷിതാവേ, അവൻ എന്റെ സമുദായത്തിൽ പെട്ടവനാണ്. അപ്പോൾ അല്ലാഹു പറയും: അങ്ങേക്കുശേഷം അവർ ചെയ്തുകൂട്ടിയത് അങ്ങേക്കറിയില്ല." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ أَحَدًا أَكْثَرَ تَبَسُّمًا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ قَالَ: مَا كَانَ ضَحْكُ رَسُولِ اللَّهِ إِلَّا تَبَسُّمًا. (ت)', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസുബ്നു ജസ്അ്(റ): റസൂൽ(സ)യെക്കാൾ കൂടുതലായി പുഞ്ചിരിക്കുന്ന ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. മറ്റൊരു റിപ്പോർട്ട്: നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യുടെ ചിരി പുഞ്ചിരി മാത്രമായിരുന്നു. (തു)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസുബ്നു ജസ്അ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 340, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=8 and h.hadith_no=106), 1, 'وَفِي رِوَايَةٍ قَالَ: مَا كَانَ ضَحْكُ رَسُولِ اللَّهِ إِلَّا تَبَسُّمًا. (ت)', 'മറ്റൊരു നിവേദന്: നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യുടെ ചിരി പുഞ്ചിരി മാത്രമായിരുന്നു. (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَشَدَّ حَيَاءً مِنَ الْعَذْرَاءِ فِي خِدْرِهَا، وَكَانَ إِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِي وَجْهِهِ. (ق)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) മണിയറയിൽ കഴിയുന്ന കന്യകയേക്കാൾ ലജ്ജയുള്ളവരായിരുന്നു. അവിടത്തേക്ക് വല്ല വെറുപ്പും അനുഭവപ്പെടുന്നുവെങ്കിൽ അവിടുത്തെ മുഖത്തുനിന്ന് ഞങ്ങൾ അത് മനസ്സിലാക്കുമായിരുന്നു. (ബു,മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَزْهَرَ اللَّوْنِ، كَأَنَّ عَرَقَهُ اللُّؤْلُؤُ، إِذَا مَشَى تَكَفَّأَ، وَلَا مَسَسْتُ دِيبَاجَةً وَلَا حَرِيرَةً أَلْيَنَ مِنْ كَفِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا شَمِمْتُ مِسْكَةً وَلَا عَنْبَرَةً أَطْيَبَ مِنْ رَائِحَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) മിന്നിത്തിളങ്ങുന്ന നിറമുള്ളയാളായിരുന്നു. അവിടുത്തെ വിയർപ്പ് മുത്ത് പോലെയായിരുന്നു. നടക്കുമ്പോൾ അവിടുന്ന് അൽപം മുന്നോട്ട് ആഞ്ഞ് നടക്കുമായിരുന്നു. റസൂൽ(സ)യുടെ കരംപോലെ നിർമ്മലമായ പട്ടോ ദീബാജോ (ഉയർന്ന ഇനം പട്ട്) ഞാൻ സ്പർശിച്ചിട്ടില്ല. റസൂൽ(സ)യുടെ വാസനയേക്കാൾ സുഗന്ധമുള്ള മിസ്കോ അമ്പറോ ഞാൻ വാസനിച്ചിട്ടില്ല. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْأُولَى، ثُمَّ خَرَجَ إِلَى أَهْلِهِ وَخَرَجْتُ مَعَهُ، فَاسْتَقْبَلَهُ وِلْدَانٌ، فَجَعَلَ يَمْسَحُ خَدَّيْ أَحَدِهِمْ وَاحِدًا وَاحِدًا، قَالَ: وَأَمَّا أَنَا فَمَسَحَ خَدِّي، [قَالَ]: فَوَجَدْتُ لِيَدِهِ بَرْدًا – أَوْ رِيحًا – كَأَنَّمَا أَخْرَجَهَا مِنْ جُؤْنَةِ عَطَّارٍ. (م)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ)യോടൊപ്പം ഞാൻ ആദ്യത്തെ നമസ്കാരം (ളുഹ്ർ) നമസ്കരിച്ചു. ശേഷം അവിടുന്ന് തന്റെ കുടുംബത്തിലേക്ക് പോയി. ഞാനും അവിടുത്തോടൊപ്പം പുറപ്പെട്ടു. അപ്പോൾ കുറച്ച് കുട്ടികൾ അവിടത്തെ മുന്നിൽ വന്നു. അവിടുന്ന് അവരിൽ ഓരോരുത്തരുടെയും ഇരു കവിളുകളും തടവാൻ തുടങ്ങി. നിവേദകൻ പറയുന്നു: അവിടുന്ന് എന്റെ കവിളും തടവി. അപ്പോൾ അവിടുത്തെ കയ്യിൽ, അത്തർ കച്ചവടക്കാരന്റെ പെട്ടിയിൽനിന്ന് പുറത്തെടുത്തതു പോലുള്ള ഒരു തണുപ്പ് - അല്ലെങ്കിൽ: സുഗന്ധം - എനിക്ക് അനുഭവപ്പെട്ടു. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا مَسِسْتُ حَرِيرًا وَلَا دِيبَاجًا أَلْيَنَ مِنْ كَفِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا شَمِمْتُ رِيحًا قَطُّ أَوْ عَرْفًا قَطُّ، أَطْيَبَ مِنْ رِيحِ أَوْ عَرْفِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസ്(റ): നബി(സ)യുടെ കരത്തേക്കാൾ നിർമ്മലമായ പട്ടുവസ്ത്രമോ ദീബാജോ ഞാൻ സ്പർശിച്ചിട്ടില്ല. നബി(സ)യുടെ വാസനയേക്കാൾ അല്ലെങ്കിൽ സുഗന്ധത്തേക്കാൾ സുഗന്ധമുള്ള വാസനയോ സുഗന്ധമോ ഞാൻ അനുഭവിച്ചിട്ടില്ല. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنْ كَانَ لَيُنْزَلُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْغَدَاةِ الْبَارِدَةِ، ثُمَّ تَفِيضُ جَبْهَتُهُ عَرَقًا. (م)', 'ആഇശ(റ): തണുപ്പുള്ള പ്രഭാതത്തിൽ നബി(സ)ക്ക് വഹ്യ് അവതരിക്കുകയും അങ്ങനെ അവിടുത്തെ നെറ്റിത്തടം വിയർത്തൊലിക്കുകയും ചെയ്യുമായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أنَس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عِنْدَنَا، فَعَرِقَ، وَجَاءَتْ أُمِّي بِقَارُورَة فَجَعَلَتْ تَسْلُتُ الْعَرَقَ فِيهَا، فَاسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أُمَّ سُلَيْمٍ، مَا هَذَا الَّذِي تَصْنَعِينَ". قَالَتْ: هَذَا عَرَقُكَ، نَجْعَلُهُ فِي طِيبِنَا، وَهُوَ مِنْ أَطْيَبِ الطِّيبِ. (م)', 'അനസ്(റ): നബി(സ) ഞങ്ങളുടെ അടുത്ത് വരികയും അവിടെ പകലുറക്കം ഉറങ്ങുകയും ചെയ്തു. അങ്ങനെ അവിടുന്ന് വിയർത്തു. എന്റെ ഉമ്മ ഒരു കുപ്പി കൊണ്ടുവന്ന് വിയർപ്പ് തുടച്ച് അതിലേക്കെടുക്കാൻ തുടങ്ങി. ഉടനെ നബി(സ) ഉണർന്നു. അവിടുന്ന് ചോദിച്ചു: "ഉമ്മു സുലൈമേ, ഇതെന്താണ് നീ ചെയ്യുന്നത്?" ഉമ്മുസുലൈം(റ) പറഞ്ഞു: ഇത് അവിടുത്തെ വിയർപ്പാണ്. അത് ഞങ്ങളുടെ സുഗന്ധത്തിൽ ഞങ്ങൾ ചേർക്കും. അത് ഏറ്റവും സുഗന്ധമുള്ള സുഗന്ധദ്രവ്യമാണ്. (മു)', 'أنَس بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أنَس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ عَلَى بَيْتِ أُمِّ سُلَيْمٍ فَيَنَامُ عَلَى فِرَاشِهَا، وَلَيْسَتْ فيه. قَالَ: فَجَاءَ ذَاتَ يَوْمٍ فَنَامَ عَلَى فِرَاشِهَا فَأُتِيتْ، فَقِيلَ لَهَا: هَذَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَائِمٌ فِي بَيْتِكِ عَلَى فِرَاشِكِ، قَالَ: فَجَاءَتْ وَقَدْ عَرِقَ وَاسْتَنْقَعَ عَرَقُهُ عَلَى قِطْعَةِ أَدِيمٍ عَلَى الْفِرَاشِ، فَفَتَحَتْ عَتِيدَهَا، قَالَ: فَجَعَلَتْ تُنَشِّفُ ذَلِكَ الْعَرَقَ فَتَعْصِرُهُ فِي قَوَارِيرِهَا، فَفَزِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَا تَصْنَعِينَ يَا أُمَّ سُلَيْمٍ". فَقَالَتْ: يَا رَسُولَ اللَّهِ، نَرْجُو بَرَكَتَهُ لِصِبْيَانِنَا. قَالَ: "أَصَبْتِ". (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഉമ്മുസുലൈം(റ)യുടെ വീട്ടിൽ പ്രവേശിക്കുകയും മഹതിയില്ലാത്ത സമയത്ത് മഹതിയുടെ വിരിപ്പിൽ ഉറങ്ങുകയും ചെയ്യുമായിരുന്നു. നിവേദകൻ പറയുന്നു: ഒരു ദിവസം നബി(സ) വരികയും മഹതിയുടെ വിരിപ്പിൽ കിടന്ന് ഉറങ്ങുകയും ചെയ്തു. അന്നേരം മഹതിയുടെ അടുത്തു ചെന്ന് ആരോ പറഞ്ഞു: നബി(സ)യതാ നിങ്ങളുടെ വീട്ടിൽവന്ന് നിങ്ങളുടെ വിരിപ്പിലുറങ്ങുന്നു. നിവേദകൻ പറയുന്നു: ഉടനെ മഹതി വന്നു. നബി(സ) വിയർക്കുകയും അവിടുത്തെ വിയർപ്പ് വിരിപ്പിന്മേലുള്ള ഒരു തോൽകഷ്ണത്തിൽ കൂടിനിൽക്കുകയും ചെയ്തിരുന്നു. ഉമ്മുസുലൈം(റ) സുഗന്ധദ്രവ്യച്ചെപ്പ് തുറക്കുകയും ആ വിയർപ്പ് തുടച്ചെടുത്ത് കുപ്പികളിലേക്ക് പിഴിയാൻ തുടങ്ങുകയും ചെയ്തു. അപ്പോൾ നബി(സ) ഞെട്ടിയുണർന്നു. അവിടുന്ന് ചോദിച്ചു: "ഉമ്മുസുലൈമേ, നീ എന്താണ് ചെയ്യുന്നത്?" മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അതിലെ ബറകത് ഞങ്ങളുടെ സന്താനങ്ങൾക്ക് ലഭിക്കണമെന്ന് ഞങ്ങൾ ആഗ്രഹിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നീ പറഞ്ഞതത് ശരിയാണ്." (മു)', 'أنَس بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 342, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْغَدَاةَ جَاءَ خَدَمُ الْمَدِينَةِ بِآنِيَتِهِمْ فِيهَا الْمَاءُ، فَمَا يُؤْتَى بِإِنَاءٍ إِلَّا غَمَسَ يَدَهُ فِيهَا، فَرُبَّمَا جَاءُوهُ فِي الْغَدَاةِ الْبَارِدَةِ فَيَغْمِسُ يَدَهُ فِيهَا. (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) സുബഹ് നമസ്കരിച്ച് കഴിഞ്ഞാൽ മദീനയിലെ സേവകർ തങ്ങളുടെ പാത്രങ്ങളിൽ വെള്ളവുമായി വരുമായിരുന്നു. കൊണ്ടുവരുന്ന ഓരോ പാത്രത്തിലും നബി(സ) തന്റെ കൈ മുക്കുമായിരുന്നു. തണുപ്പുള്ള പ്രഭാതത്തിൽ പോലും അവർ അത് കൊണ്ടുവരികയും അവിടുന്ന് അതിൽ കൈമുക്കുകയും ചെയ്യുമായിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْحَلَّاقُ يَحْلِقُهُ، وَأَطَافَ بِهِ أَصْحَابُهُ، فَمَا يُرِيدُونَ أَنْ تَقَعَ شَعْرَةٌ إِلَّا فِي يَدِ رَجُلٍ. (م)', 'അനസ്(റ): ക്ഷുരകൻ നബി(സ)യുടെ മുടി വെട്ടുമ്പോൾ തീർച്ചയായും ഞാൻ അവിടുത്തെ കണ്ടിട്ടുണ്ട്. അവിടുത്തെ അനുചരർ നബി(സ)യെ ചുറ്റിനടക്കുന്നുണ്ടായിരുന്നു. ഒരു മുടിപോലും ഒരു വ്യക്തിയുടെ കയ്യിലേക്കല്ലാതെ വീഴരുതെന്നായിരുന്നു അവരുടെ ഉദ്ദേശ്യം. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ امْرَأَةً كَانَ فِي عَقْلِهَا شَيْءٌ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ لِي إِلَيْكَ حَاجَةً. فَقَالَ: "يَا أُمَّ فُلَانٍ، انْظُرِي أَيَّ السِّكَكِ شِئْتِ حَتَّى أَقْضِيَ لَكِ حَاجَتَكِ". فَخَلَا مَعَهَا فِي بَعْضِ الطُّرُقِ حَتَّى فَرَغَتْ مِنْ حَاجَتِهَا. (م)', 'അനസ്(റ): ഒരു സ്ത്രീയുടെ ബുദ്ധിയിൽ എന്തോ പ്രശ്നമുണ്ടായിരുന്നു. അവൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് അങ്ങയെ ഒന്ന് ആവശ്യമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "സഹോദരീ, നിനക്കിഷ്ടപ്പെട്ട ഏതു സ്ഥലത്തുവെച്ചും ഞാൻ നിന്റെ ആവശ്യം നിറവേറ്റിത്തരാം." അങ്ങനെ നബി(സ) ഒരു വഴിയിൽവെച്ച് അവളോടൊന്നിച്ചിരിക്കുകയും അങ്ങനെ അവളുടെ ആവശ്യം വീടുകയും ചെയ്തു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أبو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يُحَدِّثُ وَيَقُولُ: اسْمَعِي يَا رَبَّةَ الْحُجْرَةِ، اسْمَعِي يَا رَبَّةَ الْحُجْرَةِ، وَعَائِشَةُ رِضْوَانُ اللَّهِ عَلَيْهَا تُصَلِّي، فَلَمَّا قَضَتْ صَلَاتَهَا قَالَتْ لِعُرْوَةَ: أَلَا تَسْمَعُ إِلَى هَذَا وَمَقَالَتِهِ آنِفًا؟ إِنَّمَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحَدِّثُ حَدِيثًا لَوْ عَدَّهُ الْعَادُّ لَأَحْصَاهُ. (ق)', 'ഉർവതുബ്നു സുബൈർ(റ): അബൂഹുറൈറ(റ) ഹദീസ് ഉദ്ധരിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുന്നുണ്ടായിരുന്നു: വീടിന്റെ യജമാനത്തിയേ, നീ കേൾക്കുക, വീടിന്റെ യജമാനത്തിയേ, നീ കേൾക്കുക. ആഇശ(റ) അപ്പോൾ നമസ്കരിക്കുകയായിരുന്നു. നമസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ മഹതി ഉർവ(റ)വിനോട് പറഞ്ഞു: ഇദ്ദേഹം (അബൂഹുറൈറ) അൽപംമുമ്പ് പറഞ്ഞത് നീ കേട്ടില്ലേ? ഒരാൾ എണ്ണിയാൽ തിട്ടപ്പെടുത്താൻ സാധിക്കുന്നയത്ര മാത്രമേ നബി(സ) ഹദീസ് പറയാറുണ്ടായിരുന്നുള്ളൂ. (ബു,മു)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവതുബ്നു സുബൈർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَسْرُدُ الْحَدِيثَ كَسَرْدِكُمْ. (خ)', 'ആഇശ(റ): നിങ്ങൾ തുടർച്ചയായി ഹദീസ് പറയുന്നതു പോലെ നിശ്ചയം നബി(സ) ഹദീസ് പറയുമായിരുന്നില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ سَعْدِ بْنِ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ قَالَ لِأُمَيَّةَ بْنِ خَلَفٍ: إِنِّي سَمِعْتُ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزْعُمُ أَنَّهُ قَاتِلُكَ قَالَ: إِيَّايَ؟ قَالَ: نَعَمْ، قَالَ: وَاللَّهِ مَا يَكْذِبُ مُحَمَّدٌ إِذَا حَدَّثَ، فَقَتَلَهُ اللَّهُ بِبَدْرٍ، وَفِي الْحَدِيثِ قِصَّةٌ، هَذَا مَضْمُونُ الْحَدِيثِ مِنْهَا. (خ)', 'സഅ്ദുബ്നു മുആദ്(റ): അദ്ദേഹം ഉമയ്യതുബ്നു ഖലഫിനോട് പറഞ്ഞു: മുഹമ്മദ്(സ) നിന്നെ വധിക്കുമെന്ന് അവിടുന്ന് ഉറപ്പിച്ചു പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. ഉമയ്യത് ചോദിച്ചു: എന്നെയോ? സഅ്ദ്(റ) പറഞ്ഞു: അതെ. ഉമയ്യത് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, സംസാരത്തിൽ മുഹമ്മദ് കളവ് പറയുകയില്ല. അങ്ങനെ ബദ്റിൽ വെച്ച് അല്ലാഹു അവനെ വധിച്ചു. ഈ ഹദീസിൽ ഒരു ചരിത്രം തന്നെയുണ്ട്. അതിലെ സംസാരത്തിന്റെ ഉള്ളടക്കമാണിത്. (ബു)', 'سَعْدِ بْنِ مُعَاذٍ', 'സഅ്ദുബ്നു മുആദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْرُدُ سَرْدَكُمْ هَذَا، وَلَكِنَّهُ كَانَ يَتَكَلَّمُ بِكَلَامٍ يُبَيِّنُهُ، فَصْلٌ، يَحْفَظُهُ مَنْ جَلَسَ إِلَيْهِ. (ق,د,ت)', 'ആഇശ(റ): റസൂൽ(സ) നിങ്ങളെപ്പോലെ തുടർച്ചയായി സംസാരിക്കുമായിരുന്നില്ല. സമീപത്തിരിക്കുന്നവർക്ക് മനഃപാഠമാക്കാൻ കഴിയുംവിധം ഖണ്ഡിതമായി വളരെ വ്യക്തമാകും വിധത്തിലുള്ള സംസാരമായിരുന്നു അവിടുന്ന് സംസാരിച്ചിരുന്നത്. (ബു,മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعِيدُ الْكَلِمَةَ ثَلَاثًا لِتُعْقَلَ عَنْهُ. (خ,ت)', 'അനസുബ്നു മാലിക്(റ): മറ്റുള്ളവർക്ക് മനസ്സിലാകാൻ വേണ്ടി റസൂൽ(സ) ഒരു വാക്ക് തന്നെ മുന്നുപ്രാവശ്യം ആവർത്തിക്കുമായിരുന്നു. (ബു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: يُحَدِّثُ عَنْ لَيْلَةِ أُسْرِيَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَسْجِدِ الْكَعْبَةِ، جَاءَ ثَلَاثَةُ نَفَرٍ قَبْلَ أَنْ يُوحَى إِلَيْهِ وَهُوَ نَائِمٌ فِي مَسْجِدِ الْحَرَامِ، فَقَالَ أَوَّلُهُمْ: أَيُّهُمْ هُوَ؟ فَقَالَ أَوْسَطُهُمْ: هُوَ خَيْرُهُمْ. وَقَالَ آخِرُهُمْ: خُذُوا خَيْرَهُمْ، فَكَانَتْ تِلْكَ. فَلَمْ يَرَهُمْ حَتَّى جَاءُوا لَيْلَةً أُخْرَى فِيمَا يَرَى قَلْبُهُ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَائِمَةٌ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ، وَكَذَلِكَ الْأَنْبِيَاءُ تَنَامُ أَعْيُنُهُمْ وَلَا تَنَامُ قُلُوبُهُمْ، فَتَوَلَّاهُ جِبْرِيلُ ثُمَّ عَرَجَ بِهِ إِلَى السَّمَاءِ. (خ)', 'അനസ്(റ): കഅ്ബയുൾക്കൊള്ളുന്ന പള്ളി(മസ്ജിദുൽ ഹറാം)യിൽ നിന്ന് നബി(സ)യെ രാപ്രയാണം നടത്തപ്പെട്ട രാത്രിയെക്കുറിച്ച് അനസ്(റ) ഹദീസ് പറയുന്നു: നബി(സ) മസ്ജിദുൽഹറാമിൽ ഉറങ്ങിക്കൊണ്ടിരിക്കെ, അവിടത്തേക്ക് വഹ്യ് അറിയിക്കപ്പെടും മുമ്പ് മൂന്നാളുകൾ വന്നു. അവരിൽ ആദ്യത്തെയാൾ ചോദിച്ചു: ജനങ്ങളിൽ ആരാണിത്? നടുവിലത്തെയാൾ പറഞ്ഞു: അവരിൽ ഏറ്റവും ഉത്തമരാണിത്. അവസാനത്തെയാൾ പറഞ്ഞു: അവരിൽ ഏറ്റവും ഉത്തമരായവരെ നിങ്ങൾ എടുക്കുക. അങ്ങനെ ആ സംഭവമുണ്ടായി. ശേഷം റസൂൽ(സ) അവരെ കണ്ടില്ല. എന്നാൽ തന്റെ ഹൃദയംകൊണ്ട് കാണുംവിധം മറ്റൊരു രാത്രി അവർ വന്നു. നബി(സ)യുടെ ഇരു കണ്ണുകളും ഉറങ്ങുമായിരുന്നെങ്കിലും അവിടുത്തെ ഹൃദയം ഉറങ്ങുമായിരുന്നില്ല. മുഴുവൻ പ്രവാചകന്മാരും അപ്രകാരം തന്നെയാണ്. അവരുടെ കണ്ണുകൾ ഉറങ്ങും, എന്നാൽ ഹൃദയങ്ങൾ ഉറങ്ങുകയില്ല. അങ്ങനെ ജിബ്രീൽ(അ) നബി(സ)യെ ഏറ്റെടുക്കുകയും അവിടത്തെയും കൊണ്ട് ആകാശത്തേക്ക് കയറുകയും ചെയ്തു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ إِذَا وَصَفَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمْ يَكُنْ بِالطَّوِيلِ الْمُمَّغِطِ وَلَا بِالْقَصِيرِ الْمُتَرَدِّدِ، وَكَانَ رَبْعَةً مِنَ الْقَوْمِ، وَلَمْ يَكُنْ بِالْجَعْدِ الْقَطَطِ وَلَا بِالسَّبْطِ، كَانَ جَعْدًا رَجِلًا، وَلَمْ يَكُنْ بِالْمُطَهَّمِ وَلَا بِالْمُكَلْثَمِ، وَكَانَ فِي الْوَجْهِ تَدْوِيرٌ أَبْيَضُ مُشْرَبٌ، أَدْعَجُ الْعَيْنَيْنِ، أَهْدَبُ الْأَشْفَارِ، جَلِيلُ الْمُشَاشِ وَالْكَتَدِ، أَجْرَدُ، ذُو مَسْرُبَةٍ، شَثْنُ الْكَفَّيْنِ وَالْقَدَمَيْنِ، إِذَا مَشَى تَقَلَّعَ كَأَنَّمَا يَمْشِي فِي صَبَبٍ، وَإِذَا الْتَفَتَ الْتَفَتَ مَعًا، بَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ وَهُوَ خَاتَمُ النَّبِيِّينَ، أَجْوَدُ النَّاسِ صَدْرًا، وَأَصْدَقُ النَّاسِ لَهْجَةً، وَأَلْيَنُهُمْ عَرِيكَةً، وَأَكْرَمُهُمْ عِشْرَةً، مَنْ رَآهُ بَدِيهَةً هَابَهُ، وَمَنْ خَالَطَهُ مَعْرِفَةً أَحَبَّهُ، يَقُولُ نَاعِتُهُ: لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ)യെ വിശേഷിപ്പിക്കുമ്പോൾ അലി(റ) ഇപ്രകാരം പറയുമായിരുന്നു: നബി(സ) വളരെയധികം നീണ്ടവരോ പറ്റെ കുറിയവരോ അല്ല. അവിടുന്ന് ജനങ്ങളിൽ ഒത്തവലിപ്പമുള്ള ആളായിരുന്നു. അവിടുന്ന് കൂടുതൽ ചുരുണ്ട മുടിയുള്ളവരോ തീരെ ചുരുളാത്ത നീണ്ടുകിടക്കുന്ന മുടിയുള്ളവരോ ആയിരുന്നില്ല. മറിച്ച് അൽപം ചുരുണ്ട് നീണ്ടുകിടക്കുന്ന മുടിയുള്ളവരായിരുന്നു. അവിടുന്ന് തടിച്ചുകൊഴുത്തവരോ ഉരുണ്ട മുഖമുള്ളവരോ ആയിരുന്നില്ല. അവിടുത്തെ മുഖത്തിന് ചെറിയൊരു വൃത്താകൃതിയുണ്ടായിരുന്നു. അവിടുന്ന് ചുവപ്പ് കലർന്ന വെളുപ്പ് നിറമുള്ളവരായിരുന്നു. കണ്ണിലെ കറുപ്പ് അധികരിച്ചവരായിരുന്നു. കൺകോണുകൾ നീണ്ടവരായിരുന്നു. ചുമലിന്റെ അഗ്രങ്ങളും പിരടിയും വലുപ്പമുള്ളവരായിരുന്നു. രോമം കുറഞ്ഞവരായിരുന്നു. നെഞ്ചിൽ നിന്ന് പൊക്കിൾവരെ നീണ്ടുനിൽക്കുന്ന രോമമുള്ളവരായിരുന്നു. രണ്ടു കൈകളിലെയും കാലുകളിലെയും വിരലുകൾ വലുപ്പമുള്ളവരായിരുന്നു. നടക്കുമ്പോൾ ഇറക്കമുള്ള സ്ഥലത്തിലൂടെ നടക്കുംപോലെ അവിടുന്ന് കാൽ പറിച്ചുവെച്ച് നടക്കുമായിരുന്നു. തിരിഞ്ഞുനോക്കുമ്പോൾ ശരീരത്തെ മുഴുവൻ തിരിക്കുമായിരുന്നു. അവിടുത്തെ രണ്ട് ചുമലുകൾക്കിടയിൽ ഖാതമുന്നുബുവ്വത് (പ്രവാചകത്വത്തിന്റെ സീൽ) ഉണ്ടായിരുന്നു. അവിടുന്ന് പ്രവാചകന്മാരിൽ അവസാനത്തവരാണ്. ജനങ്ങളിൽ ഏറ്റവും വിശാല മനസ്കതയുള്ളവരാണ്. അവരുടെ കൂട്ടത്തിൽ ഏറ്റവും സത്യസന്ധമായ സംസാരശൈലിയുള്ളവരാണ്. അവിടുന്ന് ജനങ്ങളിൽ ഏറ്റവും ലോലമായ പ്രകൃതമുള്ളവരാണ്. ജനങ്ങളിൽവെച്ച് ഏറ്റവും മാന്യമായ പെരുമാറ്റമുള്ളവരാണ്. അവിടുത്തെ ആദ്യമായി കാണുന്നവർ പെട്ടെന്ന് പേടിച്ചുപോകും. അറിഞ്ഞുകൊണ്ട് അവിടത്തോട് ഇടപഴകുന്നവർ അവിടുത്തെ ഇഷ്ടപ്പെടും. അവിടുത്തെ വിശേഷിപ്പിക്കുന്നവർ പറയും: നബി(സ)ക്ക് മുമ്പോ ശേഷമോ അവിടത്തെപ്പോലുള്ള ഒരാളെ ഞാൻ കണ്ടിട്ടില്ല. (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ الْيَهُودَ جَاءُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ: أَنَّ رَجُلًا مِنْهُمْ وَامْرَأَةً زَنَيَا، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الرَّجْمِ؟" فَقَالُوا: نَفْضَحُهُمْ وَيُجْلَدُونَ، فَقَالَ عَبْدُاللَّهِ بْنُ سَلَامٍ: كَذَبْتُمْ، إِنَّ فِيهَا الرَّجْمَ. فَأَتَوْا بِالتَّوْرَاةِ فَنَشَرُوهَا، فَوَضَعَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ، فَقَرَأَ مَا قَبْلَهَا وَمَا بَعْدَهَا، فَقَالَ لَهُ عَبْدُاللَّهِ بْنُ سَلَامٍ: ارْفَعْ يَدَكَ، فَرَفَعَ يَدَهُ، فَإِذَا فِيهَا آيَةُ الرَّجْمِ، فَقَالُوا: صَدَقَ يَا مُحَمَّدُ، فِيهَا آيَةُ الرَّجْمِ. فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): തങ്ങളുടെ കൂട്ടത്തിൽപെട്ട ഒരു പുരുഷനും സ്ത്രീയും വ്യഭിചരിച്ചുവെന്ന വിവരം ജൂതന്മാർ റസൂൽ(സ)യോട് വന്ന് പറഞ്ഞു. റസൂൽ(സ) അവരോട് ചോദിച്ചു: എറിഞ്ഞുകൊല്ലുന്ന വിഷയത്തെക്കുറിച്ച് തൗറാത്തിൽ എന്താണുള്ളത്? അവർ പറഞ്ഞു: ഞങ്ങൾ അവരെ വഷളാക്കണമെന്നും അവർ അടിക്കപ്പെടണമെന്നുമാണുള്ളത്. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു സലാം(റ) പറഞ്ഞു: നിങ്ങൾ പറഞ്ഞത് കളവാണ്, എറിഞ്ഞുകൊല്ലണമെന്നാണ് തീർച്ചയായും അതിലുള്ളത്. അപ്പോൾ അവർ തൗറാത്ത് കൊണ്ടുവരികയും അത് തുറന്നുവെക്കുകയും ചെയ്തു. എറിഞ്ഞുകൊല്ലണമെന്ന് പറയുന്ന സൂക്തത്തിന്മേൽ അവരിലൊരാൾ കൈവെക്കുകയും അതിന് മുമ്പും ശേഷവുമുള്ള സൂക്തങ്ങൾ പാരായണം ചെയ്യുകയും ചെയ്തു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു സലാം(റ) അവനോട് പറഞ്ഞു: നിന്റെ കൈ ഉയർത്തുക. അയാൾ കൈ ഉയർത്തി. അപ്പോഴതാ അതിൽ എറിഞ്ഞുകൊല്ലുന്നതിനെ കുറിച്ചുള്ള സൂക്തം. ജൂതന്മാർ പറഞ്ഞു: മുഹമ്മദേ, അബ്ദുല്ല പറഞ്ഞത് സത്യമാണ്. എറിഞ്ഞുകൊല്ലുന്നതിനെക്കുറിച്ചുള്ള സൂക്തം അതിലുണ്ട്. അങ്ങനെ റസൂൽ(സ) കൽപിച്ചതനുസരിച്ച് ആ സ്ത്രീയെയും പുരുഷനെയും എറിഞ്ഞു. (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 345, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ النَّاسِ بِالْخَيْرِ، وَكَانَ أَجْوَدَ مَا يَكُونُ فِي شَهْرِ رَمَضَانَ، إِنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ كَانَ يَلْقَاهُ فِي كُلِّ سَنَةٍ فِي رَمَضَانَ حَتَّى يَنْسَلِخَ، فَيَعْرِضُ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقُرْآنَ، فَإِذَا لَقِيَهُ جِبْرِيلُ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ജനങ്ങളിൽവെച്ച് ഏറ്റവും ഉദാരമായി നന്മ ചെയ്യുന്നയാളായിരുന്നു. റമളാൻ മാസത്തിലായിരുന്നു അവിടുന്ന് കൂടുതൽ ഉദാരമായി നന്മ ചെയ്തിരുന്നത്. എല്ലാ വർഷവും റമളാനിൽ ആ മാസം കഴിയുംവരെ ജിബ്രീൽ(അ) റസൂൽ(സ)യെ കണ്ടുമുട്ടുകയും അവിടുന്ന് ജിബ്രീൽ(അ)മിന് ഖുർആൻ ഓതിക്കേൾപിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ജിബ്രീൽ(അ) തിരുമേനി(സ)യെ കണ്ടുമുട്ടുമ്പോൾ റസൂൽ(സ) തുറന്നുവിടപ്പെട്ട (നന്മ നിറഞ്ഞ) കാറ്റിനേക്കാൾ കൂടുതൽ ഉദാരമായി നന്മ ചെയ്യുന്നവരായിരുന്നു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ ابْنِ شِهَابٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ الْفَتْحِ فَتْحِ مَكَّةَ، ثُمَّ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَنْ مَعَهُ مِنَ الْمُسْلِمِينَ، فَاقْتَتَلُوا بِحُنَيْنٍ، فَنَصَرَ اللَّهُ دِينَهُ وَالْمُسْلِمِينَ، وَأَعْطَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ صَفْوَانَ بْنَ أُمَيَّةَ مِائَةً مِنَ النَّعَمِ، ثُمَّ مِائَةً، ثُمَّ مِائَةً. قَالَ ابْنُ شِهَابٍ: حَدَّثَنِي سَعِيدُ بْنُ الْمُسَيَّبِ أَنَّ صَفْوَانَ قَالَ: وَاللَّهِ لَقَدْ أَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَعْطَانِي، وَإِنَّهُ لَأَبْغَضُ النَّاسِ إِلَيَّ، فَمَا بَرِحَ يُعْطِينِي حَتَّى إِنَّهُ لَأَحَبُّ النَّاسِ إِلَيَّ. (م)', 'ഇബ്നുശിഹാബ്(റ): റസൂൽ(സ) മക്കാവിജയ ഘട്ടത്തിലുള്ള പോരാട്ടം നിർവ്വഹിച്ചു. ശേഷം തന്റെ കൂടെയുള്ള മുസ്ലിംകളോടൊന്നിച്ച് പുറപ്പെടുകയും അവർ ഹുനൈനിൽവെച്ച് പോരാടുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു തന്റെ ദീനിനെയും മുസ്ലിംകളെയും സഹായിച്ചു. അന്ന് റസൂൽ(സ) സ്വഫ്വാനുബ്നു ഉമയ്യത്(റ)വിന് നൂറ് ഒട്ടകങ്ങളെ നൽകി. പിന്നെയും നൂറ് ഒട്ടകങ്ങളെ നൽകി. പിന്നെയും നൂറ് ഒട്ടകങ്ങളെ നൽകി. ഇബ്നുശിഹാബ്(റ) പറയുന്നു: സഈദുബ്നുൽ മുസയ്യബ്(റ) എന്നോട് ഇപ്രകാരം പറഞ്ഞു: നിശ്ചയം സ്വഫ്വാൻ(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ)യെ ഞാൻ ജനങ്ങളിൽവെച്ച് ഏറ്റവും വെറുക്കുന്ന സമയത്താണ് അവിടുന്ന് എനിക്ക് ആ ദാനം നൽകിയത്. പിന്നീട് ജനങ്ങളിൽവെച്ച് അവിടുന്ന് എനിക്ക് ഏറ്റവും പ്രിയപ്പെട്ടവരായി മാറുന്നതുവരെ എനിക്ക് ദാനം നൽകിക്കൊണ്ടേയിരുന്നു. (മു)', 'ابْنِ شِهَابٍ', 'ഇബ്നുശിഹാബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 346, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ قَدْ جَاءَنَا مَالُ الْبَحْرَيْنِ، لَقَدْ أَعْطَيْتُكَ هَكَذَا وَهَكَذَا وَهَكَذَا". وَقَالَ بِيَدَيْهِ جَمِيعًا، فَقُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ يَجِيءَ مَالُ الْبَحْرَيْنِ، فَقَدِمَ عَلَى أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ بَعْدَهُ، فَأَمَرَ مُنَادِيًا فَنَادَى: مَنْ كَانَتْ لَهُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِدَةٌ أَوْ دَيْنٌ فَلْيَأْتِ. فَقُمْتُ فَقُلْتُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ قَدْ جَاءَنَا مَالُ الْبَحْرَيْنِ أَعْطَيْتُكَ هَكَذَا وَهَكَذَا وَهَكَذَا". فَحَثَى أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ مَرَّةً، ثُمَّ قَالَ لِي: عُدَّهَا، فَعَدَدْتُهَا فَإِذَا هِيَ خَمْسُ مِائَةٍ، فَقَالَ: خُذْ مِثْلَيْهَا. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ബഹ്റൈനിലെ സമ്പത്ത് നമ്മുടെ പക്കലെത്തിയാൽ ഞാൻ നിനക്ക് ഇത്രയും പിന്നെ ഇത്രയും പിന്നെ ഇത്രയും നൽകുക തന്നെചെയ്യും." തന്റെ ഇരു കൈകളും ചേർത്തു പിടിച്ചുകൊണ്ടാണ് അവിടുന്ന് അത് പറഞ്ഞത്. എന്നാൽ ബഹ്റൈനിലെ സമ്പത്ത് സ്ഥലത്തെത്തും മുമ്പ് നബി(സ) വഫാതായി. ശേഷം ജാബിർ(റ) അബൂബക്കർ(റ)വിന്റെ അടുത്ത് ചെന്നു. അപ്പോൾ അബൂബക്കർ(റ) ഒരാളെ ഇപ്രകാരം വിളിച്ചു പറയാൻ ചുമതലപ്പെടുത്തി: നബി(സ)യിൽ നിന്ന് വല്ല കടമോ വാഗ്ദാനമോ ലഭിക്കാനുള്ളവർ വന്നുകൊള്ളുക. ഉടനെ ഞാൻ എഴുന്നേറ്റു നിന്നുകൊണ്ട് പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറഞ്ഞിരുന്നു: "ബഹ്റൈനിലെ സമ്പത്ത് നമ്മുടെ പക്കലെത്തിയാൽ ഞാൻ നിനക്ക് ഇത്രയും പിന്നെ ഇത്രയും പിന്നെ ഇത്രയും നൽകും." അപ്പോൾ അബൂബക്കർ(റ) ഒരു പ്രാവശ്യം കോരി. ശേഷം എന്നോട് പറഞ്ഞു: അത് എത്രയുണ്ടെന്ന് എണ്ണിനോക്കുക. ഞാൻ എണ്ണിനോക്കുമ്പോൾ അത് അഞ്ഞൂറെണ്ണമുണ്ടായിരുന്നു. അബൂബക്കർ(റ) പറഞ്ഞു: അതിന്റെ രണ്ടിരട്ടികൂടി നീ എടുക്കുക. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَا سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا قَطُّ فَقَالَ: لَا. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): തന്നോട് ചോദിക്കപ്പെട്ട ഒരു കാര്യത്തിനും റസൂൽ(സ) ഒരിക്കലും ഇല്ല എന്ന് ഉത്തരം പറഞ്ഞിട്ടില്ല. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَنَمًا بَيْنَ جَبَلَيْنِ، فَأَعْطَاهُ إِيَّاهُ، فَأَتَى قَوْمَهُ، فَقَالَ: أَيْ قَوْمِ أَسْلِمُوا، فَوَاللَّهِ إِنَّ مُحَمَّدًا لَيُعْطِي عَطَاءً مَا يَخَافُ الْفَقْرَ. فَقَالَ أَنَسٌ: إِنْ كَانَ الرَّجُلُ لَيُسْلِمُ مَا يُرِيدُ إِلَّا الدُّنْيَا، فَمَا يُسْلِمُ حَتَّى يَكُونَ الْإِسْلَامُ أَحَبَّ إِلَيْهِ مِنَ الدُّنْيَا وَمَا عَلَيْهَا. (م)', 'അനസ്(റ): ഒരാൾ രണ്ടു പർവ്വതങ്ങൾക്കിടയിൽ നിറയെ ആടുകളെ റസൂൽ(സ)യോട് ആവശ്യപ്പെട്ടു. അവിടുന്ന് അയാൾക്കത് നൽകി. അപ്പോൾ അയാൾ തന്റെ സമൂഹത്തിന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ജനങ്ങളേ, നിങ്ങൾ ഇസ്ലാം സ്വീകരിക്കുക. അല്ലാഹുവാണ് സത്യം, നിശ്ചയമായും മുഹമ്മദ് ദാരിദ്ര്യം വരുന്നതുപോലും ഭയപ്പെടാതെ വളരെ കൂടുതലായി നൽകിക്കൊണ്ടിരിക്കുന്നു. അനസ്(റ) പറയുന്നു: ഐഹിക ലോകത്തെ കാര്യം മാത്രം ആഗ്രഹിച്ചുകൊണ്ട് ഒരു വ്യക്തി മുസ്ലിമാകുന്ന അവസ്ഥയുണ്ടായിരുന്നു. എന്നാൽ ഐഹിക ലോകത്തെക്കാളും അതിലുള്ള സർവ്വത്തെക്കാളും ഇസ്ലാം അവന് ഇഷ്ടപ്പെട്ടതാകുന്നതുവരെ അവൻ (യഥാർത്ഥ) മുസ്ലിമാവുകയില്ല. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 348, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَحْسَنِ النَّاسِ خُلُقًا، فَأَرْسَلَنِي يَوْمًا لِحَاجَةٍ فَقُلْتُ: وَاللَّهِ لَا أَذْهَبُ، وَفِي نَفْسِي أَنْ أَذْهَبَ لِمَا أَمَرَنِي بِهِ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجْتُ حَتَّى أَمُرَّ عَلَى صِبْيَانٍ، وَهُمْ يَلْعَبُونَ فِي السُّوقِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَبَضَ بِقَفَايَ مِنْ وَرَائِي، قَالَ: فَنَظَرْتُ إِلَيْهِ وَهُوَ يَضْحَكُ، فَقَالَ: "يَا أُنَيْسُ، أَذَهَبْتَ حَيْثُ أَمَرْتُكَ؟" قَالَ: قُلْتُ: نَعَمْ، أَنَا أَذْهَبُ يَا رَسُولَ اللَّهِ. قَالَ أَنَسٌ: وَاللَّهِ لَقَدْ خَدَمْتُهُ تِسْعَ سِنِينَ، مَا عَلِمْتُهُ قَالَ لِشَيْءٍ صَنَعْتُهُ: لِمَ فَعَلْتَ كَذَا وَكَذَا. أَوْ لِشَيْءٍ تَرَكْتُهُ: هَلَّا فَعَلْتَ كَذَا وَكَذَا. (م)', 'അനസ്(റ): റസൂൽ(സ) ജനങ്ങളിൽവെച്ച് ഏറ്റവും നല്ല സ്വഭാവമുള്ളവരായിരുന്നു. ഒരു ദിവസം അവിടുന്ന് എന്നെ ഒരു ആവശ്യത്തിനു വേണ്ടി പറഞ്ഞയച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാൻ പോവുകയില്ല. എന്നാൽ നബി(സ) കൽപിച്ച കാര്യത്തിന് പോകണമെന്ന് തന്നെയായിരുന്നു എന്റെ മനസ്സിലുണ്ടായിരുന്നത്. ശേഷം ഞാൻ പുറത്തുപോയി. അങ്ങനെ അങ്ങാടിയിൽ കളിച്ചുകൊണ്ടിരിക്കുകയായിരുന്ന കുറച്ച് കുട്ടികൾക്കടുത്തുകൂടെ ഞാൻ നടന്നു പോകുമ്പോൾ എന്റെ പിന്നിൽ നിന്ന് റസൂൽ(സ) എന്റെ പിരടിയിൽ പിടിച്ചു. അനസ്(റ) പറയുന്നു: ഞാൻ റസൂൽ(സ)യെ നോക്കി. അവിടുന്ന് ചിരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അവിടുന്ന് ചോദിച്ചു: "ഉനൈസേ (കൊച്ചു അനസേ), ഞാൻ പറഞ്ഞിടത്തേക്ക് നീ പോയോ?" അനസ്(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ പോവുകയാണ്. അനസ്(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം, ഒമ്പതു വർഷം ഞാൻ അവിടത്തേക്ക് സേവനം ചെയ്തിട്ടുണ്ട്. എന്നാൽ ഞാൻ പ്രവർത്തിച്ച ഒരു കാര്യത്തിന് ''എന്തിനാണ് നീ ഇങ്ങനെയെല്ലാം പ്രവർത്തിച്ചത്'' എന്നോ ഞാൻ ഉപേക്ഷിച്ച ഒരു കാര്യത്തിന് ''എന്തുകൊണ്ട് നീ ഇങ്ങനെയെല്ലാം ചെയ്തില്ല'' എന്നോ അവിടുന്ന് പറഞ്ഞതായി എന്റെ അറിവിലില്ല. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 348, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَبْدِاللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمْ يَكُنِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاحِشًا وَلَا مُتَفَحِّشًا، وَكَانَ يَقُولُ: "إِنَّ مِنْ خِيَارِكُمْ أَحْسَنَكُمْ أَخْلَاقًا". (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) നീചവൃത്തി ചെയ്യുന്നയാളോ, ദുസ്സ്വഭാവിയോ ആയിരുന്നില്ല. അവിടുന്ന് പറയുമായിരുന്നു: "നിങ്ങളിൽ ഏറ്റവും ഉൽകൃഷ്ട സ്വഭാവമുള്ളവർ നിങ്ങളിലെ ശ്രേഷ്ഠരിൽ പെട്ടവരാണ്." (ബു)', 'عَبْدِاللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 348, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا قَالَتْ: مَا خُيِّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلَّا أَخَذَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ إِلَّا أَنْ تُنْتَهَكَ حُرْمَةُ اللَّهِ، فَيَنْتَقِمَ لِلَّهِ بِهَا. (خ)', 'ആഇശ(റ): രണ്ടുകാര്യങ്ങളിൽ ഇഷ്ടമുള്ളതിനെ തെരഞ്ഞെടുക്കാനുള്ള അവകാശം റസൂൽ(സ)ക്ക് നൽകപ്പെട്ടാൽ ഒരു പാപമാകുന്നില്ലെങ്കിൽ അതിൽ ഏറ്റവും സുഖമമായതിനെ അവിടുന്ന് തെരഞ്ഞെടുക്കുമായിരുന്നു. അതൊരു പാപമാണെങ്കിൽ അതിൽനിന്ന് ഏറ്റവും കൂടുതൽ അകന്നു നിൽക്കുന്നതും റസൂൽ(സ) തന്നെയായിരിക്കും. അവിടുന്ന് സ്വന്തത്തിനു വേണ്ടി പ്രതികാരമെടുത്തിട്ടില്ല. അല്ലാഹുവിന്റെ വിധിവിലക്കുകൾ ലംഘിക്കപ്പെട്ടാലല്ലാതെ. അങ്ങനെ വന്നാൽ അല്ലാഹുവിനുവേണ്ടി അവിടുന്ന് പ്രതികാരമെടുക്കും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا عَابَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا قَطُّ، إِنِ اشْتَهَاهُ أَكَلَهُ وَإِلَّا تَرَكَهُ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു ഭക്ഷണത്തെയും തീരെ കുറ്റം പറഞ്ഞിട്ടില്ല. അവിടുന്നത് ആഗ്രഹിച്ചാൽ ഭക്ഷിക്കും. ഇല്ലെങ്കിൽ ഉപേക്ഷിക്കും. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أَعْرَابِيٍّ يَعُودُهُ، قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ عَلَى مَرِيضٍ يَعُودُهُ قَالَ: "لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ". فَقَالَ لَهُ: "لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ". قَالَ: قُلْتَ طَهُورٌ، كَلَّا بَلْ هِيَ حُمَّى تَفُورُ أَوْ تَثُورُ عَلَى شَيْخٍ كَبِيرٍ تُزِيرُهُ الْقُبُورَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَنَعَمْ إِذًا". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) സന്ദർശനാവശ്യാർത്ഥം ഒരു അഅ്റാബിയുടെ അടുത്ത് ചെന്നു. നിവേദകൻ പറയുന്നു: അവിടുന്ന് ഏതെങ്കിലും രോഗിയെ സന്ദർശിക്കാൻ ചെന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "പ്രശ്നമാക്കേണ്ട, അല്ലാഹു ഉദ്ദേശിക്കുന്നപക്ഷം അത് സുഖപ്പെടും." നബി(സ) ആ അഅ്റാബിയോട് പറഞ്ഞു: "പ്രശ്നമാക്കേണ്ട, അല്ലാഹു ഉദ്ദേശിക്കുന്നപക്ഷം അത് സുഖപ്പെടും." അഅ്റാബി പറഞ്ഞു: സുഖപ്പെടുന്നതാണെന്നാണോ അങ്ങ് പറഞ്ഞത്. ഒരിക്കലും അപ്രകാരമല്ല. അത് വൃദ്ധന്മാർക്ക് പിടിപെടുന്ന അല്ലെങ്കിൽ പടർന്നുപിടിക്കുന്ന ഒരുതരം പനിയാണ്. അത് അവരെ ഖബറിലേക്ക് കൊണ്ടെത്തിക്കും (മരിപ്പിക്കും). അപ്പോൾ നബി(സ) പറഞ്ഞു: "അങ്ങനെയെങ്കിൽ അങ്ങനെത്തന്നെ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ شَقِيقٍ أَبِي وَائِلٍ قَالَ: كَانَ عَبْدُ اللَّهِ يُذَكِّرُنَا كُلَّ يَوْمٍ خَمِيسٍ، فَقَالَ لَهُ رَجُلٌ: يَا أَبَا عَبْدِ الرَّحْمَنِ إِنَّا نُحِبُّ حَدِيثَكَ وَنَشْتَهِيهِ، وَلَوَدِدْنَا أَنَّكَ حَدَّثْتَنَا كُلَّ يَوْمٍ. فَقَالَ: مَا يَمْنَعُنِي أَنْ أُحَدِّثَكُمْ إِلَّا كَرَاهِيَةَ أَنْ أُمِلَّكُمْ، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الْأَيَّامِ، كَرَاهِيَةَ السَّآمَةِ عَلَيْنَا. (م)', 'ശഖീഖ് അബൂവാഇൽ(റ): അബ്ദുല്ല(റ) എല്ലാ വ്യാഴാഴ്ച ദിവസവും ഞങ്ങൾക്ക് ഉപദേശം നൽകാറുണ്ടായിരുന്നു. അങ്ങനെയിരിക്കെ ഒരാൾ അദ്ദേഹത്തോട് പറഞ്ഞു: അബുഅബ്ദുറഹ്മാനേ, ഞങ്ങൾ താങ്കളുടെ സംസാരം ഇഷ്ടപ്പെടുകയും അത് കൊതിക്കുകയും ചെയ്യുന്നു. ദിവസവും അങ്ങ് ഞങ്ങളോട് സംസാരിച്ചിരുന്നെങ്കിലെന്ന് ഞങ്ങൾ ആശിക്കുന്നു. അബ്ദുല്ല(റ) പറഞ്ഞു: നിങ്ങളെ മടുപ്പിക്കാൻ ഇഷ്ടപ്പെടാത്തതുകൊണ്ട് മാത്രമാണ് ഞാൻ സംസാരിക്കാതിരിക്കുന്നത്. റസൂൽ(സ) ഞങ്ങൾക്ക് മടുപ്പ് വരുമോ എന്ന് പേടിച്ച് ഞങ്ങളെ ഉപദേശിക്കാൻ പ്രത്യേക ദിവസങ്ങൾ കണ്ടെത്തുമായിരുന്നു. (മു)', 'شَقِيقٍ أَبِي وَائِلٍ قَالَ', 'ശഖീഖ് അബൂവാഇൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ أَحَدًا كَانَ أَرْحَمَ [النَّاسِ] بِالْعِيَالِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: كَانَ إِبْرَاهِيمُ مُسْتَرْضِعًا لَهُ فِي عَوَالِي الْمَدِينَةِ، فَكَانَ يَنْطَلِقُ وَنَحْنُ مَعَهُ فَيَدْخُلُ الْبَيْتَ وَإِنَّهُ لَيُدَّخَنُ، وَكَانَ ظِئْرُهُ قَيْنًا، فَيَأْخُذُهُ فَيُقَبِّلُهُ، ثُمَّ يَرْجِعُ. قَالَ عَمْرٌو: فَلَمَّا تُوُفِّيَ إِبْرَاهِيمُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ إِبْرَاهِيمَ ابْنِي، وَ[إِنَّهُ] مَاتَ فِي الثَّدْيِ، وَإِنَّ لَهُ لَظِئْرَيْنِ تُكَمِّلَانِ رَضَاعَهُ فِي الْجَنَّةِ". (م)', 'അനസുബ്നു മാലിക്(റ): ജനങ്ങളിൽ ആശ്രിതരോട് റസൂൽ(സ)യോളം കരുണ ചെയ്യുന്ന ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. അനസ്(റ) പറയുന്നു: ഇബ്റാഹീ(റസൂൽ(സ)യുടെ പുത്രൻ)മിന് മുലകൊടുക്കാൻ വേണ്ടി റസൂൽ(സ) മദീനയിലെ ഉയർന്ന പ്രദേശത്ത് (ഒരു കുടുംബത്തെ) ഏൽപിച്ചിരുന്നു. റസൂൽ(സ) അവിടെ പോകുമ്പോൾ ഞങ്ങളും അവിടുത്തോടൊപ്പം കൂടുമായിരുന്നു. തിരുമേനി(സ) ആ വീട്ടിൽ പ്രവേശിക്കുമ്പോൾ അവിടെ പുക നിറഞ്ഞിട്ടുണ്ടാകുമായിരുന്നു. കാരണം മുലകൊടുക്കുന്ന സ്ത്രീയുടെ ഭർത്താവ് കൊല്ലനായിരുന്നു. അങ്ങനെ റസൂൽ(സ) ഇബ്റാഹീമിനെ എടുക്കുകയും ചുംബിക്കുകയും ചെയ്യും. ശേഷം മടങ്ങിപ്പോരും. അംറ്(റ) പറയുന്നു: ഇബ്റാഹീം വഫാതായപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇബ്റാഹീം എന്റെ പുത്രനാണ്. മുലകുടിക്കുമ്പോഴാണ് അവൻ മരിച്ചത്. അവന്റെ മുലകുടിയെ പൂർത്തീകരിക്കുന്ന, മുലകുടി ബന്ധത്തിലുള്ള രണ്ടു മാതാപിതാക്കൾ തീർച്ചയായും അവന് സ്വർഗ്ഗത്തിലുണ്ടായിരിക്കുന്നതാണ്." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'إِنَّهُ', null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ الْأَقْرَعَ بْنَ حَابِسٍ أَبْصَرَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُ الْحَسَنَ، فَقَالَ: إِنَّ لِي عَشَرَةً مِنَ الْوَلَدِ، مَا قَبَّلْتُ وَاحِدًا مِنْهُمْ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ مَنْ لَا يَرْحَمْ لَا يُرْحَمْ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) ഹസൻ(റ)വിനെ ചുംബിക്കുന്നത് അഖ്റഉബ്നു ഹാബിസ്(റ) കണ്ടു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: എനിക്ക് പത്തു സന്താനങ്ങളുണ്ട്. അവരിൽ ഒരാളെയും ഞാൻ ചുംബിക്കാറില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം കരുണ ചെയ്യാത്തവനോട് കരുണ ചെയ്യപ്പെടുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، وَغُلَامٌ أَسْوَدُ يُقَالُ لَهُ أَنْجَشَةُ يَحْدُو، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَنْجَشَةُ، رُوَيْدَكَ سَوْقًا بِالْقَوَارِيرِ". (م)', 'അനസ്(റ): റസൂൽ(സ) ഒരു യാത്രയിലായിരിക്കെ അൻജഷ എന്നു പേരുള്ള ഒരു കറുത്ത അടിമ തന്റെ ഒട്ടകത്തെ പാട്ടുപാടിക്കൊണ്ട് തെളിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അൻജഷ, പളുങ്കുകളുമായി (സ്ത്രീയുമായി) സൗമ്യതയോടെ വാഹനമോടിക്കുക." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ النَّاسِ، وَكَانَ أَجْوَدَ النَّاسِ، وَكَانَ أَشْجَعَ النَّاسِ. وَلَقَدْ فَزِعَ أَهْلُ الْمَدِينَةِ ذَاتَ لَيْلَةٍ، فَانْطَلَقَ نَاسٌ قِبَلَ الصَّوْتِ، فَتَلَقَّاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاجِعًا، وَقَدْ سَبَقَهُمْ إِلَى الصَّوْتِ، وَهُوَ عَلَى فَرَسٍ لِأَبِي طَلْحَةَ عُرْيٍ فِي عُنُقِهِ السَّيْفُ، وَهُوَ يَقُولُ: "لَمْ تُرَاعُوا، لَمْ تُرَاعُوا". قَالَ: "وَجَدْنَاهُ بَحْرًا. أَوْ: إِنَّهُ لَبَحْرٌ". قَالَ: وَكَانَ فَرَسًا يُبَطَّأُ. (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ജനങ്ങളിൽ ഏറ്റവും നല്ലവരായിരുന്നു. അവിടുന്ന് ജനങ്ങളിൽ ഏറ്റവും ധർമ്മിഷ്ടരായിരുന്നു. ജനങ്ങളിൽ ഏറ്റവും വലിയ ധീരരായിരുന്നു. ഒരു രാത്രി മദീനാ നിവാസികളെല്ലാം (ഒരു ശബ്ദം കേട്ട്) ഭയവിഹ്വലരായി. അങ്ങനെ ചിലർ ആ ശബ്ദം കേട്ട ഭാഗത്തേക്ക് ചെന്നു. അപ്പോൾ റസൂൽ(സ) അവിടെനിന്ന് മടങ്ങി വരുന്നത് അവർ കണ്ടു. പിരടിയിൽ വാൾ തൂക്കിയിട്ട്, അബൂത്വൽഹ(റ)വിന്റെ ജീനിയിട്ടിട്ടില്ലാത്ത ഒരു കുതിരയുടെ പുറത്തു കയറി, ജനങ്ങൾക്കു മുമ്പുതന്നെ റസൂൽ(സ) ആ ശബ്ദം കേട്ട ഭാഗത്തെത്തിയിട്ടുണ്ടായിരുന്നു. തിരുമേനി(സ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: "നിങ്ങൾ പേടിക്കേണ്ടതില്ല, നിങ്ങൾ പേടിക്കേണ്ടതില്ല." ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നന്നായി ഓടുന്നതായിട്ടാണ് നാമിതിനെ (കുതിരയെ) കണ്ടത്, അല്ലെങ്കിൽ: ഇത് നന്നായി ഓടുന്നതാണ്." നിവേദകൻ പറയുന്നു: അത് മുമ്പ് വളരെ പതുക്കെ സഞ്ചരിച്ചിരുന്ന കുതിരയായിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 350, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَلَغَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَصْحَابِهِ شَيْءٌ، فَخَطَبَ فَقَالَ: "عُرِضَتْ عَلَيَّ الْجَنَّةُ وَالنَّارُ، فَلَمْ أَرَ كَالْيَوْمِ فِي الْخَيْرِ وَالشَّرِّ، وَلَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا". قَالَ: فَمَا أَتَى عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمٌ أَشَدُّ مِنْهُ. قَالَ: غَطَّوْا رُءُوسَهُمْ وَلَهُمْ خَنِينٌ، قَالَ: فَقَامَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: رَضِينَا بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا. قَالَ: فَقَامَ ذَاكَ الرَّجُلُ فَقَالَ: مَنْ أَبِي؟ قَالَ: "أَبُوكَ فُلَانٌ". فَنَزَلَتْ هَذِهِ الْآيَةُ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ} [المائدة: ١٠١]. (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യുടെ അടുത്ത് തന്റെ അനുചരരെക്കുറിച്ച് എന്തോ വാർത്തയെത്തി. ഉടനെ തിരുമേനി(സ) പ്രസംഗിക്കാൻ നിൽക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "എനിക്ക് സ്വർഗ്ഗവും നരകവും കാണിക്കപ്പെട്ടു. നന്മയിലും തിന്മയിലും ഈ ദിവസം പോലുള്ള ഒരു ദിവസവും ഞാൻ കണ്ടിട്ടില്ല. ഞാൻ അറിയുന്ന കാര്യങ്ങൾ നിങ്ങൾ അറിയുകയാണെങ്കിൽ നിങ്ങൾ വളരെ കുറച്ചു മാത്രം ചിരിക്കുകയും കൂടുതലായി കരയുകയും ചെയ്യും." നിവേദകൻ പറയുന്നു: ആ ദിവസത്തോളം പ്രയാസകരമായ ഒരു ദിവസവും റസൂൽ(സ)യുടെ അനുചരന്മാർ അഭിമുഖീകരിച്ചിട്ടില്ല. അവരെല്ലാം തേങ്ങിക്കരഞ്ഞുകൊണ്ട് തങ്ങളുടെ തലകൾ താഴ്ത്തിയിരുന്നു. നിവേദകൻ പറയുന്നു: ഉടനെ ഉമറുബ്നുൽ ഖത്വാബ്(റ) എഴുന്നേറ്റുകൊണ്ട് പറഞ്ഞു: ഞങ്ങൾ അല്ലാഹുവിനെ രക്ഷിതാവായും ഇസ്ലാമിനെ മതമായും മുഹമ്മദ്(സ)യെ നബിയായും തൃപ്തിപ്പെട്ടിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ ആ വ്യക്തി എഴുന്നേറ്റ് നിന്നുകൊണ്ട് ചോദിച്ചു: ആരാണ് എന്റെ പിതാവ്? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പിതാവ് ഇന്ന വ്യക്തിയാണ്." അപ്പോഴാണ് ഈ സൂക്തം അവതരിച്ചത്: ''അല്ലയോ സത്യവിശ്വാസികളേ, വ്യക്തമാക്കപ്പെടുമ്പോൾ നിങ്ങൾക്ക് വിഷമമാകുന്ന കാര്യങ്ങളെക്കുറിച്ച് നിങ്ങൾ ചോദിക്കരുത്.'' (മാഇദ: 101) (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'المائدة: ١٠١', null, 351, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَعْظَمَ الْمُسْلِمِينَ فِي الْمُسْلِمِينَ جُرْمًا مَنْ سَأَلَ عَنْ شَيْءٍ لَمْ يُحَرَّمْ عَلَى الْمُسْلِمِينَ، فَحُرِّمَ عَلَيْهِمْ مِنْ أَجْلِ مَسْأَلَتِهِ". (م)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകൾക്ക് നിഷിദ്ധമാക്കപ്പെട്ടിട്ടില്ലാത്ത ഒരു കാര്യത്തെക്കുറിച്ച് ചോദിക്കുകയും ആ ചോദ്യം കാരണം മുസ്ലിംകൾക്ക് അത് നിഷിദ്ധമാക്കപ്പെടുകയും ചെയ്ത വ്യക്തിയാണ് മുസ്ലിംകളിൽ വെച്ച് ഏറ്റവും വലിയ പാപം ചെയ്തവൻ." (മു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 351, 352, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، أَيْنَ أَبِي؟ قَالَ: "فِي النَّارِ". فَلَمَّا قَفَّى دَعَاهُ فَقَالَ: "إِنَّ أَبِي وَأَبَاكَ فِي النَّارِ". (م)', 'അനസ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവ് എവിടെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "നരകത്തിൽ." നിവേദകൻ പറയുന്നു: ആ മനുഷ്യൻ തിരിഞ്ഞ് നടന്നപ്പോൾ റസൂൽ(സ) അയാളെ വിളിച്ചുകൊണ്ട് പറഞ്ഞു: "എന്റെ പിതാവും നിന്റെ പിതാവും നരകത്തിലാണ്."³ (മു)', 'أَنَسٍ', 'അനസ്(റ)', '³. നബി(സ)', null, array['م']::text[], array['മു']::text[], null, null, 352, 352, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ نَصْرَانِيًّا فَأَسْلَمَ وَقَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ، فَكَانَ يَكْتُبُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَادَ نَصْرَانِيًّا، فَكَانَ يَقُولُ: مَا يَدْرِي مُحَمَّدٌ إِلَّا مَا كَتَبْتُ لَهُ. فَأَمَاتَهُ اللَّهُ، فَدَفَنُوهُ فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الْأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ، لَمَّا هَرَبَ مِنْهُمْ نَبَشُوا عَنْ صَاحِبِنَا فَأَلْقَوْهُ، فَحَفَرُوا لَهُ فَأَعْمَقُوا، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الْأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ نَبَشُوا عَنْ صَاحِبِنَا لَمَّا هَرَبَ مِنْهُمْ فَأَلْقَوْهُ خَارِجَ الْقَبْرِ، فَحَفَرُوا لَهُ وَأَعْمَقُوا لَهُ فِي الْأَرْضِ مَا اسْتَطَاعُوا، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الْأَرْضُ، فَعَلِمُوا أَنَّهُ لَيْسَ مِنَ النَّاسِ فَأَلْقَوْهُ. (خ)', 'അനസ്(റ): ക്രിസ്ത്യാനിയായ ഒരു മനുഷ്യനുണ്ടായിരുന്നു. അയാൾ മുസ്ലിമാവുകയും അൽബഖറ സൂറത്തും ആലുഇംറാൻ സൂറത്തും പാരായണം ചെയ്യുകയും ചെയ്തു. അയാൾ നബി(സ)ക്ക് എഴുതിക്കൊടുക്കാറുണ്ടായിരുന്നു. പിന്നെയും അയാൾ ക്രിസ്ത്യാനിയായി. അപ്പോൾ അയാൾ ഇങ്ങനെ പറയുമായിരുന്നു: ഞാൻ എഴുതിക്കൊടുത്ത കാര്യങ്ങളല്ലാതെ ഒന്നുംതന്നെ മുഹമ്മദിന് അറിയുകയില്ല. പിന്നീട് അല്ലാഹു അയാളെ മരിപ്പിച്ചു. ജനങ്ങൾ അയാളെ മറവുചെയ്തു. എന്നാൽ നേരം പുലർന്നപ്പോഴേക്കും ഭൂമി അയാളെ പുറം തള്ളിയിരുന്നു. അപ്പോൾ ജനങ്ങൾ പറഞ്ഞു: ഇത് മുഹമ്മദിന്റെയും അവന്റെ അനുചരരുടെയും ചെയ്തിയാണ്. ഞങ്ങളുടെയാൾ അവരുടെ കൂട്ടത്തിൽ നിന്നും പിന്തിരിഞ്ഞപ്പോൾ അവർ അവന്റെ ഖബർ മാന്തുകയും അവനെ പുറത്തിടുകയും ചെയ്തു. ശേഷം അവർ അയാൾക്കുവേണ്ടി കൂടുതൽ ആഴത്തിൽ ഖബർ കുഴിച്ചു. എന്നാൽ നേരം പുലർന്നപ്പോഴേക്കും ഭൂമി അവനെ പുറംതള്ളി. അപ്പോഴും ജനങ്ങൾ പറഞ്ഞു: ഇത് മുഹമ്മദിന്റെയും അവന്റെ അനുചരരുടെയും ചെയ്തിയാണ്. ഞങ്ങളുടെയാൾ അവരുടെ കൂട്ടത്തിൽ നിന്നും പിന്തിരിഞ്ഞതിന്റെ പേരിൽ അവർ അവന്റെ ഖബർ മാന്തുകയും അവനെ പുറത്തിടുകയും ചെയ്തിരിക്കുന്നു. ശേഷം അവർ അവനുവേണ്ടി ഖബർ കുഴിക്കുകയും അവർക്ക് സാധിക്കുംവിധം ആഴം കൂട്ടുകയും ചെയ്തു. എന്നാൽ നേരം പുലർന്നപ്പോഴേക്കും ഭൂമി അവനെ പുറംതള്ളി. ഇത് ജനങ്ങൾ ചെയ്യുന്നതല്ലെന്ന് അപ്പോൾ അവർക്ക് മനസ്സിലാവുകയും അവർ അവനെ പുറത്ത് ഉപേക്ഷിക്കുകയും ചെയ്തു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 352, 352, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكُمْ مِنْ أَنْمَاطٍ". قُلْتُ: وَأَنَّى يَكُونُ لَنَا الْأَنْمَاطُ؟ قَالَ: "أَمَا إِنَّهُ سَيَكُونُ لَكُمُ الْأَنْمَاطُ". فَأَنَا أَقُولُ لَهَا: أَخِّرِي عَنِّي أَنْمَاطَكِ، فَتَقُولُ: أَلَمْ يَقُلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهَا سَتَكُونُ لَكُمُ الْأَنْمَاطُ، فَأَدَعُهَا. (خ)', 'ജാബിർ(റ): നബി(സ) ഒരിക്കൽ ചോദിച്ചു: "നിങ്ങൾക്ക് തൊങ്ങലുള്ള വിരിപ്പുകളുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഞങ്ങൾക്കെവിടെ നിന്നാണ് തൊങ്ങലുള്ള വിരിപ്പുകൾ ലഭിക്കുക. നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് തൊങ്ങലുള്ള വിരിപ്പുകൾ പിന്നീട് ലഭിക്കും." ഇപ്പോൾ (കാലങ്ങൾക്കു ശേഷം) ഞാൻ എന്റെ ഭാര്യയോട് പറയുന്നു: നീ നിന്റെ ഈ തൊങ്ങലുള്ള വിരിപ്പുകൾ എന്റെ അടുത്തുനിന്ന് നീക്കം ചെയ്യുക. അപ്പോൾ അവൾ പറയുന്നു: "ശേഷം നിങ്ങൾക്ക് തൊങ്ങലുള്ള വിരിപ്പുകൾ ഉണ്ടാവു"മെന്ന് റസൂൽ(സ) പറഞ്ഞിട്ടില്ലേ? പിന്നെ ഞാനവളോടൊന്നും പറയില്ല. (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 352, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ، فَقَالَ الْأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ. فَأَبَى عَلَيْهِمْ، فَاخْتَصَمُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ: "اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ". فَغَضِبَ الْأَنْصَارِيُّ فَقَالَ: يَا رَسُولَ اللَّهِ، أَنْ كَانَ ابْنَ عَمَّتِكَ؟ فَتَلَوَّنَ وَجْهُ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "يَا زُبَيْرُ اسْقِ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ". فَقَالَ الزُّبَيْرُ: وَاللَّهِ إِنِّي لَأَحْسِبُ هَذِهِ الْآيَةَ نَزَلَتْ فِي ذَلِكَ: {فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ} الْآيَةَ. (م)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഈത്തപ്പനത്തോട്ടത്തിൽ വെള്ളം നനച്ചിരുന്ന, ഹർറയിലെ (ചരൽ പ്രദേശത്തെ) നീർചാലിന്റെ വിഷയത്തിൽ അൻസാരികളിലൊരാൾ സുബൈർ(റ)വുമായി റസൂൽ(സ)യുടെ സന്നിധിയിൽവെച്ച് തർക്കത്തിലേർപ്പെട്ടു. അൻസാരി പറഞ്ഞു: നീ വെള്ളത്തെ ഒഴുക്കിവിടുക. എന്നാൽ സുബൈർ(റ) അവർക്ക് അത് സമ്മതിച്ചു കൊടുത്തില്ല. അങ്ങനെ റസൂൽ(സ)യുടെ സന്നിധിയിൽവെച്ച് അവർ തർക്കത്തിലേർപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) സുബൈർ(റ)വിനോട് പറഞ്ഞു: "സുബൈറേ, നീ വെള്ളം നനക്കുക, ശേഷം നിന്റെ അയൽവാസിയിലേക്കും വെള്ളം ഒഴുക്കുക." ഇതു കേട്ടപ്പോൾ അൻസാരിക്ക് ദേഷ്യംപിടിച്ചു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അദ്ദേഹം അങ്ങയുടെ പിതൃവ്യപുത്രനായതു കൊണ്ടാണോ (ഈ തീരുമാനം)? ഉടനെ റസൂൽ(സ)യുടെ മുഖം വിവർണ്ണമായി, അവിടുന്ന് പറഞ്ഞു: "സുബൈറേ, നീ നക്കുക, ശേഷം മതിൽകെട്ടിലേക്ക് തന്നെ മടങ്ങുംവിധം വെള്ളം തടഞ്ഞുവെക്കുക." സുബൈർ(റ) പറയുന്നു: ''ഇല്ല നബിയേ, അങ്ങയുടെ രക്ഷിതാവ് തന്നെയാണ് സത്യം, അങ്ങയെ വിധികർത്താവാക്കുംവരെ അവർ സത്യവിശ്വാസികളാവുകയില്ല'' എന്ന സൂക്തം ഈ വിഷയത്തിൽ അവതരിച്ചതാണെന്നാണ് എന്റെ അഭിപ്രായം. (മു)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَافْعَلُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ، وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ". (م)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം റസൂൽ(സ) പറയുന്നതായി കേട്ടു: "ഞാൻ നിങ്ങൾക്ക് നിരോധിച്ച കാര്യങ്ങളെ നിങ്ങൾ വെടിയുക. ഞാൻ കൽപിച്ച കാര്യങ്ങൾ കഴിയുംവിധം നിങ്ങൾ പ്രവർത്തിക്കുക. നിശ്ചയം നിങ്ങളുടെ മുമ്പുള്ള സമൂഹങ്ങളെ നശിപ്പിച്ചത് അവരുടെ ചോദ്യങ്ങളുടെ ആധിക്യവും തങ്ങളുടെ പ്രവാചകന്മാരോടുള്ള അവരുടെ അഭിപ്രായ വ്യത്യാസവുമായിരുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَرْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَوْمٍ عَلَى رُءُوسِ النَّخْلِ، فَقَالَ: "مَا يَصْنَعُ هَؤُلَاءِ". فَقَالُوا: يُلَقِّحُونَهُ: يَجْعَلُونَ الذَّكَرَ فِي الْأُنْثَى فَيَلْقَحُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَظُنُّ يُغْنِي ذَلِكَ شَيْئًا". قَالَ: فَأُخْبِرُوا بِذَلِكَ فَتَرَكُوهُ، فَأُخْبِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، فَقَالَ: "إِنْ كَانَ يَنْفَعُهُمْ ذَلِكَ فَلْيَصْنَعُوهُ، فَإِنِّي إِنَّمَا ظَنَنْتُ ظَنًّا، فَلَا تُؤَاخِذُونِي بِالظَّنِّ، وَلَكِنْ إِذَا حَدَّثْتُكُمْ عَنِ اللَّهِ شَيْئًا فَخُذُوا بِهِ، فَإِنِّي لَنْ أَكْذِبَ عَلَى اللَّهِ عَزَّ وَجَلَّ". (م)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): ഈത്തപ്പനകൾക്കു മുകളിൽ കയറിയ ചില ആളുകൾക്കു സമീപത്തുകൂടെ റസൂൽ(സ)യോടൊപ്പം ഞാൻ നടന്നുപോയി. തിരുമേനി(സ) ചോദിച്ചു: "ഇവരെന്താണ് ചെയ്യുന്നത്?" ജനങ്ങൾ പറഞ്ഞു: അവർ അവയെ (ഈത്തപ്പനകളെ) പരാഗണം ചെയ്യിക്കുകയാണ്. ആൺവർഗ്ഗത്തെ അവർ പെൺവർഗ്ഗത്തോട് ചേർക്കും. അപ്പോൾ അത് പരാഗണം നടന്നതാകും. റസൂൽ(സ) പറഞ്ഞു: "അതുകൊണ്ട് വല്ല ഉപകാരവുമുണ്ടെന്ന് എനിക്ക് തോന്നുന്നില്ല." നിവേദകൻ പറയുന്നു: ഈ വിവരം ആ ജനങ്ങളോട് പറയപ്പെടുകയും അവർ ആ ജോലി ഉപേക്ഷിക്കുകയും ചെയ്തു. ആ വിവരം റസൂൽ(സ) അറിഞ്ഞു. അവിടുന്ന് പറഞ്ഞു: "തങ്ങൾക്ക് ഉപകരിക്കുന്നതാണെങ്കിൽ അവർ അത് ചെയ്തുകൊള്ളട്ടെ. നിശ്ചയം ഞാൻ എന്റെ ഒരു ഊഹം പറഞ്ഞതാണ്. ഒരു ഊഹത്തിന്റെ പേരിൽ നിങ്ങൾ എന്നെ കുറ്റപ്പെടുത്തരുത്. എന്നാൽ അല്ലാഹുവിനെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് വല്ലതും പറഞ്ഞുതരുന്നുവെങ്കിൽ നിങ്ങൾ അത് സ്വീകരിക്കുക. നിശ്ചയം ഞാൻ അല്ലാഹുവിന്റെ പേരിൽ കളവ് പറയുകയില്ല." (മു)', 'طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسُ مُحَمَّدٍ فِي يَدِهِ، لَيَأْتِيَنَّ عَلَى أَحَدِكُمْ يَوْمٌ وَلَا يَرَانِي، ثُمَّ لَأَنْ يَرَانِي أَحَبُّ إِلَيْهِ مِنْ أَهْلِهِ وَمَالِهِ مَعَهُمْ". قَالَ أَبُو إِسْحَقَ – يَعْنِي ابْنَ مُحَمَّدِ بْنِ سُفْيَانَ –: الْمَعْنَى فِيهِ عِنْدِي: لَأَنْ يَرَانِي مَعَهُمْ أَحَبُّ إِلَيْهِ مِنْ أَهْلِهِ وَمَالِهِ، وَهُوَ عِنْدِي مُقَدَّمٌ وَمُؤَخَّرٌ. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഹമ്മദിന്റെ ആത്മാവ് ആരുടെ നിയന്ത്രണത്തിലാണോ അവൻതന്നെ സത്യം, നിങ്ങളിൽ ഓരോരുത്തന്നും ഒരു ദിവസം വരാനുണ്ട്. അന്ന് അവൻ എന്നെ കാണുകയില്ല. എന്നാൽ എന്നെ കാണുന്നതായിരിക്കും തന്റെ മുഴുവൻ കുടുംബത്തെക്കാളും സമ്പത്തിനെക്കാളും കൂടുതൽ അവന് തൃപ്തികരം." അബൂഇസ്ഹാഖ്(റ) - ഇബ്നുമുഹമ്മദുബ്നു സുഫ്യാൻ - പറയുന്നു: എന്റെ അഭിപ്രായത്തിൽ ഈ ഹദീസിന്റെ അർത്ഥം ഇപ്രകാരമാണ്: അവരോടൊന്നിച്ച് അവൻ എന്നെ കാണൽ തന്റെ കുടുംബത്തെക്കാളും സമ്പത്തിനെക്കാളും അവന് തൃപ്തികരമായിരിക്കും (എന്നാൽ അവൻ എന്നെ കാണുകയില്ല). എന്റെ അഭിപ്രായമനുസരിച്ച് ഹദീസിൽ വാക്കുകൾ മുന്തിക്കപ്പെടുകയും പിന്തിക്കപ്പെടുകയും ചെയ്തിരിക്കുകയാണ്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مِنْ أَشَدِّ أُمَّتِي لِي حُبًّا نَاسٌ يَكُونُونَ بَعْدِي، يَوَدُّ أَحَدُهُمْ لَوْ رَآنِي بِأَهْلِهِ وَمَالِهِ". (م)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽവെച്ച് എന്നെ ഏറ്റവും ശക്തമായി സ്നേഹിക്കുന്നത് എനിക്കുശേഷം വരുന്ന ഒരു കൂട്ടരാണ്. തന്റെ കുടുംബത്തിനും മുതലിനും പകരമായിട്ട് എന്നെ കാണാൻ സാധിച്ചെങ്കിലെന്ന് അവർ ഓരോരുത്തരും ആഗ്രഹിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 354, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَمَّارٍ رَضِيَ اللَّهُ عَنْهُ مَوْلَى بَنِي هَاشِمٍ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: كَمْ أَتَى لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ مَاتَ؟ فَقَالَ: مَا كُنْتُ أَحْسَبُ مِثْلَكَ مِنْ قَوْمِهِ يَخْفَى عَلَيْهِ ذَاكَ. قَالَ: قُلْتُ: إِنِّي قَدْ سَأَلْتُ النَّاسَ فَاخْتَلَفُوا عَلَيَّ، فَأَحْبَبْتُ أَنْ أَعْلَمَ قَوْلَكَ فِيهِ. قَالَ: أَتَحْسُبُ؟ قَالَ: قُلْتُ: نَعَمْ. قَالَ: أَمْسِكْ أَرْبَعِينَ بُعِثَ لَهَا، خَمْسَ عَشْرَةَ بِمَكَّةَ يَأْمَنُ وَيَخَافُ، وَعَشْرٌ مِنْ مُهَاجَرِهِ إِلَى الْمَدِينَةِ. وَقَدْ تَقَدَّمَ حَدِيثُ أَنَسٍ أَنَّهُ تُوُفِّيَ وَهُوَ ابْنُ سِتِّينَ سَنَةً. (م)', 'അമ്മാർ മൗലാ ബനീഹാശിം(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: വഫാതാകുമ്പോൾ റസൂൽ(സ)ക്ക് എത്ര വയസ്സായിരുന്നു? അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ)യുടെ സമൂഹത്തിൽപെട്ട താങ്കളെപ്പോലുള്ള ഒരാൾക്ക് അക്കാര്യം അവ്യക്തമാകുമെന്ന് ഞാൻ കരുതിയിരുന്നില്ല. അമ്മാർ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: നിശ്ചയം ഞാൻ ജനങ്ങളോടത് ചോദിച്ചു. എന്നാൽ അവർ എന്നോട് വ്യത്യസ്ത അഭിപ്രായങ്ങളാണ് പറഞ്ഞത്. അതിനാൽ അതേക്കുറിച്ച് താങ്കളുടെ അഭിപ്രായമെന്തെന്നറിയണമെന്ന് ഞാൻ ആഗ്രഹിച്ചു. ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു: താങ്കൾ കണക്ക് കൂട്ടുന്നില്ലേ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)ക്ക് പ്രവാചകത്വം ലഭിക്കുന്നതിന് മുമ്പുള്ള നാൽപത് വർഷം, നിർഭയനായും പേടിച്ചുകൊണ്ടും മക്കയിൽ ജീവിച്ച പതിനഞ്ച് വർഷം, തിരുമേനി(സ) മദീനയിലേക്ക് ഹിജ്റ പോയതു മുതലുള്ള പത്ത് വർഷം, ഇത്രയുമാണത്. നബി(സ) അറുപത് വയസ്സുള്ളപ്പോഴാണ് വഫാതായത് എന്ന് പറയുന്ന അനസ്(റ)വിന്റെ ഹദീസ് മുമ്പ് വന്നിട്ടുണ്ട്. (മു)', 'عَمَّارٍ', 'അമ്മാർ മൗലാ ബനീഹാശിം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ خَمْسٍ وَسِتِّينَ. (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): അറുപത്തിയഞ്ചാമത്തെ വയസ്സിലാണ് നബി(സ) വഫാതായത്. (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ وَهُوَ يَخْطُبُ: مَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ، وَأَبُو بَكْرٍ وَعُمَرُ، وَأَنَا ابْنُ ثَلَاثٍ وَسِتِّينَ. (م,ت)', 'മുആവിയതുബ്നു അബീ സുഫ്യാൻ(റ): പ്രസംഗിച്ചുകൊണ്ടിരിക്കെ അദ്ദേഹം പറഞ്ഞു: അറുപത്തിമൂന്ന് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും വഫാതായത്. എനിക്കിപ്പോൾ അറുപത്തിമൂന്ന് വയസ്സാണ്. (മു,തു)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീ സുഫ്യാൻ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أَوَّلُ النَّاسِ خُرُوجًا إِذَا بُعِثُوا، وَأَنَا خَطِيبُهُمْ إِذَا وَفَدُوا، وَأَنَا مُبَشِّرُهُمْ إِذَا أَيِسُوا، لِوَاءُ الْحَمْدِ يَوْمَئِذٍ بِيَدِي، وَأَنَا أَكْرَمُ وَلَدِ آدَمَ عَلَى رَبِّي وَلَا فَخْرَ". (م,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ പുനർജീവിപ്പിക്കപ്പെടുമ്പോൾ ആദ്യമായി പുറപ്പെടുന്നയാൾ ഞാനായിരിക്കും. അവർ ഒരുമിച്ചു കൂടിയാൽ അവരോട് പ്രസംഗിക്കുന്നയാൾ ഞാനായിരിക്കും. അവർ നിരാശരാകുമ്പോൾ സന്തോഷവാർത്ത അറിയിക്കുന്നവൻ ഞാനായിരിക്കും. അന്ന് ലിവാഉൽഹംദ് (പതാക) എന്റെ കയ്യിലാകും ഉണ്ടാവുക. എന്റെ രക്ഷിതാവിങ്കൽ ഏറ്റവും ശ്രേഷ്ഠനായ സന്തതി ഞാനാണ്. ഞാൻ അഹന്ത പറയുകയല്ല." ഹദീസ് ഹസനാണ്. (മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 355, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ، فَأُكْسَى حُلَّةً مِنْ حُلَلِ الْجَنَّةِ، ثُمَّ أَقُومُ عَنْ يَمِينِ الْعَرْشِ، لَيْسَ أَحَدٌ مِنَ الْخَلَائِقِ يَقُومُ ذَلِكَ الْمَقَامَ غَيْرِي". (ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭൂമിയിൽനിന്ന് ആദ്യമായി പുറത്തു വരുന്നയാൾ ഞാനായിരിക്കും. അങ്ങനെ ഞാൻ സ്വർഗ്ഗീയ വസ്ത്രങ്ങളിൽപെട്ട വസ്ത്രം ധരിക്കുകയും ശേഷം ഞാൻ അർശിന്റെ വലതു ഭാഗത്ത് നിൽക്കുകയും ചെയ്യും. ഞാനൊഴികെ സൃഷ്ടികളിൽപെട്ട ഒരാളും ആ സ്ഥാനത്ത് നിൽക്കുകയില്ല." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=4 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
